const e=[{id:"FC-01",ue:"2.5",front:"Quelle est la première question devant une douleur musculo-squelettique ?",back:"Évaluer la gravité et les red flags avant de conclure « mécanique ».",sources:["CORPUS-V1"],relatedIds:["2.5-RF-01"]},{id:"FC-02",ue:"2.5",front:"Que cherche-t-on avant un diagnostic ostéopathique ?",back:"Diagnostic différentiel et/ou d'exclusion.",sources:["CORPUS-V1","FSO-2023"],relatedIds:["2.5-RF-01"]},{id:"FC-03",ue:"2.5",front:"Quatre éléments neurologiques de base ?",back:"Force, sensibilité, réflexes, fonction/marche selon territoire.",sources:["CORPUS-V1"],relatedIds:["2.5-RF-07","2.5-RF-39"]},{id:"FC-04",ue:"2.5",front:"Comment une anamnèse à haute valeur aide-t-elle le raisonnement clinique ?",back:"Elle modifie la probabilité des hypothèses.",sources:["CORPUS-V1"],relatedIds:["2.5-RF-02"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-05",ue:"2.5",front:"Dans quels cas une image ne suffit-elle pas à expliquer les symptômes ?",back:"Quand sa corrélation avec les symptômes est faible ou que la question clinique n'est pas adaptée à l'imagerie.",sources:["CORPUS-V1","ACR-AC"],relatedIds:["2.5-RF-12","2.5-RF-14"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-06",ue:"2.5",front:"Quel signal impose de penser à la moelle ?",back:"Signes bilatéraux + marche/mains + signes pyramidaux.",sources:["CORPUS-V1"],relatedIds:["2.5-RF-08"]},{id:"FC-07",ue:"2.5",front:"Articulation aiguë chaude, gonflée et très douloureuse : quelle hypothèse ne pas manquer ?",back:"Penser notamment à l'infection articulaire ; ne pas présumer d'une simple surcharge.",sources:["CORPUS-V1","UE25-PACK-V2"],relatedIds:["2.5-RF-16"]},{id:"FC-08",ue:"2.5",front:"Que veut dire « red flag » ?",back:"Élément augmentant la suspicion d'une pathologie sérieuse et pouvant changer la conduite.",sources:["CORPUS-V1"],relatedIds:["2.5-RF-01"]},{id:"FC-09",ue:"2.5",front:"Un red flag = urgence automatique ?",back:"Non : il faut l'interpréter dans le contexte ; certains justifient une urgence, d'autres une évaluation ciblée.",sources:["CORPUS-V1"],relatedIds:["2.5-RF-01","2.5-RF-19"]},{id:"FC-10",ue:"2.5",front:"Rôle de l'ostéopathe en Suisse face à un diagnostic d'exclusion non clarifié ?",back:"Décider si une prise en charge est appropriée et orienter vers le professionnel adapté si nécessaire.",sources:["CORPUS-V1","FSO-2023"],relatedIds:["2.5-RF-01"]},{id:"FC-12",ue:"2.5",front:"Trois éléments évocateurs de queue de cheval ?",back:"Troubles sphinctériens + anesthésie en selle + déficit neurologique.",sources:["UE25-PACK-V2"],relatedIds:["2.5-RF-03"]},{id:"FC-13",ue:"2.5",front:"Une IRM anormale explique-t-elle forcément la douleur ?",back:"Non : une anomalie d'imagerie n'est pas la preuve de la cause de la douleur.",sources:["UE25-PACK-V2"],relatedIds:["2.5-RF-28"]},{id:"FC-14",ue:"2.5",front:"Douleur nocturne = toujours red flag ?",back:"Non ; interpréter dans son contexte.",sources:["UE25-PACK-V2"],relatedIds:["2.5-RF-04","2.5-RF-19"]},{id:"FC-16",ue:"2.5",front:"Ostéoporose = douleur permanente ?",back:"Non, souvent silencieuse jusqu’à fracture.",sources:["UE25-PACK-V2"],relatedIds:["2.5-RF-17"]},{id:"FC-17",ue:"2.5",front:"Douleur radiculaire = hernie discale certaine ?",back:"Non : rechercher un déficit moteur, la sensibilité et les réflexes dans le territoire avant de conclure.",sources:["UE25-PACK-V2"],relatedIds:["2.5-RF-07","2.5-RF-39"]},{id:"FC-18",ue:"2.5",front:"Question avant un examen complémentaire ?",back:"Quelle question clinique doit-il résoudre ?",sources:["UE25-PACK-V2"],relatedIds:["2.5-RF-27"]},{id:"FC-19",ue:"2.5",front:"Pourquoi tester la force dans une radiculopathie ?",back:"Rechercher et suivre un déficit moteur.",sources:["UE25-PACK-V2"],relatedIds:["2.5-RF-07","2.5-RF-26","2.5-RF-39"]},{id:"FC-20",ue:"2.5",front:"Finalité du raisonnement CRS ?",back:"Décision clinique justifiée : prise en charge, précautions, avis ou urgence.",sources:["UE25-PACK-V2"],relatedIds:["2.5-RF-29","2.5-RF-30"]},{id:"FC-21",ue:"2.5",front:"Mécanisme traumatique faible sur terrain fragile : quelle règle ?",back:"Suspicion de fracture : ne pas traiter comme une simple dysfonction mécanique avant clarification.",sources:["CORPUS-V1","UE25-PACK-V2"],relatedIds:["2.5-RF-05"]},{id:"FC-22",ue:"2.5",front:"Cervicalgie : quel type de signal fait sortir du cadre mécanique ?",back:"Un signe neurologique ou médullaire, un traumatisme, une fièvre ou un contexte tumoral.",sources:["CORPUS-V1","UE25-PACK-V2"],relatedIds:["2.5-RF-06","2.5-RF-08"]},{id:"FC-23",ue:"2.5",front:"Faiblesse à l'épaule : quelle question discriminante ?",back:"Déficit douloureux ou véritable déficit moteur ?",sources:["CORPUS-V1","UE25-PACK-V2"],relatedIds:["2.5-RF-09"]},{id:"FC-24",ue:"2.5",front:"Quel profil oriente vers une capsulite ?",back:"Limitation active ET passive, avec restriction marquée de la rotation externe.",sources:["CORPUS-V1","UE25-PACK-V2"],relatedIds:["2.5-RF-10"]},{id:"FC-25",ue:"2.5",front:"Genou : quels éléments imposent une évaluation médicale adaptée ?",back:"Incapacité d'appui, déformation, suspicion de fracture ou de luxation, blocage véritable, déficit neurovasculaire.",sources:["CORPUS-V1","UE25-PACK-V2"],relatedIds:["2.5-RF-11"]},{id:"FC-26",ue:"2.5",front:"Tendinopathie ou rupture tendineuse ?",back:"Tendinopathie : douleur liée à la charge, évolution progressive. Rupture : mécanisme brutal, déficit fonctionnel marqué.",sources:["CORPUS-V1","UE25-PACK-V2"],relatedIds:["2.5-RF-13"]},{id:"FC-27",ue:"2.5",front:"Quel pattern évoque une arthrite inflammatoire ?",back:"Raideur matinale importante, plusieurs articulations, gonflement, signes systémiques possibles.",sources:["CORPUS-V1","UE25-PACK-V2"],relatedIds:["2.5-RF-15"]},{id:"FC-28",ue:"2.5",front:"L'absence de fièvre exclut-elle une infection ostéo-articulaire ?",back:"Non : le contexte prime (immunodépression, chirurgie récente, douleur progressive inhabituelle).",sources:["CORPUS-V1","UE25-PACK-V2"],relatedIds:["2.5-RF-18"]},{id:"FC-29",ue:"2.5",front:"Devant une douleur référée possible, quelle question poser avant de traiter ?",back:"La distribution est-elle anatomiquement cohérente avec la structure à traiter ?",sources:["CORPUS-V1","UE25-PACK-V2"],relatedIds:["2.5-RF-20"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-30",ue:"2.5",front:"Douleur thoracique inhabituelle : que faire avant tout traitement manuel ?",back:"Une évaluation clinique : effort, dyspnée, malaise, irradiation, facteurs cardiovasculaires, fièvre.",sources:["CORPUS-V1","UE25-PACK-V2"],relatedIds:["2.5-RF-21"]},{id:"FC-31",ue:"2.5",front:"Quels descripteurs évoquent une douleur neuropathique ?",back:"Brûlure, décharges électriques, paresthésies, engourdissement, allodynie, hyperalgésie.",sources:["CORPUS-V1","UE25-PACK-V2"],relatedIds:["2.5-RF-25"]},{id:"FC-32",ue:"2.5",front:"Lombalgie cohérente et sans élément inquiétant : quelle décision ?",back:"Une prise en charge conservatrice proportionnée, avec réévaluation.",sources:["CORPUS-V1","UE25-PACK-V2"],relatedIds:["2.5-RF-02"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-33",ue:"2.5",front:"Lombalgie avec suspicion de cause spécifique : quelle décision ?",back:"Un avis médical et un bilan ciblé.",sources:["CORPUS-V1","UE25-PACK-V2"],relatedIds:["2.5-RF-02","2.5-RF-19"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-34",ue:"2.5",front:"Douleur de hanche : quelles origines envisager ?",back:"Intra-articulaire, péri-trochantérienne, rachis lombaire, bassin, neurologique, viscérale.",sources:["CORPUS-V1","UE25-PACK-V2"],relatedIds:["2.5-RF-22"]},{id:"FC-35",ue:"2.15",front:"Quelle différence sépare douleur neuropathique et douleur nociplastique ?",back:"Neuropathique : lésion démontrée du système somatosensoriel ; nociplastique : sans lésion démontrée.",sources:["IASP-TERM"],relatedIds:["2.15-RF-01"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-36",ue:"2.15",front:"3 signes d'alerte généraux devant une douleur persistante ?",back:"Perte de poids involontaire ; douleur nocturne non soulagée ; absence d'amélioration malgré prise en charge proportionnée.",sources:["NICE-NG12"],relatedIds:["2.15-RF-02"]},{id:"FC-37",ue:"2.6",front:"Douleur thoracique : quels éléments évoquent une cause cardiovasculaire plutôt que pariétale ?",back:"Oppression, irradiation bras/mâchoire, sueurs, lien à l'effort, facteurs de risque cardiovasculaire.",sources:["NICE-CG95"],relatedIds:["2.6-RF-01"]},{id:"FC-38",ue:"2.4",front:"Quel red flag de céphalée impose une orientation immédiate ?",back:"Une céphalée en coup de tonnerre, maximale en quelques secondes.",sources:["NICE-CG150"],relatedIds:["2.4-RF-01"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-39",ue:"2.4",front:"Vertige aigu : quels signes font craindre une cause centrale ?",back:"Vertige continu, céphalée nouvelle, trouble marqué de la marche, signes neurologiques associés, facteurs de risque vasculaire.",sources:["GRACE3-DIZZ"],relatedIds:["2.4-RF-02"]},{id:"FC-40",ue:"2.3",front:"Sepsis : quels signes évoquent une aggravation nécessitant une urgence ?",back:"Confusion nouvelle, fréquence respiratoire élevée, hypotension/tachycardie, peau marbrée, absence d'urines.",sources:["NICE-NG253"],relatedIds:["2.3-RF-01"]},{id:"FC-41",ue:"1.6",front:"Nerf médian : racines d'origine ?",back:"C5 à T1, via les cordons latéral et médial du plexus brachial.",sources:["NCBI-MEDIANNERVE"],relatedIds:["1.6-KN-01"]},{id:"FC-42",ue:"1.6",front:"Nerf médian dans le bras : combien de branches ?",back:"Aucune ; il ne donne ni branche musculaire ni branche cutanée dans le bras.",sources:["NCBI-MEDIANNERVE"],relatedIds:["1.6-KN-01"]},{id:"FC-43",ue:"1.6",front:"Muscles innervés par le nerf interosseux antérieur ?",back:"Long fléchisseur du pouce, moitié radiale du fléchisseur profond des doigts, carré pronateur.",sources:["NCBI-MEDIANNERVE"],relatedIds:["1.6-KN-01"]},{id:"FC-44",ue:"1.6",front:"Territoire sensitif palmaire du nerf médian ?",back:"Pouce, index, majeur et moitié radiale de l'annulaire.",sources:["NCBI-MEDIANNERVE"],relatedIds:["1.6-KN-01"]},{id:"FC-45",ue:"1.6",front:"Pourquoi la paume reste sensible dans un canal carpien classique ?",back:"La branche cutanée palmaire naît avant le tunnel carpien et le contourne en superficie.",sources:["NCBI-MEDIANNERVE"],relatedIds:["1.6-DX-01"]},{id:"FC-46",ue:"1.6",front:"Cordon postérieur : quelle sensibilité véhicule-t-il ?",back:"La sensibilité profonde consciente (proprioception, vibration) et le tact discriminatif ; décussation au bulbe.",sources:["NCBI-SPINALCORD-PHYSIO"],relatedIds:["1.6-KN-02"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-47",ue:"1.6",front:"Faisceau spinothalamique latéral : quelle sensibilité, où décusse-t-il ?",back:"Douleur et température ; décusse environ 2 segments au-dessus de son entrée médullaire.",sources:["NCBI-SPINALCORD-PHYSIO"],relatedIds:["1.6-KN-02"]},{id:"FC-48",ue:"1.6",front:"Corne latérale de la moelle : présente à quel niveau et pour quoi ?",back:"Niveau thoracique uniquement ; contient les neurones sympathiques préganglionnaires.",sources:["NCBI-SPINALCORD-PHYSIO"],relatedIds:["1.6-KN-02"]},{id:"FC-49",ue:"1.6",front:"Un signe de Babinski positif évoque l'atteinte de quel motoneurone ?",back:"Le motoneurone supérieur (syndrome pyramidal).",sources:["NCBI-UMN-SIGNS"],relatedIds:["1.6-DX-02"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-50",ue:"1.6",front:"Hypotonie, hyporéflexie, amyotrophie et fasciculations : quel syndrome ?",back:"Une atteinte du motoneurone inférieur (syndrome neurogène périphérique).",sources:["NCBI-LMN-LESION"],relatedIds:["1.6-DX-02"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-51",ue:"1.6",front:"Piège clinique du choc spinal ?",back:"Lésion aiguë du motoneurone supérieur peut être initialement flasque et aréflexique avant l'installation de la spasticité.",sources:["NCBI-UMN-SIGNS"],relatedIds:["1.6-DX-02"]},{id:"FC-52",ue:"1.6",front:"Niveau C6 : quel réflexe ostéotendineux explorer ?",back:"Le réflexe brachio-radial.",sources:["NCBI-CERVICAL-RADIC"],relatedIds:["1.6-EX-01"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-53",ue:"1.6",front:"Niveau S1 : quel réflexe ostéotendineux explorer ?",back:"Le réflexe achilléen.",sources:["NCBI-LUMBOSACRAL-RADIC"],relatedIds:["1.6-EX-01"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-54",ue:"1.6",front:"Niveau L4 : quel réflexe ostéotendineux explorer ?",back:"Le réflexe rotulien.",sources:["NCBI-LUMBOSACRAL-RADIC"],relatedIds:["1.6-EX-01"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-55",ue:"1.6",front:"Quels repères sensitifs cutanés correspondent aux niveaux thoraciques T4 et T10 ?",back:"T4 = mamelon ; T10 = ombilic.",sources:["NCBI-DERMATOMES"],relatedIds:["1.6-EX-01"]},{id:"FC-56",ue:"1.7",front:"Composants communs d'une articulation synoviale ?",back:"Cartilage hyalin, cavité articulaire, capsule fibreuse, liquide synovial, ligaments.",sources:["OPENSTAX-SYNOVIAL-JOINTS"],relatedIds:["1.7-KN-01"]},{id:"FC-57",ue:"1.7",front:"Type d'articulation de la hanche et de l'épaule ?",back:"Sphéroïde (énarthrose) : amplitude de mouvement la plus grande, multiaxiale.",sources:["OPENSTAX-SYNOVIAL-JOINTS"],relatedIds:["1.7-KN-01"]},{id:"FC-58",ue:"1.7",front:"Type d'articulation atlanto-axoïdienne (C1-C2) ?",back:"Pivot : uniaxial, rotation.",sources:["OPENSTAX-SYNOVIAL-JOINTS"],relatedIds:["1.7-KN-01"]},{id:"FC-59",ue:"1.7",front:"Levier le plus fréquent dans le corps humain, et pourquoi ?",back:"3e classe (effort entre appui et charge) ; privilégie amplitude et vitesse, au détriment de la force.",sources:["OPENSTAX-MUSCLE-LEVERS"],relatedIds:["1.7-KN-02"]},{id:"FC-60",ue:"1.7",front:"Exemple de levier de 1re classe dans le corps ?",back:"Muscles de la nuque tenant la tête : le rachis cervical est le point d'appui, entre effort et charge.",sources:["OPENSTAX-MUSCLE-LEVERS"],relatedIds:["1.7-KN-02"]},{id:"FC-61",ue:"1.7",front:"Différence synergiste vs antagoniste ?",back:"Synergiste aide le mouvement de l'agoniste ; antagoniste s'y oppose pour le contrôler.",sources:["LIBRETEXTS-BODY-LEVERS"],relatedIds:["1.7-KN-02"]},{id:"FC-62",ue:"1.7",front:"Théorie du glissement des filaments : que se passe-t-il ?",back:"L'actine glisse sur la myosine, raccourcissant le sarcomère sans que les filaments changent de longueur.",sources:["OPENSTAX-MUSCLE-CONTRACTION"],relatedIds:["1.7-KN-03"]},{id:"FC-63",ue:"1.7",front:"Principe de taille de Henneman ?",back:"Les petites unités motrices lentes sont recrutées avant les grandes unités rapides lors d'un effort croissant.",sources:["OPENSTAX-MOTOR-UNIT"],relatedIds:["1.7-KN-03"]},{id:"FC-64",ue:"1.7",front:"Deux mécanismes de gradation de la force musculaire ?",back:"Recrutement du nombre d'unités motrices ; sommation temporelle selon la fréquence de stimulation.",sources:["OPENSTAX-MOTOR-UNIT"],relatedIds:["1.7-KN-03"]},{id:"FC-65",ue:"1.7",front:"Loi de Wolff : que dit-elle ?",back:"L'os se renforce le long des lignes de contrainte mécanique habituelles et se résorbe en l'absence de charge.",sources:["NCBI-BONE-PHYSIO"],relatedIds:["1.7-KN-04"]},{id:"FC-66",ue:"1.7",front:"Pourquoi le tendon cicatrise-t-il lentement ?",back:"Tissu peu vascularisé et peu cellulaire (ténocytes).",sources:["NCBI-TENDON-ANATOMY"],relatedIds:["1.7-KN-04"]},{id:"FC-67",ue:"1.7",front:"Quelle cellule osseuse forme la matrice osseuse ?",back:"L'ostéoblaste.",sources:["NCBI-BONE-PHYSIO"],relatedIds:["1.7-KN-04"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-68",ue:"1.7",front:"Échelle MRC : que signifie un score de 3 ?",back:"Mouvement actif complet contre la pesanteur, sans résistance additionnelle.",sources:["NCBI-MRC-SCALE"],relatedIds:["1.7-EX-01"]},{id:"FC-69",ue:"1.7",front:"Échelle MRC : différence entre 4 et 5 ?",back:"4 = résistance modérée surmontée ; 5 = résistance maximale, force normale.",sources:["NCBI-MRC-SCALE"],relatedIds:["1.7-EX-01"]},{id:"FC-70",ue:"1.7",front:"Piège de cotation MRC en présence de douleur ?",back:"La douleur peut limiter l'effort sans traduire un vrai déficit : ne pas coter 4 par défaut.",sources:["NCBI-MRC-SCALE"],relatedIds:["1.7-EX-01"]},{id:"FC-71",ue:"1.7",front:"Distribution typique d'une faiblesse myogène (myopathie) ?",back:"Proximale et symétrique (ceintures), réflexes longtemps préservés, pas de fasciculation.",sources:["NCBI-MYOPATHY"],relatedIds:["1.7-DX-01"]},{id:"FC-72",ue:"1.7",front:"CK dans une atteinte myogène vs neurogène périphérique ?",back:"Souvent élevées dans la myopathie ; normales ou peu élevées dans l'atteinte neurogène périphérique.",sources:["NCBI-MYOPATHY"],relatedIds:["1.7-DX-01"]},{id:"FC-73",ue:"1.8",front:"Que produit la fermeture des valves auriculo-ventriculaires ?",back:"Le bruit B1, au début de la systole ventriculaire.",sources:["NCBI-CARDIAC-CYCLE"],relatedIds:["1.8-KN-01"]},{id:"FC-74",ue:"1.8",front:"Phase du cycle cardiaque où toutes les valves sont fermées et la pression monte ?",back:"La contraction isovolumétrique.",sources:["NCBI-CARDIAC-CYCLE"],relatedIds:["1.8-KN-01"]},{id:"FC-75",ue:"1.8",front:"Comment calcule-t-on le volume d'éjection systolique ?",back:"Volume télédiastolique moins volume télésystolique.",sources:["NCBI-CARDIAC-CYCLE"],relatedIds:["1.8-KN-01"]},{id:"FC-76",ue:"1.8",front:"Localisation du foyer aortique ?",back:"2e espace intercostal droit, bord sternal.",sources:["NCBI-HEART-SOUNDS"],relatedIds:["1.8-EX-01"]},{id:"FC-77",ue:"1.8",front:"Localisation du foyer tricuspide ?",back:"4e espace intercostal gauche, bord sternal.",sources:["NCBI-HEART-SOUNDS"],relatedIds:["1.8-EX-01"]},{id:"FC-78",ue:"1.8",front:"B3 physiologique : chez qui ?",back:"Enfant et athlète ; souvent pathologique après 40 ans, par exemple dans l'insuffisance cardiaque.",sources:["NCBI-HEART-SOUNDS"],relatedIds:["1.8-EX-01"]},{id:"FC-79",ue:"1.8",front:"Muscle inspiratoire principal et son innervation ?",back:"Diaphragme ; nerf phrénique, racines C3 à C5.",sources:["NCBI-LUNG-PHYSIO"],relatedIds:["1.8-KN-02"]},{id:"FC-80",ue:"1.8",front:"L'expiration au repos est-elle active ou passive ?",back:"Passive : retour élastique du poumon et de la paroi thoracique.",sources:["NCBI-LUNG-PHYSIO"],relatedIds:["1.8-KN-02"]},{id:"FC-81",ue:"1.8",front:"Que reflète la compliance pulmonaire ?",back:"L'élasticité du poumon et de la paroi thoracique ; variation de volume par unité de pression.",sources:["NCBI-LUNG-PHYSIO"],relatedIds:["1.8-KN-02"]},{id:"FC-82",ue:"2.6",front:"Quels seuils de fréquence respiratoire et de SpO2 signent une dyspnée grave ?",back:"Fréquence respiratoire > 30/min ; SpO2 < 90 %.",sources:["NCBI-DYSPNEA"],relatedIds:["2.6-RF-02"]},{id:"FC-83",ue:"2.6",front:"Quatre causes immédiatement menaçantes de dyspnée aiguë ?",back:"Pneumothorax sous tension, obstruction aiguë des voies aériennes, infarctus du myocarde, embolie pulmonaire massive.",sources:["NCBI-DYSPNEA"],relatedIds:["2.6-RF-02"]},{id:"FC-84",ue:"1.9",front:"Où a lieu l'essentiel de l'absorption des nutriments ?",back:"Intestin grêle (environ 90 %), grâce aux villosités et microvillosités.",sources:["NCBI-GI-PHYSIO"],relatedIds:["1.9-KN-01"]},{id:"FC-85",ue:"1.9",front:"Rôle des cellules pariétales gastriques ?",back:"Sécrètent l'acide chlorhydrique, maintenant le pH gastrique entre 1,5 et 2,0.",sources:["NCBI-GI-PHYSIO"],relatedIds:["1.9-KN-01"]},{id:"FC-86",ue:"1.9",front:"Quel plexus coordonne le péristaltisme ?",back:"Le plexus myentérique, au sein du système nerveux entérique.",sources:["NCBI-GI-PHYSIO"],relatedIds:["1.9-KN-01"]},{id:"FC-87",ue:"2.7",front:"Signe de Blumberg : que signifie-t-il ?",back:"Douleur au relâchement brusque de la palpation ; évoque une irritation péritonéale.",sources:["NCBI-ACUTE-ABDOMEN"],relatedIds:["2.7-RF-01"]},{id:"FC-88",ue:"2.7",front:"Masse abdominale pulsatile après 55 ans : y penser en priorité ?",back:"Anévrisme de l'aorte abdominale.",sources:["NCBI-ACUTE-ABDOMEN"],relatedIds:["2.7-RF-01"]},{id:"FC-89",ue:"2.7",front:"Différence défense vs contracture abdominale ?",back:"Défense = résistance musculaire volontaire ; contracture = rigidité involontaire, plus évocatrice de péritonite.",sources:["NCBI-ACUTE-ABDOMEN"],relatedIds:["2.7-RF-01"]},{id:"FC-90",ue:"2.7",front:"Ordre recommandé de l'examen abdominal ?",back:"Inspection, puis auscultation, puis palpation : palper avant d'ausculter peut modifier les bruits intestinaux.",sources:["NCBI-ABDOMINAL-EXAM"],relatedIds:["2.7-EX-01"]},{id:"FC-91",ue:"2.7",front:"Quelles sont la sensibilité et la spécificité de la douleur au point de McBurney pour l'appendicite ?",back:"Sensibilité 50 à 94 % ; spécificité 75 à 86 % (plages larges d'un manuel) : un signe d'orientation, qui ne confirme ni n'exclut.",sources:["NCBI-ABDOMINAL-EXAM"],relatedIds:["2.7-EX-01"]},{id:"FC-92",ue:"2.8",front:"Signe le plus prédictif du syndrome de la queue de cheval, et son piège ?",back:"Rétention urinaire indolore ; forte valeur prédictive mais signe déjà une atteinte tardive.",sources:["NCBI-CAUDA-EQUINA"],relatedIds:["2.8-RF-01"]},{id:"FC-93",ue:"2.8",front:"Fréquence de l'anesthésie en selle dans le syndrome de la queue de cheval ?",back:"Jusqu'à 93 % des cas.",sources:["NCBI-CAUDA-EQUINA"],relatedIds:["2.8-RF-01"]},{id:"FC-94",ue:"2.8",front:"Délai idéal de décompression chirurgicale en cas de syndrome de la queue de cheval ?",back:"Idéalement dans les 48 heures suivant la présentation.",sources:["NCBI-CAUDA-EQUINA"],relatedIds:["2.8-RF-01"]},{id:"FC-95",ue:"2.8",front:"Que signale une fièvre associée à une colique néphrétique ?",back:"Une possible pyélonéphrite obstructive (pyonéphrose), urgence de drainage.",sources:["NCBI-RENAL-COLIC"],relatedIds:["2.8-RF-02"]},{id:"FC-96",ue:"2.8",front:"Comportement typique du patient en colique néphrétique ?",back:"Agité, incapable de rester immobile, contrairement au patient avec péritonisme.",sources:["NCBI-RENAL-COLIC"],relatedIds:["2.8-RF-02"]},{id:"FC-97",ue:"2.8",front:"Signe d'examen évocateur de colique néphrétique ?",back:"Sensibilité costo-vertébrale à la palpation.",sources:["NCBI-RENAL-COLIC"],relatedIds:["2.8-RF-02"]},{id:"FC-98",ue:"1.9",front:"DFG normal chez l'adulte ?",back:"Environ 120 à 125 mL/min.",sources:["NCBI-RENAL-PHYSIO"],relatedIds:["1.9-KN-02"]},{id:"FC-99",ue:"1.9",front:"Trois couches de la barrière de filtration glomérulaire ?",back:"Endothélium fenêtré, membrane basale chargée négativement, fentes de filtration entre podocytes.",sources:["NCBI-RENAL-PHYSIO"],relatedIds:["1.9-KN-02"]},{id:"FC-100",ue:"1.9",front:"Deux fonctions endocrines du rein, au-delà de la filtration ?",back:"Production d'érythropoïétine ; activation de la vitamine D.",sources:["NCBI-RENAL-PHYSIO"],relatedIds:["1.9-KN-02"]},{id:"FC-101",ue:"1.9",front:"Quelle hormone hypothalamique stimule la sécrétion de TSH ?",back:"La TRH (thyrotropin-releasing hormone).",sources:["NCBI-THYROID-AXIS"],relatedIds:["1.9-KN-03"]},{id:"FC-102",ue:"1.9",front:"Quelles hormones freinent la sécrétion de TSH et de TRH par rétrocontrôle ?",back:"T3 et T4, les hormones thyroïdiennes.",sources:["NCBI-THYROID-AXIS"],relatedIds:["1.9-KN-03"]},{id:"FC-103",ue:"1.9",front:"Que signale une TSH basse associée à une T4 libre élevée ?",back:"Une hyperthyroïdie, par rétrocontrôle négatif exagéré sur l'axe.",sources:["NCBI-THYROID-AXIS"],relatedIds:["1.9-KN-03"]},{id:"FC-104",ue:"1.9",front:"Quelle enzyme organifie l'iode sur la thyroglobuline ?",back:"La thyroperoxydase (TPO).",sources:["NCBI-THYROID-HORMONE"],relatedIds:["1.9-KN-04"]},{id:"FC-105",ue:"1.9",front:"Dans quel rapport la thyroïde libère-t-elle T4 et T3 ?",back:"Environ 80 % de T4 pour 20 % de T3.",sources:["NCBI-THYROID-HORMONE"],relatedIds:["1.9-KN-04"]},{id:"FC-106",ue:"1.9",front:"Quelle est la forme biologiquement active de l'hormone thyroïdienne au niveau cellulaire ?",back:"La T3, en grande partie issue de la conversion périphérique du T4.",sources:["NCBI-THYROID-HORMONE"],relatedIds:["1.9-KN-04"]},{id:"FC-107",ue:"2.8",front:"Quel terrain doit faire évoquer un anévrisme de l'aorte abdominale devant une douleur de flanc ?",back:"Homme de plus de 60 ans, tabagique, hypertendu.",sources:["NCBI-AAA"],relatedIds:["2.8-RF-03"]},{id:"FC-108",ue:"2.8",front:"Quel signe d'examen évoque une rupture d'anévrisme aortique plutôt qu'une colique néphrétique ?",back:"Masse abdominale pulsatile avec instabilité hémodynamique.",sources:["NCBI-AAA"],relatedIds:["2.8-RF-03"]},{id:"FC-109",ue:"2.8",front:"Que traduit une hypotension avec tachycardie chez un patient au profil vasculaire présentant une douleur de flanc ?",back:"Une possible rupture d'anévrisme de l'aorte abdominale, urgence vitale.",sources:["NCBI-AAA"],relatedIds:["2.8-RF-03"]},{id:"FC-110",ue:"2.4",front:"Quel profil de vertige oriente vers une cause centrale ?",back:"Continu, non positionnel, avec ataxie ou signe neurologique focal.",sources:["GRACE3-DIZZ"],relatedIds:["2.4-RF-02"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-111",ue:"2.4",front:"Vertige aigu et impossibilité de tenir debout sans aide : que suspecter ?",back:"Une cause centrale : orientation en urgence.",sources:["GRACE3-DIZZ"],relatedIds:["2.4-RF-02"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-112",ue:"2.15",front:"Quelle douleur rachidienne, chez un patient aux antécédents de cancer, évoque une métastase ?",back:"Douleur nocturne progressive non soulagée par le repos, avec perte de poids.",sources:["NICE-NG12"],relatedIds:["2.15-RF-02"]},{id:"FC-113",ue:"2.15",front:"Quel signe impose une orientation urgente devant une lombalgie chez un patient aux antécédents oncologiques ?",back:"Un déficit neurologique focal, même discret.",sources:["NICE-NG12"],relatedIds:["2.15-RF-02"]},{id:"FC-114",ue:"2.9",front:"Que veulent dire les cinq lettres de la règle ABCDE pour une lésion pigmentée ?",back:"Asymétrie, Bordure irrégulière, Couleur hétérogène, Diamètre > 6 mm, Évolution.",sources:["NCBI-MELANOMA"],relatedIds:["2.9-RF-01"]},{id:"FC-115",ue:"2.9",front:"Quel examen confirme le diagnostic devant une lésion cutanée suspecte de mélanome ?",back:"Une biopsie, de préférence excisionnelle.",sources:["NCBI-MELANOMA"],relatedIds:["2.9-RF-01"]},{id:"FC-116",ue:"2.10",front:"Quel test cutané simple recherche un purpura non blanchissant ?",back:"Le test de la vitropression (glass test).",sources:["NICE-NG240"],relatedIds:["2.10-RF-01"]},{id:"FC-117",ue:"2.10",front:"Quelle taille de lésion purpurique est retenue comme seuil d'alerte pour une méningococcémie ?",back:"Plus de 2 mm.",sources:["NICE-NG240"],relatedIds:["2.10-RF-01"]},{id:"FC-118",ue:"2.6",front:"Quels signes cliniques associés à une dyspnée brutale évoquent une thrombose veineuse profonde ?",back:"Mollet tuméfié, sensible et érythémateux, souvent unilatéral.",sources:["NCBI-PE"],relatedIds:["2.6-RF-02"]},{id:"FC-119",ue:"2.6",front:"Quelle est la principale cause de décès dans une embolie pulmonaire sévère ?",back:"La défaillance du ventricule droit par surcharge de pression aiguë.",sources:["NCBI-PE"],relatedIds:["2.6-RF-02"]},{id:"FC-120",ue:"2.9",front:"Combien de temps la douleur prodromique du zona précède-t-elle en moyenne l'éruption ?",back:"En moyenne 48 heures, de 1 à 10 jours.",sources:["NCBI-HERPES-ZOSTER"],relatedIds:["2.9-RF-02"]},{id:"FC-121",ue:"2.9",front:"Que doit faire évoquer une atteinte zostérienne multidermatomale chez un adulte immunocompétent ?",back:"Une immunodépression sous-jacente à rechercher.",sources:["NCBI-HERPES-ZOSTER"],relatedIds:["2.9-RF-02"]},{id:"FC-122",ue:"1.5",front:"Position anatomique de référence : description ?",back:"Debout, pieds à largeur des épaules et parallèles, orteils vers l'avant, membres supérieurs écartés de chaque côté, paumes vers l'avant.",sources:["OPENSTAX-AP-1-6"],relatedIds:["1.5-KN-01"]},{id:"FC-123",ue:"1.5",front:"Proximal vs distal : définition ?",back:"Proximal = plus proche du point d'attache d'un membre ; distal = plus loin. Ne s'applique qu'aux membres.",sources:["OPENSTAX-AP-1-6"],relatedIds:["1.5-KN-01"]},{id:"FC-124",ue:"1.5",front:"Plan sagittal : que divise-t-il ?",back:"Le corps verticalement en portion droite et portion gauche.",sources:["OPENSTAX-AP-1-6"],relatedIds:["1.5-KN-01"]},{id:"FC-125",ue:"1.5",front:"Plan frontal (coronal) : que divise-t-il ?",back:"Le corps en portion antérieure et portion postérieure.",sources:["OPENSTAX-AP-1-6"],relatedIds:["1.5-KN-01"]},{id:"FC-126",ue:"1.5",front:"Plan transverse : que divise-t-il ?",back:"Le corps horizontalement en portion supérieure et portion inférieure.",sources:["OPENSTAX-AP-1-6"],relatedIds:["1.5-KN-01"]},{id:"FC-127",ue:"1.5",front:"Cavité dorsale : que contient-elle ?",back:"La cavité crânienne (encéphale) et la cavité vertébrale (moelle spinale).",sources:["OPENSTAX-AP-1-6"],relatedIds:["1.5-KN-01"]},{id:"FC-128",ue:"1.5",front:"Cavité ventrale : que contient-elle ?",back:"La cavité thoracique et la cavité abdomino-pelvienne.",sources:["OPENSTAX-AP-1-6"],relatedIds:["1.5-KN-01"]},{id:"FC-129",ue:"1.5",front:"Niveaux d'organisation du corps humain : les six niveaux ?",back:"Chimique, cellulaire, tissulaire, organe, système organique, organisme.",sources:["OPENSTAX-AP-1-2"],relatedIds:["1.5-KN-02"]},{id:"FC-130",ue:"1.5",front:"Définition d'un organe (niveau d'organisation) ?",back:"Structure anatomiquement distincte composée d'au moins deux types de tissus, avec une fonction physiologique propre.",sources:["OPENSTAX-AP-1-2"],relatedIds:["1.5-KN-02"]},{id:"FC-131",ue:"1.5",front:"Définition d'un tissu (niveau d'organisation) ?",back:"Groupe de nombreuses cellules similaires qui coopèrent pour une fonction spécifique.",sources:["OPENSTAX-AP-1-2"],relatedIds:["1.5-KN-02"]},{id:"FC-132",ue:"1.5",front:"Fonction du système lymphatique ?",back:"Retourne le liquide interstitiel vers le sang et défend contre les agents pathogènes.",sources:["OPENSTAX-AP-1-2"],relatedIds:["1.5-KN-03"]},{id:"FC-133",ue:"1.5",front:"Fonction du système tégumentaire ?",back:"Enveloppe les structures internes et porte des récepteurs sensoriels.",sources:["OPENSTAX-AP-1-2"],relatedIds:["1.5-KN-03"]},{id:"FC-134",ue:"1.5",front:"Fonction du système endocrinien ?",back:"Sécrète des hormones qui régulent les processus corporels.",sources:["OPENSTAX-AP-1-2"],relatedIds:["1.5-KN-03"]},{id:"FC-135",ue:"1.5",front:"Set point, en homéostasie : définition ?",back:"Valeur physiologique de référence autour de laquelle fluctue l'intervalle normal d'un paramètre.",sources:["OPENSTAX-AP-1-5"],relatedIds:["1.5-KN-04"]},{id:"FC-136",ue:"1.5",front:"Boucle de rétroaction homéostatique : trois composants ?",back:"Capteur (récepteur), centre de contrôle, effecteur.",sources:["OPENSTAX-AP-1-5"],relatedIds:["1.5-KN-04"]},{id:"FC-137",ue:"1.5",front:"Rétroaction négative : effet sur le paramètre ?",back:"Inverse un écart par rapport au set point ; ramène le paramètre dans l'intervalle normal.",sources:["OPENSTAX-AP-1-5"],relatedIds:["1.5-KN-04"]},{id:"FC-138",ue:"1.5",front:"Rétroaction positive : effet sur le paramètre ?",back:"Amplifie un changement au lieu de l'inverser ; ne survient que s'il existe un point d'arrêt défini.",sources:["OPENSTAX-AP-1-5"],relatedIds:["1.5-KN-04"]},{id:"FC-139",ue:"1.5",front:"Exemple physiologique de rétroaction positive ?",back:"Étirement du col utérin pendant l'accouchement, amplifié par l'ocytocine jusqu'à la naissance.",sources:["OPENSTAX-AP-1-5"],relatedIds:["1.5-KN-04"]},{id:"FC-140",ue:"1.5",front:"Tissu épithélial : fonction principale ?",back:"Recouvre les surfaces externes, tapisse les cavités internes, forme certaines glandes.",sources:["OPENSTAX-AP-4-1"],relatedIds:["1.5-KN-05"]},{id:"FC-141",ue:"1.5",front:"Tissu conjonctif : fonction principale ?",back:"Lie cellules et organes ; assure protection, soutien et intégration du corps.",sources:["OPENSTAX-AP-4-1"],relatedIds:["1.5-KN-05"]},{id:"FC-142",ue:"1.5",front:"Tissu musculaire : les trois formes ?",back:"Squelettique, lisse, cardiaque.",sources:["OPENSTAX-AP-4-1"],relatedIds:["1.5-KN-05"]},{id:"FC-143",ue:"1.5",front:"Tissu nerveux : fonction principale ?",back:"Propage des signaux électrochimiques (influx nerveux) entre régions du corps.",sources:["OPENSTAX-AP-4-1"],relatedIds:["1.5-KN-05"]},{id:"FC-144",ue:"1.4",front:"Formule du torque (moment de force) ?",back:"τ = r × F × sin θ (r = distance au pivot, F = force, θ = angle).",sources:["OPENSTAX-CP-9-2"],relatedIds:["1.4-KN-01"]},{id:"FC-145",ue:"1.4",front:"Deuxième condition d'équilibre : quelle grandeur doit être nulle ?",back:"La somme des torques externes appliqués au système.",sources:["OPENSTAX-CP-9-2"],relatedIds:["1.4-KN-01"]},{id:"FC-146",ue:"1.4",front:"Torque : effet d'un angle θ = 0° entre force et bras de levier ?",back:"Torque nul, quelle que soit l'intensité de la force.",sources:["OPENSTAX-CP-9-2"],relatedIds:["1.4-KN-01"]},{id:"FC-147",ue:"1.4",front:"Trois composants d'un système de levier ?",back:"Bras rigide (os), pivot (articulation), force motrice (muscle).",sources:["LIBRETEXTS-LEVERS"],relatedIds:["1.4-KN-02"]},{id:"FC-148",ue:"1.4",front:"Levier de 3e classe : position de la force ?",back:"Entre le pivot et la charge — désavantage mécanique, avantage de vitesse/amplitude.",sources:["LIBRETEXTS-LEVERS"],relatedIds:["1.4-KN-02"]},{id:"FC-149",ue:"1.4",front:"Levier de 2e classe : position de la charge ?",back:"Entre le pivot et la force — avantage mécanique.",sources:["LIBRETEXTS-LEVERS"],relatedIds:["1.4-KN-02"]},{id:"FC-150",ue:"1.4",front:"Levier de 1re classe : exemple corporel ?",back:"Extension de l'avant-bras par le triceps brachial, coude en pivot.",sources:["LIBRETEXTS-LEVERS"],relatedIds:["1.4-KN-02"]},{id:"FC-151",ue:"1.4",front:"Classe de levier la plus fréquente dans le corps ?",back:"Troisième classe — privilégie vitesse et amplitude au détriment de la force.",sources:["LIBRETEXTS-LEVERS"],relatedIds:["1.4-KN-02"]},{id:"FC-152",ue:"1.4",front:"Flexion : effet sur l'angle articulaire ?",back:"Diminue l'angle entre deux os (plan sagittal).",sources:["OPENSTAX-AP-9-5"],relatedIds:["1.4-KN-03"]},{id:"FC-153",ue:"1.4",front:"Abduction : direction du mouvement ?",back:"Éloigne le membre de la ligne médiane du corps (plan frontal).",sources:["OPENSTAX-AP-9-5"],relatedIds:["1.4-KN-03"]},{id:"FC-154",ue:"1.4",front:"Rotation médiale (interne) : définition ?",back:"Amène la face antérieure du membre vers la ligne médiane (plan transverse).",sources:["OPENSTAX-AP-9-5"],relatedIds:["1.4-KN-03"]},{id:"FC-155",ue:"1.4",front:"Pronation de l'avant-bras : position de la paume ?",back:"Paume vers l'arrière, radius et ulna croisés en X.",sources:["OPENSTAX-AP-9-5"],relatedIds:["1.4-KN-03"]},{id:"FC-156",ue:"1.4",front:"Dorsiflexion du pied : mouvement ?",back:"Rapproche le dos du pied de la face antérieure de la jambe.",sources:["OPENSTAX-AP-9-5"],relatedIds:["1.4-KN-03"]},{id:"FC-157",ue:"1.4",front:"Inversion du pied : définition ?",back:"Oriente la plante du pied vers la ligne médiane.",sources:["OPENSTAX-AP-9-5"],relatedIds:["1.4-KN-03"]},{id:"FC-158",ue:"1.4",front:"Circumduction : définition ?",back:"Mouvement circulaire combinant flexion, abduction, extension et adduction successives.",sources:["OPENSTAX-AP-9-5"],relatedIds:["1.4-KN-03"]},{id:"FC-159",ue:"1.4",front:"Bonne posture debout : torque du poids du tronc sur les hanches ?",back:"Nul, car le centre de gravité du tronc reste au-dessus du pivot des hanches.",sources:["OPENSTAX-CP-9-6"],relatedIds:["1.4-KN-04"]},{id:"FC-160",ue:"1.4",front:"Flexion du tronc en avant : effet sur le bras de levier du poids du tronc ?",back:"Il s'allonge, augmentant le torque que les muscles spinaux doivent compenser.",sources:["OPENSTAX-CP-9-6"],relatedIds:["1.4-KN-04"]},{id:"FC-161",ue:"1.4",front:"Stress et strain, en biomécanique tissulaire : définitions ?",back:"Stress = force appliquée au tissu ; strain = déformation qui en résulte.",sources:["LIBRETEXTS-TENDON-BONE"],relatedIds:["1.4-KN-05"]},{id:"FC-162",ue:"1.4",front:"Zone d'allure (toe region) d'un tendon : que s'y passe-t-il ?",back:"Les fibres de collagène ondulées s'alignent progressivement dans l'axe de traction.",sources:["LIBRETEXTS-TENDON-BONE"],relatedIds:["1.4-KN-05"]},{id:"FC-163",ue:"1.4",front:"Zone plastique d'un tissu conjonctif : conséquence ?",back:"Déformation permanente correspondant à une lésion tissulaire.",sources:["LIBRETEXTS-TENDON-BONE"],relatedIds:["1.4-KN-05"]},{id:"FC-164",ue:"1.4",front:"Os vs tendon : quel tissu est le plus rigide et le plus fragile ?",back:"L'os — module d'élasticité plus élevé, mais tolère moins de déformation avant rupture.",sources:["LIBRETEXTS-TENDON-BONE"],relatedIds:["1.4-KN-05"]},{id:"FC-165",ue:"1.1",front:"Composant de la membrane plasmique qui module sa fluidité ?",back:"Le cholestérol, intercalé dans la bicouche de phospholipides.",sources:["OPENSTAX-AP-3-1"],relatedIds:["1.1-KN-01"]},{id:"FC-166",ue:"1.1",front:"Glycocalyx : définition ?",back:"Enveloppe de glycoprotéines et glucides à la surface cellulaire, impliquée dans la reconnaissance cellulaire.",sources:["OPENSTAX-AP-3-1"],relatedIds:["1.1-KN-01"]},{id:"FC-167",ue:"1.1",front:"Perméabilité sélective : que traverse librement la bicouche lipidique ?",back:"Les petites molécules non polaires (O2, CO2) et les molécules hydrophobes.",sources:["OPENSTAX-AP-3-1"],relatedIds:["1.1-KN-01"]},{id:"FC-168",ue:"1.1",front:"Diffusion simple vs diffusion facilitée : différence ?",back:"Diffusion simple = directe à travers la bicouche ; diffusion facilitée = via protéine canal/transporteur. Les deux sont passives.",sources:["OPENSTAX-AP-3-1"],relatedIds:["1.1-KN-02"]},{id:"FC-169",ue:"1.1",front:"Osmose : quel est le sens du mouvement de l'eau à travers une membrane semi-perméable ?",back:"Diffusion de l'eau vers la zone la plus concentrée en soluté.",sources:["OPENSTAX-AP-3-1"],relatedIds:["1.1-KN-02"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-170",ue:"1.1",front:"Solution hypotonique : effet sur la cellule ?",back:"La cellule gonfle par entrée d'eau, avec risque de rupture.",sources:["OPENSTAX-AP-3-1"],relatedIds:["1.1-KN-02"]},{id:"FC-171",ue:"1.1",front:"Solution hypertonique : effet sur la cellule ?",back:"La cellule se rétracte par sortie d'eau.",sources:["OPENSTAX-AP-3-1"],relatedIds:["1.1-KN-02"]},{id:"FC-172",ue:"1.1",front:"Pompe sodium-potassium : mouvement par ATP consommé ?",back:"3 ions sodium sortent, 2 ions potassium entrent.",sources:["OPENSTAX-AP-3-1"],relatedIds:["1.1-KN-02"]},{id:"FC-173",ue:"1.1",front:"Phagocytose vs pinocytose : différence ?",back:"Phagocytose = engloutit de grosses particules ; pinocytose = engloutit des liquides/substances dissoutes.",sources:["OPENSTAX-AP-3-1"],relatedIds:["1.1-KN-02"]},{id:"FC-174",ue:"1.1",front:"Fonction du noyau cellulaire ?",back:"Stocke l'ADN, l'information génétique de la cellule.",sources:["OPENSTAX-AP-3-2"],relatedIds:["1.1-KN-03"]},{id:"FC-175",ue:"1.1",front:"Fonction de la mitochondrie ?",back:"Convertit les nutriments en ATP par la respiration cellulaire.",sources:["OPENSTAX-AP-3-2"],relatedIds:["1.1-KN-03"]},{id:"FC-176",ue:"1.1",front:"Fonction du réticulum endoplasmique lisse ?",back:"Synthèse des lipides et hormones stéroïdiennes, régulation du calcium, détoxification.",sources:["OPENSTAX-AP-3-2"],relatedIds:["1.1-KN-03"]},{id:"FC-177",ue:"1.1",front:"Quel est le rôle des lysosomes dans la cellule ?",back:"Dégrader et digérer les composants cellulaires devenus inutiles.",sources:["OPENSTAX-AP-3-2"],relatedIds:["1.1-KN-03"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-178",ue:"1.1",front:"Quel est le rôle des ribosomes dans la cellule ?",back:"Site de synthèse des protéines à partir de l'ARN messager.",sources:["OPENSTAX-AP-3-2"],relatedIds:["1.1-KN-03"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-179",ue:"1.1",front:"Dogme central de la biologie moléculaire : flux d'information ?",back:"ADN → ARN messager (transcription) → protéine (traduction).",sources:["OPENSTAX-AP-3-4"],relatedIds:["1.1-KN-04"]},{id:"FC-180",ue:"1.1",front:"Qu'est-ce qu'un codon de l'ARN messager ?",back:"Séquence de trois bases de l'ARN messager codant un acide aminé.",sources:["OPENSTAX-AP-3-4"],relatedIds:["1.1-KN-04"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-181",ue:"1.1",front:"Qu'est-ce qu'un anticodon de l'ARN de transfert ?",back:"Séquence de bases de l'ARN de transfert, complémentaire d'un codon.",sources:["OPENSTAX-AP-3-4"],relatedIds:["1.1-KN-04"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-182",ue:"1.1",front:"Rôle de l'ARN de transfert (ARNt) ?",back:"Achemine l'acide aminé correspondant jusqu'au ribosome pendant la traduction.",sources:["OPENSTAX-AP-3-4"],relatedIds:["1.1-KN-04"]},{id:"FC-183",ue:"1.1",front:"ATP : rôle dans la cellule ?",back:"Monnaie énergétique cellulaire ; sa dégradation libère l'énergie utilisée pour le travail cellulaire.",sources:["OPENSTAX-BIO-7"],relatedIds:["1.1-KN-05"]},{id:"FC-184",ue:"1.1",front:"Glycolyse : bilan net en ATP ?",back:"Gain net de deux ATP et deux NADH, dans le cytoplasme.",sources:["OPENSTAX-BIO-7"],relatedIds:["1.1-KN-05"]},{id:"FC-185",ue:"1.1",front:"Chaîne de transport d'électrons : localisation et rôle ?",back:"Membrane mitochondriale interne ; produit l'essentiel de l'ATP cellulaire, avec l'oxygène comme accepteur final.",sources:["OPENSTAX-BIO-7"],relatedIds:["1.1-KN-05"]},{id:"FC-186",ue:"1.3",front:"Épithélium : critère de classification selon la forme cellulaire ?",back:"Pavimenteuse (aplatie), cubique (aussi large que haute) ou cylindrique (plus haute que large).",sources:["OPENSTAX-AP-4-2"],relatedIds:["1.3-KN-01"]},{id:"FC-187",ue:"1.3",front:"Différence entre épithélium simple et stratifié ?",back:"Simple : une seule couche, toutes les cellules touchent la lame basale ; stratifié : plusieurs couches, seule la couche basale la touche.",sources:["OPENSTAX-AP-4-2"],relatedIds:["1.3-KN-01"]},{id:"FC-188",ue:"1.3",front:"Épithélium pseudo-stratifié : particularité ?",back:"Une seule couche de cellules de hauteurs inégales, donnant une fausse apparence de stratification.",sources:["OPENSTAX-AP-4-2"],relatedIds:["1.3-KN-01"]},{id:"FC-189",ue:"1.3",front:"Glande exocrine vs endocrine ?",back:"Exocrine : sécrète via un canal. Endocrine : sécrète directement dans le sang, sans canal.",sources:["OPENSTAX-AP-4-2"],relatedIds:["1.3-KN-01"]},{id:"FC-190",ue:"1.3",front:"Trois composants de la matrice extracellulaire du tissu conjonctif ?",back:"Substance fondamentale amorphe, fibres protéiques (collagène, élastique, réticulaire), et cellules dispersées.",sources:["OPENSTAX-AP-4-3"],relatedIds:["1.3-KN-02"]},{id:"FC-191",ue:"1.3",front:"Trois grandes familles de tissu conjonctif ?",back:"Conjonctif proprement dit (lâche/dense), tissu de soutien (cartilage, os), tissu conjonctif fluide (sang, lymphe).",sources:["OPENSTAX-AP-4-3"],relatedIds:["1.3-KN-02"]},{id:"FC-192",ue:"1.3",front:"Pourquoi le sang est-il un tissu conjonctif ?",back:"Sa matrice extracellulaire est liquide : le plasma.",sources:["OPENSTAX-AP-4-3"],relatedIds:["1.3-KN-02"]},{id:"FC-193",ue:"1.3",front:"Différence conjonctif lâche vs dense ?",back:"Lâche : riche en substance fondamentale, souple. Dense : riche en fibres de collagène organisées (tendons, ligaments).",sources:["OPENSTAX-AP-4-3"],relatedIds:["1.3-KN-02"]},{id:"FC-194",ue:"1.3",front:"Muscle squelettique : caractéristiques histologiques ?",back:"Fibres longues cylindriques, striées, plusieurs noyaux périphériques, contraction volontaire.",sources:["OPENSTAX-AP-4-4"],relatedIds:["1.3-KN-03"]},{id:"FC-195",ue:"1.3",front:"Muscle cardiaque : caractéristiques histologiques ?",back:"Fibres courtes ramifiées, striées, un seul noyau central, disques intercalaires, contraction involontaire.",sources:["OPENSTAX-AP-4-4"],relatedIds:["1.3-KN-03"]},{id:"FC-196",ue:"1.3",front:"Muscle lisse : caractéristiques histologiques ?",back:"Fibres courtes fusiformes, sans strie visible, un seul noyau, contraction involontaire.",sources:["OPENSTAX-AP-4-4"],relatedIds:["1.3-KN-03"]},{id:"FC-197",ue:"1.3",front:"Trois composants structuraux du neurone ?",back:"Corps cellulaire (noyau, organites), dendrites (réception), axone (conduction de l’influx).",sources:["OPENSTAX-AP-4-5"],relatedIds:["1.3-KN-03"]},{id:"FC-198",ue:"1.3",front:"Gastrulation : que produit-elle ?",back:"Transforme le disque embryonnaire à deux couches en disque à trois feuillets germinatifs, en semaine 3.",sources:["OPENSTAX-AP-28-2"],relatedIds:["1.3-KN-04"]},{id:"FC-199",ue:"1.3",front:"Quels tissus et organes dérivent de l'ectoderme ?",back:"Système nerveux central et périphérique, organes sensoriels, épiderme, phanères.",sources:["OPENSTAX-AP-28-2"],relatedIds:["1.3-KN-04"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-200",ue:"1.3",front:"Quels tissus et organes dérivent du mésoderme ?",back:"Squelette, muscles, tissu conjonctif, cœur, vaisseaux sanguins, reins.",sources:["OPENSTAX-AP-28-2"],relatedIds:["1.3-KN-04"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-201",ue:"1.3",front:"Quels tissus et organes dérivent de l'endoderme ?",back:"Muqueuse épithéliale du tube digestif, foie, pancréas, poumons.",sources:["OPENSTAX-AP-28-2"],relatedIds:["1.3-KN-04"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-202",ue:"1.3",front:"Caryotype humain normal : composition ?",back:"22 paires d'autosomes + 1 paire de chromosomes sexuels (XX ou XY), soit 23 paires.",sources:["OPENSTAX-AP-28-7"],relatedIds:["1.3-KN-05"]},{id:"FC-203",ue:"1.3",front:"Hérédité autosomique dominante : exemple et risque de transmission ?",back:"Ex. maladie de Huntington ; un parent atteint transmet l'allèle avec 50% de risque par enfant.",sources:["OPENSTAX-AP-28-7"],relatedIds:["1.3-KN-05"]},{id:"FC-204",ue:"1.3",front:"Hérédité autosomique récessive : exemple ?",back:"Mucoviscidose ; nécessite deux allèles défectueux, porteurs hétérozygotes asymptomatiques.",sources:["OPENSTAX-AP-28-7"],relatedIds:["1.3-KN-05"]},{id:"FC-205",ue:"1.3",front:"Hérédité liée à l’X : pourquoi les hommes sont-ils plus souvent atteints ?",back:"Ils n'ont qu'un chromosome X (XY) ; une seule copie récessive suffit à exprimer le trait, ex. daltonisme.",sources:["OPENSTAX-AP-28-7"],relatedIds:["1.3-KN-05"]},{id:"FC-206",ue:"1.2",front:"Quelle cellule est à l'origine de tous les éléments figurés du sang ?",back:"La cellule souche hématopoïétique de la moelle osseuse rouge.",sources:["OPENSTAX-AP-18-2"],relatedIds:["1.2-KN-01"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-207",ue:"1.2",front:"Quelle lignée produit les érythrocytes, les plaquettes, les granulocytes et les monocytes ?",back:"La lignée myéloïde.",sources:["OPENSTAX-AP-18-2"],relatedIds:["1.2-KN-01"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-208",ue:"1.2",front:"Quelle lignée produit les lymphocytes T, B et les cellules NK ?",back:"La lignée lymphoïde.",sources:["OPENSTAX-AP-18-2"],relatedIds:["1.2-KN-01"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-209",ue:"1.2",front:"Pourquoi une atteinte de la moelle peut-elle toucher plusieurs lignées sanguines à la fois ?",back:"Toutes les lignées dérivent d'une même cellule souche médullaire.",sources:["OPENSTAX-AP-18-2"],relatedIds:["1.2-KN-01"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-210",ue:"1.2",front:"Quel leucocyte, majoritaire parmi les leucocytes (50-70 %), est un phagocyte rapide des bactéries ?",back:"Le neutrophile.",sources:["OPENSTAX-AP-18-4"],relatedIds:["1.2-KN-02"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-211",ue:"1.2",front:"Quel leucocyte lutte contre les parasites et régule l'inflammation ?",back:"L'éosinophile.",sources:["OPENSTAX-AP-18-4"],relatedIds:["1.2-KN-02"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-212",ue:"1.2",front:"Quel leucocyte libère histamine et héparine et intensifie l'inflammation ?",back:"Le basophile.",sources:["OPENSTAX-AP-18-4"],relatedIds:["1.2-KN-02"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-213",ue:"1.2",front:"En quoi les monocytes se transforment-ils dans les tissus ?",back:"En macrophages.",sources:["OPENSTAX-AP-18-4"],relatedIds:["1.2-KN-02"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-214",ue:"1.2",front:"Quelle est la séquence des trois phases de l'hémostase ?",back:"Spasme vasculaire, clou plaquettaire, coagulation.",sources:["OPENSTAX-AP-18-5"],relatedIds:["1.2-KN-03"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-215",ue:"1.2",front:"Quel est le rôle du facteur de von Willebrand dans l'hémostase ?",back:"Il stabilise l'adhésion des plaquettes à la paroi lésée.",sources:["OPENSTAX-AP-18-5"],relatedIds:["1.2-KN-03"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-216",ue:"1.2",front:"Quelles voies convergent dans la cascade de coagulation ?",back:"Les voies extrinsèque et intrinsèque, vers une voie commune.",sources:["OPENSTAX-AP-18-5"],relatedIds:["1.2-KN-03"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-217",ue:"1.2",front:"Pourquoi le clou plaquettaire ne suffit-il pas à arrêter durablement un saignement ?",back:"C'est un bouchon temporaire ; la fibrine de la coagulation le stabilise.",sources:["OPENSTAX-AP-18-5"],relatedIds:["1.2-KN-03"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-218",ue:"1.2",front:"Quelle propriété de l'immunité adaptative permet une réponse secondaire plus rapide ?",back:"La mémoire immunitaire.",sources:["OPENSTAX-AP-21-2","OPENSTAX-AP-21-3"],relatedIds:["1.2-KN-04"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-219",ue:"1.2",front:"Que font les lymphocytes T auxiliaires (CD4+) ?",back:"Ils sécrètent des cytokines qui amplifient d'autres réponses immunitaires.",sources:["OPENSTAX-AP-21-2","OPENSTAX-AP-21-3"],relatedIds:["1.2-KN-04"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-220",ue:"1.2",front:"Comment les lymphocytes T cytotoxiques (CD8+) détruisent-ils leurs cibles ?",back:"En induisant leur apoptose (perforines, granzymes, ligand Fas).",sources:["OPENSTAX-AP-21-2","OPENSTAX-AP-21-3"],relatedIds:["1.2-KN-04"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-221",ue:"1.2",front:"Un premier contact avec un pathogène est-il mémorisé par l'immunité innée ?",back:"Non : seule l'immunité adaptative génère une mémoire.",sources:["OPENSTAX-AP-21-2","OPENSTAX-AP-21-3"],relatedIds:["1.2-KN-04"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-222",ue:"1.2",front:"Quel signe cardinal de l'inflammation est ressenti par le patient comme un symptôme ?",back:"La douleur.",sources:["OPENSTAX-AP-21-2"],relatedIds:["1.2-KN-05"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-223",ue:"1.2",front:"Quels médiateurs une lésion tissulaire libère-t-elle pour déclencher l'inflammation ?",back:"L'histamine, les leucotriènes et les prostaglandines.",sources:["OPENSTAX-AP-21-2"],relatedIds:["1.2-KN-05"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-224",ue:"1.2",front:"Quel phénomène explique la chaleur et la rougeur inflammatoires ?",back:"La vasodilatation, qui augmente le flux sanguin local.",sources:["OPENSTAX-AP-21-2"],relatedIds:["1.2-KN-05"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-225",ue:"1.2",front:"Quel phénomène explique l'œdème inflammatoire ?",back:"L'augmentation de la perméabilité vasculaire, avec fuite de liquide dans les tissus.",sources:["OPENSTAX-AP-21-2"],relatedIds:["1.2-KN-05"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-226",ue:"2.4",front:"Radiculopathie : quel type de douleur et quel facteur l'aggrave typiquement ?",back:"Douleur au trajet dermatomal, aggravée par la toux, l'éternuement ou l'effort (Valsalva).",sources:["NCBI-CERVICAL-RADIC"],relatedIds:["2.4-KN-01"]},{id:"FC-227",ue:"2.4",front:"Que suggère une manœuvre de Spurling qui reproduit la douleur radiculaire ?",back:"Une compression foraminale.",sources:["NCBI-CERVICAL-RADIC"],relatedIds:["2.4-EX-01"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-228",ue:"2.4",front:"Quel effet attend-on du test de distraction cervicale en cas de radiculopathie ?",back:"Un soulagement de la douleur radiculaire par diminution de la compression foraminale.",sources:["NCBI-CERVICAL-RADIC"],relatedIds:["2.4-EX-01"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-229",ue:"2.4",front:"Dans quelle plage d'élévation de la jambe tendue le Lasègue est-il positif ?",back:"Entre 30° et 70°.",sources:["NCBI-LUMBOSACRAL-RADIC"],relatedIds:["2.4-EX-01"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-230",ue:"2.4",front:"Paresthésies du pouce : quel élément distingue une origine C6 d'un canal carpien ?",back:"Extension du poignet et réflexe brachio-radial diminués = C6 ; le canal carpien épargne typiquement ces deux éléments.",sources:["NCBI-CERVICAL-RADIC"],relatedIds:["2.4-DX-01"]},{id:"FC-231",ue:"2.4",front:"Radiculopathie cervicale + maladresse des mains + trouble de la marche : quoi suspecter ?",back:"Une myélopathie cervicale associée (signes pyramidaux sous le niveau lésionnel).",sources:["NCBI-UMN-SIGNS"],relatedIds:["2.4-RF-03"]},{id:"FC-232",ue:"2.4",front:"Signe de Lhermitte : que déclenche-t-il et pourquoi inquiète-t-il ?",back:"Décharge électrique dans le dos/membres à la flexion cervicale ; évoque une atteinte médullaire cervicale.",sources:["NCBI-UMN-SIGNS"],relatedIds:["2.4-RF-03"]},{id:"FC-233",ue:"2.4",front:"Radiculopathie sans red flag : quand l'imagerie précoce est-elle indiquée ?",back:"Seulement en cas de red flag, de déficit progressif/sévère, ou d'échec du traitement conservateur après plusieurs semaines.",sources:["NICE-NG59"],relatedIds:["2.4-KN-02"]},{id:"FC-234",ue:"2.6",front:"Orthopnée : définition et signification",back:"Dyspnée apparaissant en décubitus, soulagée en position assise ; évocatrice d'insuffisance cardiaque gauche.",sources:["NCBI-DYSPNEA"],relatedIds:["2.6-KN-01"]},{id:"FC-235",ue:"2.6",front:"Dyspnée paroxystique nocturne : à distinguer de quoi ?",back:"De l'orthopnée : réveil brutal en étouffement plusieurs heures après le coucher, résolution plus lente.",sources:["NCBI-DYSPNEA"],relatedIds:["2.6-KN-01"]},{id:"FC-236",ue:"2.6",front:"B3 après 40 ans : que faut-il évoquer ?",back:"Une surcharge volémique, souvent une insuffisance cardiaque, contrairement au B3 physiologique du sujet jeune.",sources:["NCBI-HF"],relatedIds:["2.6-KN-02"]},{id:"FC-237",ue:"2.6",front:"Œdèmes bilatéraux + orthopnée + prise de poids rapide : cardiaque ou veineux ?",back:"Cardiaque : la triade oriente vers une décompensation, plutôt qu'une insuffisance veineuse isolée (souvent asymétrique, sans dyspnée).",sources:["NCBI-HF"],relatedIds:["2.6-RF-03"]},{id:"FC-238",ue:"2.6",front:"Signe de Homans : fiable pour écarter une thrombose veineuse profonde ?",back:"Non, peu sensible et peu spécifique ; sa négativité ne permet pas d'exclure le diagnostic.",sources:["NCBI-PE"],relatedIds:["2.6-KN-03"]},{id:"FC-239",ue:"2.6",front:"Quels sont les trois éléments de la triade de Virchow (embolie pulmonaire) ?",back:"Stase veineuse, hypercoagulabilité, lésion endothéliale.",sources:["NCBI-PE"],relatedIds:["2.6-KN-03"]},{id:"FC-240",ue:"2.6",front:"Douleur thoracique brutale, déchirante, migratrice : quel geste d'examen oriente ?",back:"Comparer la pression artérielle aux deux bras : une asymétrie évoque une dissection.",sources:["NICE-CG95"],relatedIds:["2.6-EX-01"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-241",ue:"2.6",front:"SpO2 normale au repos : élimine-t-elle une embolie pulmonaire ?",back:"Non, surtout chez un patient jeune sans comorbidité respiratoire.",sources:["NCBI-PE"],relatedIds:["2.6-KN-03"]},{id:"FC-242",ue:"2.10",front:"Seuil de fièvre définissant une urgence chez un patient neutropénique sous chimiothérapie ?",back:"≥ 38,3 °C (ou ≥ 38 °C pendant au moins 1 heure).",sources:["NCBI-FEBRILE-NEUTROPENIA"],relatedIds:["2.10-RF-02"]},{id:"FC-243",ue:"2.10",front:"Pourquoi une infection peut-elle être sévère sans signes locaux chez un patient neutropénique ?",back:"Le déficit en neutrophiles supprime la réponse inflammatoire locale habituelle.",sources:["NCBI-FEBRILE-NEUTROPENIA"],relatedIds:["2.10-RF-02"]},{id:"FC-244",ue:"2.10",front:"Quel antécédent chirurgical faut-il rechercher devant toute fièvre car il change le niveau d'urgence ?",back:"La splénectomie (ou une asplénie fonctionnelle).",sources:["NCBI-ASPLENIA"],relatedIds:["2.10-RF-03"]},{id:"FC-245",ue:"2.10",front:"Quel type de germes menace particulièrement le patient asplénique fébrile ?",back:"Les germes encapsulés (pneumocoque, méningocoque, Haemophilus influenzae).",sources:["NCBI-ASPLENIA"],relatedIds:["2.10-RF-03"]},{id:"FC-246",ue:"2.10",front:"Quelle complication associe purpura nécrotique extensif, fièvre et CIVD ?",back:"Le purpura fulminans.",sources:["NCBI-PURPURA-FULMINANS"],relatedIds:["2.10-DX-01"]},{id:"FC-247",ue:"2.10",front:"Le purpura thrombopénique immunologique s'accompagne-t-il typiquement de fièvre ?",back:"Non, il survient en règle sans fièvre ni syndrome infectieux associé.",sources:["NCBI-THROMBOCYTOPENIA"],relatedIds:["2.10-DX-01"]},{id:"FC-248",ue:"2.10",front:"Taille et durée au-delà desquelles une adénopathie fixe et indolore doit faire suspecter une malignité ?",back:"Plus de 2 cm, persistant au-delà de 4 à 6 semaines.",sources:["NCBI-LYMPHADENOPATHY"],relatedIds:["2.10-DX-02"]},{id:"FC-249",ue:"2.10",front:"Quelle localisation ganglionnaire est un signe d'alerte quelle que soit sa taille ?",back:"La localisation sus-claviculaire.",sources:["NCBI-LYMPHADENOPATHY"],relatedIds:["2.10-DX-02"]},{id:"FC-250",ue:"2.10",front:"Quels organes palper systématiquement devant une fièvre prolongée d'origine indéterminée ?",back:"Les aires ganglionnaires et la rate (recherche de splénomégalie).",sources:["NCBI-LYMPHADENOPATHY","NCBI-SPLENOMEGALY"],relatedIds:["2.10-EX-01"]},{id:"FC-251",ue:"2.10",front:"Quel facteur détermine le niveau d'urgence d'une fièvre en contexte immuno-hématologique ?",back:"Le terrain du patient (neutropénie, asplénie, hémopathie connue).",sources:["NICE-CG151"],relatedIds:["2.10-MG-01"]},{id:"FC-252",ue:"2.9",front:"Quelle est la différence entre une macule et une papule ?",back:"La macule est plane, non palpable ; la papule est une lésion solide surélevée de moins de 1 cm.",sources:["NCBI-SKIN-LESIONS"],relatedIds:["2.9-KN-01"]},{id:"FC-253",ue:"2.9",front:"Selon quels trois axes décrit-on une lésion cutanée ?",back:"Morphologie primaire, configuration/disposition, distribution anatomique.",sources:["NCBI-SKIN-LESIONS"],relatedIds:["2.9-KN-01"]},{id:"FC-254",ue:"2.9",front:"Quel signe distingue le plus précocement une fasciite nécrosante d'une cellulite simple ?",back:"Une douleur disproportionnée par rapport à l'aspect cutané visible.",sources:["NCBI-NEC-FASCIITIS"],relatedIds:["2.9-RF-03"]},{id:"FC-255",ue:"2.9",front:"Que faire en urgence devant une suspicion de fasciite nécrosante ?",back:"Orienter sans délai vers les urgences chirurgicales pour débridement.",sources:["NCBI-NEC-FASCIITIS"],relatedIds:["2.9-RF-03"]},{id:"FC-256",ue:"2.9",front:"Quels signes distinguent une toxidermie sévère (Stevens-Johnson) d'un exanthème médicamenteux banal ?",back:"Atteinte muqueuse, douleur cutanée, signe de Nikolsky positif, décollement épidermique.",sources:["NCBI-SJS-TEN"],relatedIds:["2.9-RF-04"]},{id:"FC-257",ue:"2.9",front:"Quel délai sépare généralement l'introduction d'un médicament inducteur et l'apparition d'un DRESS syndrome ?",back:"De 2 à 8 semaines après le début du traitement.",sources:["NCBI-CADR"],relatedIds:["2.9-RF-04"]},{id:"FC-258",ue:"2.9",front:"Quel signe d'angio-œdème facial impose un appel aux secours immédiat ?",back:"Une atteinte laryngée ou pharyngée : dysphonie, stridor ou dyspnée.",sources:["NCBI-ANGIOEDEMA"],relatedIds:["2.9-MG-01"]},{id:"FC-259",ue:"2.9",front:"Syndrome de Stevens-Johnson : quelle surface corporelle décollée ?",back:"< 10 %.",sources:["NCBI-SJS-TEN"],relatedIds:["2.9-RF-04"]},{id:"FC-260",ue:"2.9",front:"Quels deux éléments de l'examen mesurent la gravité d'une éruption cutanée étendue ?",back:"Le pourcentage de surface corporelle atteinte et la présence d'un décollement cutané.",sources:["NCBI-SJS-TEN"],relatedIds:["2.9-EX-01"]},{id:"FC-261",ue:"2.15",front:"À partir de quel score le questionnaire DN4 évoque-t-il une composante neuropathique ?",back:"Un score ≥ 4 sur 10.",sources:["PUBMED-DN4"],relatedIds:["2.15-EX-01"]},{id:"FC-262",ue:"2.15",front:"Qu'est-ce qui caractérise cliniquement une douleur nociplastique ?",back:"Douleur diffuse, disproportionnée par rapport à toute lésion identifiable, hypersensibilité à plusieurs types de stimuli.",sources:["IASP-TERM"],relatedIds:["2.15-DX-01"]},{id:"FC-263",ue:"2.15",front:"Différence entre douleur chronique primaire et douleur chronique secondaire (ICD-11) ?",back:"Primaire : syndrome à part entière sans cause identifiable. Secondaire : symptôme d'une pathologie sous-jacente identifiable.",sources:["PUBMED-ICD11-PAIN"],relatedIds:["2.15-RF-03"]},{id:"FC-264",ue:"2.15",front:"Quels deux scores les critères 2016 de la fibromyalgie combinent-ils ?",back:"Indice de douleur diffuse (WPI) et échelle de sévérité des symptômes (SSS), selon des seuils combinés.",sources:["PUBMED-FM-ACR2016"],relatedIds:["2.15-KN-01"]},{id:"FC-265",ue:"2.15",front:"Quelles caractéristiques de début, d'exercice et de nuit définissent la douleur inflammatoire (critères ASAS) ?",back:"Début avant 40 ans et insidieux ; amélioration à l'exercice mais pas au repos ; douleur nocturne avec amélioration au lever (4 critères sur 5).",sources:["PUBMED-ASAS-IBP"],relatedIds:["2.15-DX-02"]},{id:"FC-266",ue:"2.15",front:"Combien de critères ASAS sur 5 sont nécessaires pour évoquer une douleur inflammatoire ?",back:"Au moins 4 sur 5.",sources:["PUBMED-ASAS-IBP"],relatedIds:["2.15-DX-02"]},{id:"FC-267",ue:"2.15",front:"Quelle durée de raideur matinale oriente vers une origine inflammatoire plutôt que mécanique ?",back:"Plus de 30 minutes.",sources:["PUBMED-ASAS-IBP"],relatedIds:["2.15-DX-02"]},{id:"FC-268",ue:"2.15",front:"Quelle conduite adopter devant une douleur diffuse sans red flag compatible avec une fibromyalgie ?",back:"Prise en charge biopsychosociale multimodale, sans multiplier les examens complémentaires.",sources:["NICE-NG59"],relatedIds:["2.15-MG-01"]},{id:"FC-269",ue:"2.15",front:"Quels facteurs psychosociaux (yellow flags) influencent le pronostic d'une douleur chronique ?",back:"Peur du mouvement, catastrophisme, retentissement sur le sommeil et les activités, croyances erronées sur la douleur.",sources:["NICE-NG59"],relatedIds:["2.15-EX-01"]},{id:"FC-270",ue:"2.8",front:"Quel signe d'examen est le plus discriminant en faveur d'une torsion testiculaire ?",back:"L'abolition du réflexe crémastérien du côté atteint.",sources:["NCBI-ACUTE-SCROTUM"],relatedIds:["2.8-DX-01"]},{id:"FC-271",ue:"2.8",front:"Que vaut un signe de Prehn pour exclure une torsion testiculaire ?",back:"Il est trop peu fiable pour l'exclure à lui seul.",sources:["NCBI-ACUTE-SCROTUM"],relatedIds:["2.8-DX-01"]},{id:"FC-272",ue:"2.8",front:"Dans quel délai le taux de sauvetage testiculaire dépasse-t-il 90 % après le début d'une torsion ?",back:"Dans les 6 heures suivant le début de la douleur.",sources:["NCBI-TESTICULAR-TORSION"],relatedIds:["2.8-RF-04"]},{id:"FC-273",ue:"2.8",front:"Qu'évoque un « blue dot sign » visible par transillumination scrotale ?",back:"Une torsion d'une annexe testiculaire (hydatide de Morgagni), plutôt qu'une torsion testiculaire vraie.",sources:["NCBI-ACUTE-SCROTUM"],relatedIds:["2.8-DX-01"]},{id:"FC-274",ue:"2.8",front:"Comment rechercher un globe vésical à l'examen ?",back:"Percussion sus-pubienne à la recherche d'une matité convexe.",sources:["NCBI-URINARY-RETENTION"],relatedIds:["2.8-EX-01"]},{id:"FC-275",ue:"2.8",front:"Que recherche le signe de Giordano ?",back:"Une douleur vive à la percussion de la loge rénale, évocatrice d'une origine rénale.",sources:["NCBI-RENAL-COLIC"],relatedIds:["2.8-EX-01"]},{id:"FC-276",ue:"2.8",front:"Que doit faire suspecter une rétention urinaire aiguë avec anesthésie en selle ?",back:"Un syndrome de la queue de cheval, urgence neurochirurgicale.",sources:["NCBI-URINARY-RETENTION"],relatedIds:["2.8-RF-05"]},{id:"FC-277",ue:"2.8",front:"Que doit faire évoquer une hématurie macroscopique indolore chez un fumeur de plus de 50 ans ?",back:"Une cause tumorale (vessie, rein, prostate) à exclure par un bilan urologique.",sources:["NCBI-HEMATURIA"],relatedIds:["2.8-DX-02"]},{id:"FC-278",ue:"2.8",front:"Peut-on attribuer une hématurie à un traitement anticoagulant sans bilan complémentaire ?",back:"Non, l'anticoagulant peut démasquer une lésion sous-jacente plutôt que la causer.",sources:["NCBI-HEMATURIA"],relatedIds:["2.8-DX-02"]},{id:"FC-279",ue:"2.5",front:"Des cristaux dans le liquide synovial excluent-ils une arthrite septique ?",back:"Non. Une infection concomitante reste possible et la microbiologie demeure nécessaire.",sources:["SANJO-2023"],relatedIds:["2.5-RF-16"]},{id:"FC-280",ue:"2.5",front:"Quel antécédent récent rend une dorsalgie nouvelle particulièrement suspecte d'infection vertébrale ?",back:"Une bactériémie à Staphylococcus aureus.",sources:["IDSA-NVO-2015"],relatedIds:["2.5-RF-18"]},{id:"FC-281",ue:"2.5",front:"Un signe pyramidal isolément absent exclut-il une myélopathie cervicale ?",back:"Non. La constellation clinique prime sur un signe isolé.",sources:["NCBI-CERVICAL-MYELOPATHY"],relatedIds:["2.5-RF-08"]},{id:"FC-282",ue:"2.3",front:"Signes de Kernig et Brudzinski : sensibilité et spécificité pour la méningite ?",back:"Sensibilité faible (Kernig ~5 %, Brudzinski 2-43 %) ; spécificité élevée (95 % et 80-100 %) : négatifs, ils n'excluent pas une méningite.",sources:["NCBI-KERNIG","NCBI-BRUDZINSKI"],relatedIds:["2.3-EX-01"]},{id:"FC-283",ue:"2.3",front:"Fasciite nécrosante : outre la douleur disproportionnée, quels signes locaux d'extension alertent ?",back:"Extension rapide en quelques heures et crépitation sous-cutanée.",sources:["NCBI-NEC-FASCIITIS"],relatedIds:["2.3-DX-01"]},{id:"FC-284",ue:"2.3",front:"Endocardite infectieuse : pourquoi l'absence de souffle cardiaque n'exclut-elle pas le diagnostic ?",back:"Un souffle nouveau ou modifié n'est retrouvé que dans moins de 50 % des cas d'endocardite infectieuse.",sources:["NCBI-ENDOCARDITIS"],relatedIds:["2.3-RF-02"]},{id:"FC-285",ue:"2.3",front:"Chez l'enfant, quand une ostéomyélite peut-elle mimer une arthrite septique ?",back:"Quand la métaphyse infectée est intra-capsulaire (coude, épaule, hanche), l'infection s'étend à l'articulation adjacente.",sources:["NCBI-OSTEOMYELITIS"],relatedIds:["2.3-RF-03"]},{id:"FC-286",ue:"2.3",front:"Fièvre et infection active : quelle conduite avant tout traitement manuel ?",back:"Différer le traitement manuel ; orientation médicale urgente si red flag de sepsis, méningite ou infection ostéo-articulaire suspectée.",sources:["NICE-NG253"],relatedIds:["2.3-MG-01"]},{id:"FC-287",ue:"2.7",front:"Cholécystite aiguë : quels éléments la distinguent d'une colique biliaire simple ?",back:"Douleur prolongée au-delà de quelques heures, fièvre, défense de l'hypochondre droit, syndrome inflammatoire.",sources:["NCBI-CHOLECYSTITIS"],relatedIds:["2.7-RF-02"]},{id:"FC-288",ue:"2.7",front:"Pancréatite aiguë : caractéristiques de la douleur typique ?",back:"Douleur épigastrique brutale, transfixiante, irradiant en barre vers le dos, avec nausées et vomissements.",sources:["NCBI-PANCREATITIS"],relatedIds:["2.7-RF-03"]},{id:"FC-289",ue:"2.7",front:"Méléna avec syncope : que signifie l'association de ces deux signes ?",back:"Une instabilité hémodynamique secondaire à une hémorragie digestive active nécessitant une orientation urgente.",sources:["NCBI-UGIB"],relatedIds:["2.7-RF-04"]},{id:"FC-290",ue:"2.7",front:"Occlusion intestinale : quel changement de la douleur signe une complication ischémique ?",back:"Le passage d'une douleur colique à une douleur continue et sévère, avec fièvre et tachycardie.",sources:["NCBI-SBO"],relatedIds:["2.7-RF-05"]},{id:"FC-291",ue:"2.7",front:"Confusion et sueurs chez un diabétique connu : premier réflexe ?",back:"Suspecter une hypoglycémie ; resucrer immédiatement par voie orale si le patient est conscient.",sources:["NCBI-HYPOGLYCEMIA"],relatedIds:["2.7-MG-01"]},{id:"FC-292",ue:"1.10",front:"De la surface à la profondeur, quelles sont les trois couches de la peau ?",back:"Épiderme, derme, hypoderme.",sources:["NCBI-SKIN-ANATOMY"],relatedIds:["1.10-KN-01"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-293",ue:"1.10",front:"Pourquoi l'épiderme dépend-il du derme pour sa nutrition ?",back:"Il est avasculaire ; les nutriments diffusent depuis le derme papillaire.",sources:["NCBI-SKIN-ANATOMY"],relatedIds:["1.10-KN-01"]},{id:"FC-294",ue:"1.10",front:"Dans quel ordre se succèdent les quatre phases de la cicatrisation cutanée ?",back:"Hémostase, inflammation, prolifération, remodelage.",sources:["NCBI-WOUND-HEALING"],relatedIds:["1.10-KN-02"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-295",ue:"1.10",front:"Quel type de collagène remplace le collagène de type III lors du remodelage cicatriciel ?",back:"Le collagène de type I, mature.",sources:["NCBI-WOUND-HEALING"],relatedIds:["1.10-KN-02"]},{id:"FC-296",ue:"1.10",front:"Quel est le mécanisme le plus efficace de transfert de chaleur du centre vers la périphérie ?",back:"Le flux sanguin cutané (vasodilatation).",sources:["NCBI-THERMOREG"],relatedIds:["1.10-KN-03"]},{id:"FC-297",ue:"1.10",front:"Quelle plage de température corporelle centrale la thermorégulation maintient-elle ?",back:"Entre 36,5 et 37,5 °C.",sources:["NCBI-THERMOREG"],relatedIds:["1.10-KN-03"]},{id:"FC-298",ue:"1.10",front:"Quels mécanorécepteurs cutanés principaux distingue-t-on ?",back:"Meissner, Merkel, Pacini, Ruffini.",sources:["NCBI-MECHANORECEPTORS"],relatedIds:["1.10-KN-04"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-299",ue:"1.10",front:"Qu'est-ce qu'un dermatome ?",back:"Le territoire cutané innervé par les fibres sensitives d'une seule racine spinale.",sources:["NCBI-DERMATOMES"],relatedIds:["1.10-KN-04"]},{id:"FC-300",ue:"1.10",front:"En quelles trois tuniques la paroi de l'œil se divise-t-elle ?",back:"Fibreuse (sclère, cornée), vasculaire/uvée (choroïde, corps ciliaire, iris), nerveuse (rétine).",sources:["NCBI-EYE-ANATOMY"],relatedIds:["1.10-KN-05"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-301",ue:"1.10",front:"Que provoque classiquement une lésion du chiasma optique ?",back:"Une hémianopsie bitemporale.",sources:["NCBI-VISUAL-PATHWAY"],relatedIds:["1.10-KN-05"]},{id:"FC-302",ue:"1.10",front:"Quels organes vestibulaires détectent les rotations de la tête ?",back:"Les trois canaux semi-circulaires.",sources:["NCBI-VESTIBULAR-PHYSIO"],relatedIds:["1.10-KN-06"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-303",ue:"1.10",front:"Quel nerf crânien transmet les informations vestibulaires ?",back:"Le nerf vestibulo-cochléaire (VIIIe nerf crânien).",sources:["NCBI-EAR-ANATOMY"],relatedIds:["1.10-KN-06"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-304",ue:"2.2",front:"En combien de temps la CRP atteint-elle son pic après un stimulus inflammatoire ?",back:"36 à 50 heures.",sources:["NCBI-CRP"],relatedIds:["2.2-KN-01"]},{id:"FC-305",ue:"2.2",front:"Pourquoi une VS ou une CRP normales n'excluent-elles pas une pathologie grave ?",back:"Elles réduisent la probabilité sans l'annuler, surtout si la cause est débutante ou localisée.",sources:["NCBI-CRP","NCBI-ESR"],relatedIds:["2.2-KN-01"]},{id:"FC-306",ue:"2.2",front:"Quel est le seuil OMS d'hémoglobine définissant l'anémie chez la femme adulte non enceinte ?",back:"Inférieure à 12 g/dL.",sources:["NCBI-ANEMIA"],relatedIds:["2.2-RF-01"]},{id:"FC-307",ue:"2.2",front:"Quels signes associés à une anémie doivent faire suspecter une cause grave sous-jacente ?",back:"Perte de poids inexpliquée ; sueurs nocturnes ; rectorragies/méléna ; altération marquée de l'état général.",sources:["NCBI-ANEMIA"],relatedIds:["2.2-RF-01"]},{id:"FC-308",ue:"2.2",front:"Quelles lignées cellulaires l'hémogramme explore-t-il ?",back:"Globules rouges, globules blancs, plaquettes.",sources:["NCBI-CBC"],relatedIds:["2.2-KN-02"]},{id:"FC-309",ue:"2.2",front:"Que peut traduire cliniquement une thrombopénie ?",back:"Un purpura ou des ecchymoses spontanées, par risque hémorragique augmenté.",sources:["NCBI-CBC"],relatedIds:["2.2-KN-02"]},{id:"FC-310",ue:"2.2",front:"Que recommande NICE NG59 pour l'imagerie d'une lombalgie commune en soins primaires ?",back:"Ne pas l'offrir de façon systématique, en l'absence de red flag.",sources:["NICE-NG59"],relatedIds:["2.2-IM-01"]},{id:"FC-311",ue:"2.2",front:"Quand une imagerie est-elle envisagée en contexte spécialisé selon NICE NG59 ?",back:"Seulement si son résultat est susceptible de changer la prise en charge.",sources:["NICE-NG59"],relatedIds:["2.2-IM-01"]},{id:"FC-312",ue:"2.2",front:"Que doit faire l'ostéopathe face à un résultat paraclinique anormal rapporté sans explication ?",back:"Chercher un avis médical rapide et communiquer avec le médecin traitant, sans l'interpréter seul.",sources:["NICE-NG59"],relatedIds:["2.2-MG-01"]},{id:"FC-313",ue:"2.2",front:"Un résultat paraclinique normal et déjà expliqué par le médecin permet-il de poursuivre la prise en charge ostéopathique ?",back:"Oui, si le résultat est cohérent avec le tableau clinique.",sources:["NCBI-CRP"],relatedIds:["2.2-MG-01"]},{id:"FC-314",ue:"2.1",front:"Anticoagulation et techniques HVLA : quel statut ?",back:"Contre-indication relative ; évaluation individuelle du rapport bénéfice/risque, idéalement avec le prescripteur.",sources:["NCBI-HVLA-CONTRA"],relatedIds:["2.1-RF-01"]},{id:"FC-315",ue:"2.1",front:"Corticothérapie ≥10 mg/j au-delà de 90 jours : effet sur le risque fracturaire ?",back:"Risque de fracture de hanche x7 et de fracture vertébrale x17 environ ; abaisser le seuil de suspicion devant un traumatisme mineur.",sources:["NCBI-GC-OSTEOPOROSIS"],relatedIds:["2.1-RF-02"]},{id:"FC-316",ue:"2.1",front:"AINS : quel mécanisme du risque digestif ?",back:"Inhibition de la COX-1, qui réduit les prostaglandines protectrices de la muqueuse gastrique ; risque d'ulcère hémorragique.",sources:["NCBI-NSAID"],relatedIds:["2.1-RF-03"]},{id:"FC-317",ue:"2.1",front:"Opioïdes chroniques : quelle proportion de patients répond aux critères de trouble de l'usage ?",back:"Jusqu'à 50% des patients sous opioïdes au long cours.",sources:["NCBI-OPIOID-OUD"],relatedIds:["2.1-RF-04"]},{id:"FC-318",ue:"2.1",front:"Polymédication : quel seuil et quel risque principal chez la personne âgée ?",back:"5 médicaments ou plus ; facteur de risque indépendant de chute et de fracture de hanche.",sources:["NCBI-POLYPHARMACY"],relatedIds:["2.1-MG-01"]},{id:"FC-319",ue:"2.16",front:"Carence en vitamine D : quels symptômes musculo-squelettiques ?",back:"Douleur osseuse, arthralgies, myalgies, fatigue, faiblesse musculaire ; augmente le risque de chute.",sources:["NCBI-VITAMIN-D-DEF"],relatedIds:["2.16-KN-01"]},{id:"FC-320",ue:"2.16",front:"Apports calcique et vitaminique D insuffisants : quel lien avec l'ostéoporose ?",back:"Facteur de risque reconnu d'ostéoporose, à considérer avec l'âge, la carence estrogénique et les antécédents familiaux.",sources:["NCBI-OSTEOPOROSIS-FEMALES"],relatedIds:["2.16-RF-01"]},{id:"FC-321",ue:"2.16",front:"Dénutrition et fracture : quel risque pour la consolidation ?",back:"Facteur de risque de pseudarthrose (5-10% des fractures) ; altère la synthèse du collagène et la réparation osseuse.",sources:["MEESTERS-MALNUTRITION-FRACTURE"],relatedIds:["2.16-RF-02"]},{id:"FC-322",ue:"2.16",front:"Anorexie mentale : impact osseux chez le sujet jeune ?",back:"Cause reconnue d'ostéoporose secondaire : baisse du pic de masse osseuse (multifactoriel : hypogonadisme, carence en vitamine D).",sources:["NCBI-SECONDARY-OSTEOPOROSIS"],relatedIds:["2.16-RF-03"]},{id:"FC-323",ue:"2.12",front:"Ecchymose chez un nourrisson non mobile : que faire ?",back:"Rare de façon accidentelle (0-1,3 %) : toute ecchymose chez un enfant non mobile fait suspecter une maltraitance et orienter.",sources:["PIERCE-TEN4-FACESP"],relatedIds:["2.12-RF-01"]},{id:"FC-324",ue:"2.12",front:"Fièvre chez un nourrisson de moins de 3 mois : conduite ?",back:"Toujours une urgence potentielle, même si l'enfant paraît bien ; orientation médicale immédiate, quel que soit l'aspect clinique.",sources:["NICE-NG143-FEVER"],relatedIds:["2.12-RF-02"]},{id:"FC-325",ue:"2.12",front:"Boiterie fébrile de l'enfant : diagnostic à éliminer en priorité ?",back:"Arthrite septique de hanche.",sources:["KOCHER-1999-SEPTIC-HIP"],relatedIds:["2.12-DX-01"]},{id:"FC-326",ue:"2.12",front:"Marche autonome : repère de développement attendu vers quel âge ?",back:"Vers 18 mois chez la grande majorité des enfants ; un écart important ou une régression est un signal d'alerte.",sources:["CDC-DEV-MILESTONES"],relatedIds:["2.12-KN-01"]},{id:"FC-327",ue:"2.12",front:"Test d'Adam : que recherche-t-il ?",back:"Une gibbosité costale ou lombaire asymétrique à la flexion antérieure du tronc, signant une rotation vertébrale évocatrice de scoliose.",sources:["USPSTF-SCOLIOSIS-2018"],relatedIds:["2.12-EX-01"]},{id:"FC-328",ue:"2.13",front:"Chute chez la personne âgée : quelle évaluation déclencher ?",back:"Évaluation multifactorielle : marche/équilibre, vision, tension orthostatique, médicaments, environnement ; pas seulement la polymédication.",sources:["AGS-BGS-FALLS-2011"],relatedIds:["2.13-RF-01","2.1-MG-01"]},{id:"FC-329",ue:"2.13",front:"Fracture après un traumatisme mineur chez la personne âgée : implication ?",back:"Fracture de fragilité = red flag en soi ; impose imagerie et évaluation du risque fracturaire ultérieur (FRAX/QFracture).",sources:["NICE-CG146-OSTEOPOROSIS-RISK"],relatedIds:["2.13-RF-02","2.5-RF-17"]},{id:"FC-330",ue:"2.13",front:"Infarctus chez la personne âgée : signe le plus trompeur ?",back:"Douleur thoracique souvent absente (> 50 % après 85 ans) ; dyspnée, syncope ou confusion peuvent être les seuls signes.",sources:["OCHIAI-MI-ATYPICAL-ELDERLY"],relatedIds:["2.13-RF-03"]},{id:"FC-331",ue:"2.13",front:"Absence de fièvre chez la personne âgée fragile : que conclure ?",back:"Rien : la fièvre est absente ou atténuée chez 20-50 % des infections graves à cet âge ; ne rassure pas faussement.",sources:["NORMAN-FEVER-ELDERLY-2000"],relatedIds:["2.13-RF-04"]},{id:"FC-332",ue:"2.13",front:"Confusion aiguë chez la personne âgée : diagnostic à évoquer ?",back:"Délirium ; symptôme d'une cause organique aiguë à rechercher, jamais un diagnostic en soi. Anamnèse directe peu fiable.",sources:["NICE-CG103-DELIRIUM"],relatedIds:["2.13-RF-05"]},{id:"FC-333",ue:"2.4",front:"Céphalée nouvelle avec claudication de la mâchoire après 50 ans : quelle hypothèse ?",back:"Une artérite à cellules géantes, urgence médicale du jour même.",sources:["BSR-GCA-2020"],relatedIds:["2.13-RF-06","2.4-RF-01"],audience:"CLINICAL",difficultyBand:"CLINICAL"},{id:"FC-334",ue:"2.11",front:"Que signale un apaisement soudain après une détresse suicidaire intense ?",back:"Peut signer une décision de passage à l'acte déjà prise ; c'est un red flag, pas un mieux-être.",sources:["NICE-NG225"],relatedIds:["2.11-RF-01"]},{id:"FC-335",ue:"2.11",front:"Faut-il éviter de demander directement à un patient s'il pense au suicide ?",back:"Non : poser la question directement ne provoque pas le passage à l'acte et permet le repérage.",sources:["NIMH-ASQ"],relatedIds:["2.11-RF-01"]},{id:"FC-336",ue:"2.11",front:"Quel est le signe cardinal distinguant le delirium d'un trouble psychiatrique primaire ?",back:"Fluctuation de l'attention et de la vigilance au cours de la journée, d'apparition aiguë.",sources:["NICE-CG103"],relatedIds:["2.11-DX-01"]},{id:"FC-337",ue:"2.11",front:"Une confusion aiguë brutale chez une personne âgée doit d'abord faire évoquer quoi ?",back:"Un delirium d'origine organique (infection, métabolique, médicament) : urgence à orienter.",sources:["NICE-CG103"],relatedIds:["2.11-DX-01"]},{id:"FC-338",ue:"2.11",front:"Quel type d'hallucinations lors d'une décompensation psychotique est particulièrement à risque ?",back:"Les hallucinations auditives à contenu impératif (ordres de passage à l'acte).",sources:["NICE-CG178"],relatedIds:["2.11-RF-02"]},{id:"FC-339",ue:"2.11",front:"Un premier épisode psychotique chez un jeune adulte sans antécédent impose quoi ?",back:"Une évaluation médicale complète pour éliminer une cause organique ou toxique.",sources:["NICE-CG178"],relatedIds:["2.11-RF-02"]},{id:"FC-340",ue:"2.11",front:"Avant de conclure à une attaque de panique, quelles urgences doit-on éliminer ?",back:"Syndrome coronarien aigu, embolie pulmonaire, hyperthyroïdie, hypoglycémie.",sources:["NICE-CG113"],relatedIds:["2.11-DX-02"]},{id:"FC-341",ue:"2.11",front:"Une douleur thoracique aiguë chez une personne à risque cardiovasculaire évoque-t-elle d'abord l'anxiété ?",back:"Non : orienter pour élimination cardiaque avant d'attribuer le symptôme à l'anxiété.",sources:["NICE-CG113"],relatedIds:["2.11-DX-02"]},{id:"FC-342",ue:"2.14",front:"Un sportif suspect de commotion peut-il reprendre le jeu le même jour si les symptômes disparaissent ?",back:"Non : retrait immédiat et pas de retour le jour même, sauf si un professionnel de santé expérimenté établit que le signe n'était pas lié à une commotion.",sources:["BJSPORTS-CONCUSSION23"],relatedIds:["2.14-RF-01"]},{id:"FC-343",ue:"2.14",front:"Une perte de connaissance est-elle nécessaire pour parler de commotion cérébrale liée au sport ?",back:"Non : une commotion peut survenir avec ou sans perte de connaissance.",sources:["BJSPORTS-CONCUSSION23"],relatedIds:["2.14-RF-01"]},{id:"FC-344",ue:"2.14",front:"Une syncope survenant pendant l'effort chez un sportif évoque en priorité quoi ?",back:"Un red flag cardiovasculaire majeur : arrêt de l'activité et bilan cardiologique avant reprise.",sources:["ESC-SPORTSCARDIO20"],relatedIds:["2.14-RF-02"]},{id:"FC-345",ue:"2.14",front:"Quel antécédent familial oriente vers un risque cardiovasculaire chez un sportif ?",back:"Mort subite ou cardiomyopathie chez un parent de moins de 50 ans.",sources:["ESC-SPORTSCARDIO20"],relatedIds:["2.14-RF-02"]},{id:"FC-346",ue:"2.14",front:"Le RED-S concerne-t-il uniquement les sportives ?",back:"Non : il concerne les athlètes féminins et masculins exposés à une faible disponibilité énergétique.",sources:["BJSPORTS-REDS23"],relatedIds:["2.14-RF-03"]},{id:"FC-347",ue:"2.14",front:"Des fractures de stress récidivantes chez un sportif doivent faire rechercher quoi ?",back:"Un déficit énergétique relatif dans le sport (RED-S), pas seulement un problème biomécanique.",sources:["BJSPORTS-REDS23"],relatedIds:["2.14-RF-03"]},{id:"FC-348",ue:"2.14",front:"En cas de coup de chaleur d'exercice, que faut-il faire en priorité ?",back:"Refroidir immédiatement sur place (immersion en eau froide), avant même le transfert.",sources:["NATA-HEATILLNESS15"],relatedIds:["2.14-MG-01"]},{id:"FC-349",ue:"2.14",front:"Qu'est-ce qui distingue le coup de chaleur d'exercice d'un simple épuisement à la chaleur ?",back:"Une altération de l'état de conscience associée à une température centrale élevée.",sources:["NATA-HEATILLNESS15"],relatedIds:["2.14-MG-01"]},{id:"FC-350",ue:"3.4",front:"Quelle loi fédérale reconnaît l'ostéopathie comme profession de santé en Suisse ?",back:"La LPSan (RS 811.21), en vigueur depuis le 1er février 2020 ; l'ostéopathie est l'une de ses sept professions de santé.",sources:["FEDLEX-LPSAN"],relatedIds:["3.4-KN-01"],jurisdiction:"CH"},{id:"FC-351",ue:"3.4",front:"Quel diplôme la LPSan exige-t-elle des ostéopathes pour obtenir l'autorisation de pratiquer ?",back:"Le Master of science HES en ostéopathie (art. 12, al. 2, let. g), ou un diplôme étranger reconnu.",sources:["FEDLEX-LPSAN"],relatedIds:["3.4-KN-01"],jurisdiction:"CH"},{id:"FC-352",ue:"3.4",front:"Quelles 3 conditions l'art. 12 LPSan pose-t-il pour l'autorisation cantonale de pratiquer ?",back:"Diplôme requis (ou étranger reconnu) ; honorabilité et garanties physiques et psychiques ; maîtrise d'une langue officielle du canton.",sources:["FEDLEX-LPSAN"],relatedIds:["3.4-KN-02"],jurisdiction:"CH"},{id:"FC-353",ue:"3.4",front:"Qui délivre l'autorisation de pratiquer une profession de santé en Suisse ?",back:"Le canton dans lequel la profession est exercée.",sources:["FEDLEX-LPSAN"],relatedIds:["3.4-KN-02"],jurisdiction:"CH"},{id:"FC-354",ue:"3.4",front:"Que doit respecter tout professionnel de santé selon l'article 16 LPSan ?",back:"Les limites des compétences acquises dans sa filière d'études, à étendre en continu (art. 16, let. c).",sources:["FEDLEX-LPSAN"],relatedIds:["3.4-MG-01"],jurisdiction:"CH"},{id:"FC-355",ue:"3.4",front:"L'article 16 LPSan impose-t-il le secret professionnel ?",back:"Oui : il impose d'observer le secret professionnel conformément aux dispositions applicables.",sources:["FEDLEX-LPSAN"],relatedIds:["3.4-MG-01"],jurisdiction:"CH"},{id:"FC-356",ue:"3.5",front:"Quel organe sanctionne le non-respect du Code de déontologie FSO ?",back:"La Commission intercantonale d'éthique et de déontologie (CIED).",sources:["FSO-DEONTO"],relatedIds:["3.5-KN-01"],jurisdiction:"CH"},{id:"FC-357",ue:"3.5",front:"Quel est le but du Code de déontologie de la FSO ?",back:"Garantir des soins de qualité et une image professionnelle responsable de l'ostéopathie.",sources:["FSO-DEONTO"],relatedIds:["3.5-KN-01"],jurisdiction:"CH"},{id:"FC-358",ue:"3.5",front:"Le patient peut-il poser des questions pendant toute la consultation, selon le Code FSO ?",back:"Oui : avant, pendant et après la consultation, à tout moment.",sources:["FSO-DEONTO"],relatedIds:["3.5-KN-02"],jurisdiction:"CH"},{id:"FC-359",ue:"3.5",front:"Code FSO : à quel moment le patient peut-il changer de thérapeute ou interrompre son traitement ?",back:"À tout moment, sans avoir à se justifier.",sources:["FSO-DEONTO"],relatedIds:["3.5-KN-02"],jurisdiction:"CH"},{id:"FC-360",ue:"3.5",front:"Que doit faire l'ostéopathe si le tableau dépasse son champ de compétence (Code FSO) ?",back:"Orienter le patient vers un autre professionnel de santé.",sources:["FSO-DEONTO"],relatedIds:["3.5-MG-01"],jurisdiction:"CH"},{id:"FC-361",ue:"3.5",front:"L'obligation déontologique d'orientation recoupe-t-elle une obligation légale ?",back:"Oui : elle rejoint le devoir légal de respecter les limites de compétence (art. 16 LPSan).",sources:["FSO-DEONTO"],relatedIds:["3.5-MG-01"],jurisdiction:"CH"},{id:"FC-362",ue:"4.3",front:"Que fait le clinicien dès les premiers indices de l'anamnèse, selon le modèle hypothético-déductif ?",back:"Il génère précocement plusieurs hypothèses concurrentes, avant la fin du recueil de données.",sources:["JONES-CRM1992"],relatedIds:["4.3-KN-01"]},{id:"FC-363",ue:"4.3",front:"Combien de catégories d'hypothèses cliniques propose Jones ?",back:"Six : dysfonction, mécanismes, source/cause, facteurs contribuants, précautions/contre-indications, pronostic.",sources:["JONES-CRM1992"],relatedIds:["4.3-KN-02"]},{id:"FC-364",ue:"4.3",front:"Que doit déclencher une absence de réponse au traitement d'épreuve ?",back:"Une révision active des hypothèses diagnostiques, pas seulement un changement de technique.",sources:["JONES-CRM1992"],relatedIds:["4.3-DX-01"]},{id:"FC-365",ue:"4.3",front:"Qu'est-ce que le biais d'ancrage en raisonnement clinique ?",back:"Rester fixé sur l'hypothèse initiale malgré des données discordantes ultérieures.",sources:["CROSKERRY-COGERR2003"],relatedIds:["4.3-MG-01"]},{id:"FC-366",ue:"4.3",front:"Qu'est-ce que la clôture prématurée du raisonnement diagnostique ?",back:"Arrêter la recherche d'hypothèses dès qu'une explication plausible apparaît, sans tester les hypothèses graves.",sources:["CROSKERRY-COGERR2003"],relatedIds:["4.3-MG-01"]},{id:"FC-367",ue:"4.3",front:"Le dépistage des red flags précède-t-il ou suit-il le diagnostic fonctionnel ostéopathique ?",back:"Il le précède et le conditionne.",sources:["FNESO-DIAGOPP"],relatedIds:["4.3-RF-01"]},{id:"FC-368",ue:"5.3",front:"Quel diagnostic précède le diagnostic fonctionnel en ostéopathie ?",back:"Le diagnostic d'opportunité, qui recherche les signaux d'alerte imposant une réorientation médicale.",sources:["FNESO-DIAGOPP"],relatedIds:["5.3-KN-01"]},{id:"FC-369",ue:"5.3",front:"Nomme les 5 niveaux de décision du diagnostic d'opportunité.",back:"Traiter, surveiller, orienter, orienter en urgence, urgence vitale.",sources:["FNESO-DIAGOPP"],relatedIds:["5.3-MG-01"]},{id:"FC-370",ue:"5.3",front:"Une contre-indication technique (ex. ostéoporose) impose-t-elle toujours une orientation médicale ?",back:"Non : sans autre signal d'alerte, elle relève d'une décision « surveiller/adapter la technique ».",sources:["NCBI-HVLA-CONTRA"],relatedIds:["5.3-RF-01"]},{id:"FC-371",ue:"5.3",front:"Que risque une manipulation à haute vélocité chez un patient anticoagulé ?",back:"Un risque hémorragique accru, en particulier pour les manipulations cervicales.",sources:["NCBI-ANTICOAG-SAFETY"],relatedIds:["5.3-RF-01"]},{id:"FC-372",ue:"5.3",front:"Quels éléments rendent un filet de sécurité efficace, selon la littérature ?",back:"Des signes concrets à surveiller et un délai/modalité de réévaluation précisés, pas seulement « reconsultez si besoin ».",sources:["SAFETYNET-BJGP2019"],relatedIds:["5.3-MG-02"]},{id:"FC-373",ue:"5.3",front:"Mollet chaud, gonflé et douloureux après immobilisation : que faut-il éviter ?",back:"Le massage ou la mobilisation de la zone avant d'avoir exclu une thrombose veineuse profonde.",sources:["NCBI-DVT"],relatedIds:["5.3-RF-01","CASE-43"]},{id:"FC-374",ue:"5.3",front:"Céphalée, fièvre, raideur de nuque et purpura : quelle conduite ?",back:"Urgence vitale : appel immédiat des urgences, suspicion de méningite ou de sepsis à méningocoque.",sources:["NICE-NG240"],relatedIds:["5.3-MG-01","CASE-45"]},{id:"FC-375",ue:"5.11",front:"Une fracture ou luxation récente sur la zone visée est-elle une contre-indication absolue ou relative aux HVLA ?",back:"Absolue, quelle que soit l'amplitude.",sources:["NCBI-HVLA-CONTRA"],relatedIds:["5.11-MG-01"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-376",ue:"5.11",front:"Que dit le cadre IFOMPT 2020 des anciens tests positionnels cervicaux ?",back:"Les données ne soutiennent pas leur recommandation ; le raisonnement repose sur l'anamnèse, les facteurs de risque et l'examen vasculaire et neurologique.",sources:["IFOMPT-CERVICAL2020"],relatedIds:["5.11-EX-01"],audience:"CLINICAL",difficultyBand:"ADVANCED"},{id:"FC-377",ue:"5.11",front:"Que regroupe la mnémotechnique « 5D et 3N » ?",back:"Des signes d'ischémie vertébro-basilaire (outil d'enseignement, non issu du cadre IFOMPT 2020).",sources:["IFOMPT-CERVICAL2020"],relatedIds:["5.11-EX-01"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-378",ue:"5.11",front:"Que faut-il ajouter à l'information du patient à risque vasculaire avant une technique cervicale ?",back:"Le risque rare de dissection et l'alternative non structurelle.",sources:["IFOMPT-CERVICAL2020"],relatedIds:["5.11-CR-01"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-379",ue:"5.11",front:"Quelle est la première action devant une réaction inattendue pendant une technique ?",back:"Arrêter la technique, puis réévaluer l'état du patient.",sources:["NCBI-HVLA-CONTRA"],relatedIds:["5.11-MG-02"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-380",ue:"5.11",front:"Que faire face au refus informé d'une orientation médicale recommandée ?",back:"Documenter le refus, renforcer le filet de sécurité et poursuivre le suivi.",sources:["FSO-DEONTO"],relatedIds:["5.11-MG-03"],audience:"CLINICAL",difficultyBand:"CLINICAL"},{id:"FC-381",ue:"5.11",front:"Une ostéoporose modérée sans fracture récente est-elle une contre-indication absolue aux HVLA ?",back:"Non : relative, elle impose d'adapter la technique.",sources:["NCBI-OSTEOPOROSIS-FEMALES"],relatedIds:["5.11-MG-01"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-382",ue:"5.12",front:"Quelle est la première action devant un patient inconscient qui ne respire pas normalement ?",back:"Appeler ou faire appeler les secours immédiatement, puis débuter le massage cardiaque sans délai.",sources:["ERC-BLS2021"],relatedIds:["5.12-MG-01"]},{id:"FC-383",ue:"5.12",front:"Quel est le rythme de la réanimation cardio-pulmonaire de base chez l'adulte ?",back:"30 compressions thoraciques pour 2 insufflations, fréquence 100-120/min, profondeur 5-6 cm.",sources:["ERC-BLS2021"],relatedIds:["5.12-MG-01"]},{id:"FC-384",ue:"5.12",front:"Que signifie le score FAST ?",back:"Face (asymétrie faciale), Arm (faiblesse d'un bras), Speech (trouble de la parole), Time (heure de début des symptômes).",sources:["NICE-NG128"],relatedIds:["5.12-RF-01"]},{id:"FC-385",ue:"5.12",front:"Quel est le traitement de première intention d'un choc anaphylactique ?",back:"L'adrénaline par voie intramusculaire, administrée sans délai.",sources:["WAO-ANAPHYLAXIS20"],relatedIds:["5.12-RF-02"]},{id:"FC-386",ue:"5.12",front:"Quels signes évoquent un syndrome de la queue de cheval imposant une orientation immédiate aux urgences ?",back:"Anesthésie en selle, troubles sphinctériens, sciatique bilatérale, dysfonction sexuelle récente.",sources:["NCBI-CAUDA-EQUINA"],relatedIds:["5.12-RF-03"]},{id:"FC-387",ue:"5.12",front:"Quels éléments distinguent un malaise vagal typique d'une urgence cardiaque ?",back:"Un prodrome typique et une récupération rapide et complète en position allongée.",sources:["NICE-CG95"],relatedIds:["5.12-MG-02"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-388",ue:"5.12",front:"Pourquoi noter précisément l'heure de début des symptômes en cas d'AVC suspecté ?",back:"Elle conditionne l'éligibilité à un traitement de reperfusion en urgence, temps-dépendant.",sources:["NICE-NG128"],relatedIds:["5.12-RF-01"]},{id:"FC-389",ue:"4.1",front:"Que fusionne le cadre CIF (ICF) de l'OMS ?",back:"Le modèle médical et le modèle social du handicap, en une approche biopsychosociale.",sources:["WHO-ICF"],relatedIds:["4.1-KN-01"]},{id:"FC-390",ue:"4.1",front:"Au-delà des facteurs contextuels, quelles composantes la CIF décrit-elle chez la personne ?",back:"Fonctions/structures corporelles, activité, participation.",sources:["WHO-ICF"],relatedIds:["4.1-KN-01"]},{id:"FC-391",ue:"4.1",front:"Selon Bialosky, l'effet d'une technique manuelle s'explique par quoi ?",back:"Un stimulus mécanique transitoire déclenchant une cascade neurophysiologique modulée par le contexte.",sources:["BIALOSKY-MT2018"],relatedIds:["4.1-KN-02"]},{id:"FC-392",ue:"4.1",front:"Selon Sackett, quelles composantes la pratique fondée sur les preuves associe-t-elle ?",back:"Meilleures preuves de recherche, expertise clinique, valeurs et préférences du patient.",sources:["SACKETT-EBM1996"],relatedIds:["4.1-KN-03"]},{id:"FC-393",ue:"4.1",front:"Une décision fondée sur une preuve de haut niveau qui ignore les préférences du patient est-elle EBP ?",back:"Non : les trois composantes (preuves, expertise, valeurs du patient) sont indissociables.",sources:["SACKETT-EBM1996"],relatedIds:["4.1-KN-03"]},{id:"FC-394",ue:"4.1",front:"Dans la CIF, à quoi correspond la « participation » ?",back:"L'implication du patient dans une situation de vie réelle (travail, loisirs, vie sociale).",sources:["WHO-ICF"],relatedIds:["4.1-KN-01"]},{id:"FC-395",ue:"4.2",front:"Que désigne la dysfonction somatique ?",back:"Une altération de la fonction régulatrice des éléments squelettiques, arthrodiaux et myofasciaux, avec signes palpables.",sources:["TRAMONTANO-SD2022"],relatedIds:["4.2-KN-01"]},{id:"FC-396",ue:"4.2",front:"Que signifie l'acronyme TART ?",back:"Tissue texture change, Asymmetry, Restriction of motion, Tenderness.",sources:["TRAMONTANO-SD2022"],relatedIds:["4.2-EX-01"]},{id:"FC-397",ue:"4.2",front:"Combien de critères TART suffisent, si nets et reproductibles, pour retenir une dysfonction somatique ?",back:"Un seul critère net et reproductible peut suffire.",sources:["TRAMONTANO-SD2022"],relatedIds:["4.2-EX-01"]},{id:"FC-398",ue:"4.2",front:"Que montrent les revues systématiques sur la fiabilité inter-examinateurs de la palpation ?",back:"Une fiabilité hétérogène, souvent faible à modérée selon les tests et régions.",sources:["BASILE-OSTEORELI2017"],relatedIds:["4.2-KN-02"]},{id:"FC-399",ue:"4.2",front:"Quelle conséquence pratique tirer de la fiabilité modeste de la palpation isolée ?",back:"Ne pas fonder une décision sur un signe isolé ; rechercher la convergence avec l'anamnèse et la réponse au traitement.",sources:["BASILE-OSTEORELI2017"],relatedIds:["4.2-KN-02"]},{id:"FC-400",ue:"4.2",front:"Comment choisir une technique selon le modèle diagnostique de la dysfonction somatique ?",back:"En la faisant correspondre à la dysfonction identifiée et au profil du patient, après vérification des contre-indications.",sources:["TRAMONTANO-SD2022"],relatedIds:["4.2-MG-01"]},{id:"FC-401",ue:"4.3",front:"Qu'est-ce que le biais de disponibilité en raisonnement clinique ?",back:"Privilégier le diagnostic le plus fréquent ou le plus récemment rencontré plutôt que celui suggéré par les données présentes.",sources:["CROSKERRY-COGERR2003"],relatedIds:["4.3-MG-01"]},{id:"FC-402",ue:"4.3",front:"Qu'est-ce que le biais de confirmation en raisonnement clinique ?",back:"Rechercher préférentiellement les éléments qui confirment l'hypothèse favorite plutôt que ceux qui pourraient l'infirmer.",sources:["CROSKERRY-COGERR2003"],relatedIds:["4.3-MG-01"]},{id:"FC-403",ue:"4.3",front:"Quelle est la différence entre pattern recognition et raisonnement analytique ?",back:"Schéma : rapide, fondé sur l'expérience de cas similaires. Analytique : plus lent, nécessaire si présentation atypique.",sources:["JONES-CRM1992","CROSKERRY-COGERR2003"],relatedIds:["4.3-KN-03"]},{id:"FC-404",ue:"5.3",front:"L'examen révèle un signe inattendu alors que l'anamnèse était rassurante : que fait-on ?",back:"Prioriser le signe d'examen objectif et reconsidérer l'hypothèse initiale, sans l'écarter parce que l'histoire semblait bénigne.",sources:["FNESO-DIAGOPP","SAFETYNET-BJGP2019"],relatedIds:["5.3-DX-01"]},{id:"FC-405",ue:"5.3",front:"Quels éléments imposent de réviser une décision « traiter » en cours de suivi ?",back:"Absence d'amélioration après un délai raisonnable, apparition d'un nouveau red flag, ou aggravation malgré un traitement adapté.",sources:["SAFETYNET-BJGP2019"],relatedIds:["5.3-MG-03"]},{id:"FC-406",ue:"5.3",front:"Deux hypothèses restent également plausibles après un recueil complet : quelle conduite ?",back:"Choisir l'option la plus prudente compatible avec les données, documenter les deux hypothèses, et rapprocher la réévaluation.",sources:["SACKETT-EBM1996"],relatedIds:["4.3-DX-02"]},{id:"FC-407",ue:"5.11",front:"Deux comorbidités relatives coexistent, aucune n'étant absolue : que fait-on ?",back:"On les pondère pour choisir la technique la moins invasive utile, sans refus systématique.",sources:["NCBI-HVLA-CONTRA"],relatedIds:["5.11-MG-04"],audience:"CLINICAL",difficultyBand:"ADVANCED"},{id:"FC-408",ue:"5.11",front:"Quels éléments la trace écrite d'une décision clinique doit-elle comporter au minimum ?",back:"Éléments recueillis, décision, filet de sécurité et consentement si technique à risque.",sources:["FSO-DEONTO"],relatedIds:["5.11-CR-02"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-409",ue:"5.11",front:"Patient anticoagulé et ostéoporotique sans contre-indication absolue : quelle technique privilégier ?",back:"Une technique de moindre amplitude ou non structurelle, avec information et consentement.",sources:["NCBI-ANTICOAG-SAFETY","NCBI-SECONDARY-OSTEOPOROSIS"],relatedIds:["5.11-MG-04"],audience:"CLINICAL",difficultyBand:"ADVANCED"},{id:"FC-410",ue:"5.12",front:"Plusieurs signaux d'alerte apparaissent en même temps chez un patient : que priorise-t-on ?",back:"La conscience et la respiration d'abord, puis les signes de choc ou d'ischémie, puis les signes neurologiques focaux.",sources:["ERC-BLS2021"],relatedIds:["5.12-MG-03"]},{id:"FC-411",ue:"5.12",front:"Pourquoi l'ischémie myocardique peut-elle passer inaperçue chez un patient âgé ou diabétique ?",back:"La neuropathie autonome liée à l'âge ou au diabète atténue ou masque la douleur thoracique typique.",sources:["OCHIAI-MI-ATYPICAL-ELDERLY"],relatedIds:["5.12-DX-01"]},{id:"FC-412",ue:"5.12",front:"Chez un patient à risque cardiovasculaire, quel symptôme discret doit alerter même sans douleur thoracique ?",back:"Une dyspnée d'effort inhabituelle et récente, associée ou non à des signes discrets de mauvaise tolérance (tachycardie, pâleur, sueurs).",sources:["OCHIAI-MI-ATYPICAL-ELDERLY","NICE-CG95"],relatedIds:["5.12-DX-01"]},{id:"FC-413",ue:"1.6",front:"Quels signes caractérisent une atteinte du motoneurone supérieur ?",back:"Hyperréflexie, spasticité, clonus, signe de Babinski positif, sans amyotrophie précoce.",sources:["NCBI-UMN-SIGNS"],relatedIds:["1.6-DX-02"]},{id:"FC-414",ue:"1.6",front:"Quels signes caractérisent une atteinte du motoneurone inférieur ?",back:"Hypotonie, hyporéflexie ou aréflexie, amyotrophie, fasciculations, signe de Babinski absent.",sources:["NCBI-LMN-LESION"],relatedIds:["1.6-DX-02"]},{id:"FC-415",ue:"1.6",front:"Pourquoi vérifier la cohérence entre myotome, dermatome et réflexe du même niveau ?",back:"Une atteinte cohérente sur les trois est un argument fort pour une radiculopathie ; un déficit isolé est moins spécifique.",sources:["NCBI-CERVICAL-RADIC","NCBI-DERMATOMES"],relatedIds:["1.6-DX-03"],audience:"CLINICAL",difficultyBand:"ADVANCED"},{id:"FC-416",ue:"1.9",front:"Que signifie une défense abdominale involontaire à la palpation ?",back:"Un signe d'irritation péritonéale, évocateur d'un abdomen chirurgical imposant une orientation en urgence.",sources:["NCBI-ACUTE-ABDOMEN"],relatedIds:["1.9-DX-01"]},{id:"FC-417",ue:"1.9",front:"Qu'est-ce que le signe de rebond (douleur à la décompression brusque) ?",back:"Une douleur déclenchée au relâchement soudain de la palpation abdominale, évocatrice d'une irritation péritonéale.",sources:["NCBI-ABDOMINAL-EXAM"],relatedIds:["1.9-DX-01"]},{id:"FC-418",ue:"1.4",front:"Comment se calcule le moment de force (torque) exercé sur une articulation ?",back:"Torque = force appliquée × longueur du bras de levier (distance perpendiculaire entre l'axe et la ligne d'action de la force).",sources:["OPENSTAX-CP-9-2","LIBRETEXTS-BODY-LEVERS"],relatedIds:["1.4-KN-01"]},{id:"FC-419",ue:"1.4",front:"Comment réagissent tendon et os face à une contrainte mécanique croissante ?",back:"Tendon : élastique jusqu'à un seuil, puis plus rigide. Os : rigide, cassant au-delà de sa limite d'élasticité.",sources:["LIBRETEXTS-TENDON-BONE"],relatedIds:["1.4-KN-05"]},{id:"FC-420",ue:"1.7",front:"Que signifie un grade 3 sur l'échelle MRC de force musculaire ?",back:"Le mouvement actif est possible contre la gravité, mais pas contre une résistance ajoutée par l'examinateur.",sources:["NCBI-MRC-SCALE"],relatedIds:["1.7-EX-01"]},{id:"FC-421",ue:"1.7",front:"Quel mécanisme sous-tend la contraction du muscle squelettique ?",back:"Le glissement de l'actine sur la myosine, déclenché par le calcium et l'hydrolyse de l'ATP.",sources:["OPENSTAX-MUSCLE-CONTRACTION"],relatedIds:["1.7-KN-03"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-422",ue:"5.11",front:"Céphalée brutale pendant une mobilisation cervicale : quelle conduite ?",back:"Interrompre la technique et orienter en urgence : cause vasculaire grave possible.",sources:["IFOMPT-CERVICAL2020"],relatedIds:["5.11-EX-01"],audience:"CLINICAL",difficultyBand:"CLINICAL"},{id:"FC-423",ue:"5.12",front:"Sciatique bilatérale avec anesthésie en selle : conduite ?",back:"Orientation chirurgicale en urgence, ce tableau évoquant un syndrome de la queue de cheval.",sources:["NCBI-CAUDA-EQUINA"],relatedIds:["5.12-RF-03"]},{id:"FC-424",ue:"5.12",front:"Prodrome typique et récupération rapide allongé : quelle cause évoquer en premier ?",back:"Un malaise vagal, si la récupération est réellement rapide et complète.",sources:["NICE-CG95"],relatedIds:["5.12-MG-02"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-425",ue:"5.11",front:"L'anticoagulation stable sans saignement actif contre-indique-t-elle toute technique manuelle ?",back:"Non : contre-indication relative, qui impose d'adapter la technique.",sources:["NCBI-ANTICOAG-SAFETY"],relatedIds:["5.11-MG-04"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-426",ue:"2.5",front:"Douleur de coude : la localisation suffit-elle à désigner la source ?",back:"Non — différentiel à discuter : tendinopathie, traumatisme, arthrose/arthrite du coude, compression nerveuse, douleur cervicale projetée.",sources:["UE25-PACK-V2"],relatedIds:["2.5-RF-23"]},{id:"FC-427",ue:"2.5",front:"Douleur de poignet/main : quel examen permet de trier le large éventail de causes possibles ?",back:"Un examen comparatif : sensibilité, force, mobilité, gonflement, température/couleur et territoire nerveux.",sources:["UE25-PACK-V2"],relatedIds:["2.5-RF-24"]},{id:"FC-428",ue:"2.6",front:"Douleur thoracique reproduite à la palpation : que peut-on conclure ?",back:"Une origine pariétale est possible, mais une cause cardiaque n'est pas exclue.",sources:["NICE-CG95","NCBI-PE"],relatedIds:["2.6-DX-01"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-429",ue:"2.6",front:"Douleur thoracique/dyspnée : quand appeler les secours immédiatement plutôt qu'organiser un avis médical rapide ?",back:"Douleur évocatrice de SCA ou de dissection ; dyspnée grave (SpO2 < 90 %, incapacité à parler, cyanose, confusion) ; syncope associée.",sources:["NICE-CG95","NCBI-DYSPNEA","NCBI-HF"],relatedIds:["2.6-MG-01"]},{id:"FC-430",ue:"2.9",front:"Éruption cutanée fébrile : quel test distingue un érythème d'un purpura ?",back:"La vitropression : une lésion qui s'efface est un érythème, une lésion qui persiste est un purpura.",sources:["NCBI-CADR","NCBI-SJS-TEN"],relatedIds:["2.9-DX-01"]},{id:"FC-431",ue:"2.8",front:"Douleur scrotale aiguë d'installation brutale : quelle urgence chirurgicale orienter sans délai, sans attendre l'imagerie ?",back:"La torsion testiculaire.",sources:["NCBI-TESTICULAR-TORSION"],relatedIds:["2.8-MG-01"]},{id:"FC-432",ue:"4.1",front:"Dans le raisonnement ostéopathique contemporain, que structure respectivement le cadre CIF, le modèle mécanistique et la pratique fondée sur les preuves ?",back:"CIF : ce qu'il faut évaluer. Modèle mécanistique : pourquoi une technique peut agir. Pratique fondée sur les preuves : comment décider en intégrant preuves, expertise et préférences du patient.",sources:["WHO-ICF","BIALOSKY-MT2018"],relatedIds:["4.1-CR-01"]},{id:"FC-433",ue:"1.8",front:"Formule du débit cardiaque et ses deux déterminants directs ?",back:"DC = FC × VES (fréquence cardiaque × volume d'éjection systolique).",sources:["NCBI-CARDIAC-OUTPUT"],relatedIds:["1.8-KN-03"]},{id:"FC-434",ue:"2.3",front:"Appendicite aiguë : quelle proportion de présentations est atypique ?",back:"Plus de 50 % (nourrisson, enfant, personne âgée, femme enceinte).",sources:["MSD-APPENDICITIS"],relatedIds:["2.3-DX-02"]},{id:"FC-435",ue:"2.6",front:"Pneumonie communautaire chez la personne âgée : quels signes remplacent souvent la fièvre et la toux typiques ?",back:"La fièvre est souvent absente ; confusion ou obnubilation possibles, avec délirium chez environ 20 % des patients (mauvais pronostic).",sources:["MSD-CAP"],relatedIds:["2.6-DX-02"]},{id:"FC-436",ue:"1.8",front:"Où le rapport V/Q est-il égal à 1 dans le poumon ?",back:"Au milieu du poumon ; il est abaissé à la base.",sources:["NCBI-PULM-VENT-PERFUSION"],relatedIds:["1.8-KN-04"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-437",ue:"1.8",front:"De combien la ventilation alvéolaire augmente-t-elle quand le pH du LCR passe de 7,30 à 7,25 ?",back:"Elle double : les chémorécepteurs centraux sont extrêmement sensibles au pH du LCR.",sources:["PMC-CENTRAL-CHEMORECEPTORS"],relatedIds:["1.8-KN-05"],audience:"STUDENT",difficultyBand:"ADVANCED"},{id:"FC-438",ue:"2.7",front:"Quel est le signe clinique précoce le plus caractéristique de l'ischémie mésentérique aiguë, avant l'infarctus intestinal ?",back:"Douleur sévère avec abdomen souple et peu sensible (« douleur disproportionnée à l'examen ») ; la péritonite n'apparaît qu'après la nécrose.",sources:["MSD-MESENTERIC-ISCHEMIA"],relatedIds:["2.7-RF-06"]},{id:"FC-439",ue:"2.6",front:"Devant une suspicion de pneumothorax compressif (tension), faut-il attendre la radiographie thoracique avant de traiter ?",back:"Non : le diagnostic est clinique ; décompression à l'aiguille sans attendre l'imagerie.",sources:["MSD-PNEUMOTHORAX"],relatedIds:["2.6-RF-04"]},{id:"FC-440",ue:"1.8",front:"Quel mécanisme définit le choc cardiogénique ?",back:"Une défaillance de la pompe cardiaque.",sources:["MSD-SHOCK"],relatedIds:["1.8-KN-06"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-441",ue:"1.9",front:"Équilibre acido-basique : quels sont les 3 mécanismes de régulation de l'organisme ?",back:"Tamponnement chimique (immédiat), compensation respiratoire, compensation rénale.",sources:["MSD-ACID-BASE-REG"],relatedIds:["1.9-KN-05"]},{id:"FC-442",ue:"1.6",front:"Où se situent les corps cellulaires préganglionnaires sympathiques ?",back:"Dans la corne intermédiolatérale de la moelle, de T1 à L2-L3 (voie thoraco-lombaire).",sources:["MSD-ANS-OVERVIEW"],relatedIds:["1.6-KN-03"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-443",ue:"2.4",front:"Asymétrie faciale aiguë chez un patient qui peut froncer les sourcils des deux côtés : atteinte centrale ou périphérique ?",back:"Centrale : à traiter comme un AVC suspecté (FAST, urgence). Dans une atteinte périphérique (Bell), le front est atteint.",sources:["NICE-CKS-BELLSPALSY"],relatedIds:["2.4-RF-05"]},{id:"FC-444",ue:"3.5",front:"Quelle règle commune France-Suisse pose l'art. 5 de la Convention d'Oviedo ?",back:"Pas d'intervention dans le domaine de la santé sans consentement libre et éclairé, retirable à tout moment.",sources:["COE-OVIEDO"],relatedIds:["3.5-KN-03"],jurisdiction:"COMMON"},{id:"FC-445",ue:"3.5",front:"Depuis quand la Convention d'Oviedo est-elle en vigueur pour la Suisse et pour la France ?",back:"Suisse : 1er novembre 2008. France : 1er avril 2012.",sources:["COE-OVIEDO"],relatedIds:["3.5-KN-03"],jurisdiction:"COMMON"},{id:"FC-446",ue:"3.4",front:"France : quelles obligations accompagnent l'usage professionnel du titre d'ostéopathe ?",back:"Diplôme ou autorisation réglementé, enregistrement auprès de l'ARS, formation continue, et assurance RC pour l'exercice libéral.",sources:["LEGIFRANCE-LOI-2002-303","LEGIFRANCE-DECRET-2007-435","LEGIFRANCE-LOI-2014-201"],relatedIds:["3.4-KN-03"],jurisdiction:"FR"},{id:"FC-447",ue:"3.4",front:"France : quelles manipulations l'art. 3, II du décret 2007-435 soumet-il à un diagnostic médical attestant l'absence de contre-indication ?",back:"Celles du rachis cervical, et celles du crâne, de la face et du rachis chez le nourrisson de moins de six mois.",sources:["LEGIFRANCE-DECRET-2007-435"],relatedIds:["3.4-MG-02"],jurisdiction:"FR"},{id:"FC-448",ue:"3.4",front:"France : deux actes interdits à l'ostéopathe (décret 2007-435, art. 3, I) ?",back:"Les manipulations gynéco-obstétricales et les touchers pelviens.",sources:["LEGIFRANCE-DECRET-2007-435"],relatedIds:["3.4-MG-02"],jurisdiction:"FR"},{id:"FC-449",ue:"3.4",front:"Suisse : qui surveille les ostéopathes exerçant sous propre responsabilité ?",back:"L'autorité cantonale de surveillance (art. 17).",sources:["FEDLEX-LPSAN"],relatedIds:["3.4-KN-04"],jurisdiction:"CH"},{id:"FC-450",ue:"3.4",front:"Suisse : l'art. 321 CP vise-t-il les ostéopathes ? Peine encourue ?",back:"Oui, expressément (avec leurs auxiliaires) : peine privative de liberté de 3 ans au plus ou peine pécuniaire, sur plainte.",sources:["FEDLEX-CP"],relatedIds:["3.4-MG-03"],jurisdiction:"CH"},{id:"FC-451",ue:"3.3",front:"Suisse : l'autorisation LPSan suffit-elle à pratiquer à la charge de l'assurance obligatoire ?",back:"Non : l'admission à la charge de l'assurance obligatoire (LAMal, art. 36) est un régime distinct de l'autorisation LPSan.",sources:["FEDLEX-LAMAL"],relatedIds:["3.3-KN-01"],jurisdiction:"CH"},{id:"FC-452",ue:"3.5",front:"France : peut-on citer l'art. L1111-4 CSP comme base directe du consentement de l'ostéopathe ?",back:"Non, pas sans base explicite : il vise le « professionnel de santé ». On retient un principe général (Code civil art. 16-3).",sources:["LEGIFRANCE-CSP-L1111-4","LEGIFRANCE-CC-16-3"],relatedIds:["3.5-KN-04"],jurisdiction:"FR"},{id:"FC-453",ue:"3.5",front:"Que prévoit l'art. 16-3 du Code civil sur le consentement ?",back:"Consentement préalable avant toute atteinte à l'intégrité du corps, sauf nécessité thérapeutique chez une personne hors d'état de consentir.",sources:["LEGIFRANCE-CC-16-3"],relatedIds:["3.5-KN-04"],jurisdiction:"FR"},{id:"FC-454",ue:"3.4",front:"En France, comment secret professionnel, consentement et données personnelles s'articulent-ils ?",back:"Trois régimes distincts : secret (CP 226-13, CSP L1110-4), consentement (3.5-KN-04), données personnelles (RGPD).",sources:["LEGIFRANCE-CP-226-13","LEGIFRANCE-CSP-L1110-4","CNIL-RGPD-TEXTE"],relatedIds:["3.4-MG-04"],jurisdiction:"FR"},{id:"FC-455",ue:"3.4",front:"RGPD : qui est le responsable du traitement (art. 4, pt 7) ?",back:"Celui qui détermine les finalités et les moyens du traitement : définition fonctionnelle, non liée à un statut.",sources:["CNIL-RGPD-TEXTE"],relatedIds:["3.4-MG-04"],jurisdiction:"FR"},{id:"FC-456",ue:"3.5",front:"Suisse : le consentement du patient relève-t-il d'une seule règle nationale ?",back:"Non : devoir fédéral (LPSan art. 16, let. d), précisé par le droit cantonal (ex. Vaud, LSP art. 23) à vérifier canton par canton.",sources:["FEDLEX-LPSAN","VD-CONSENTEMENT"],relatedIds:["3.5-KN-05"],jurisdiction:"CH"},{id:"FC-457",ue:"3.5",front:"Suisse : exceptions au consentement décrites par l'OFSP ?",back:"Urgence (intérêt présumé du patient) et incapacité de discernement (volonté présumée, directives anticipées, représentant).",sources:["BAG-CONSENTEMENT"],relatedIds:["3.5-KN-05"],jurisdiction:"CH"},{id:"FC-458",ue:"3.4",front:"LPD : les données de santé sont-elles sensibles ?",back:"Oui (art. 5, let. c, ch. 2) : consentement exprès si un consentement est requis (art. 6, al. 7).",sources:["FEDLEX-LPD"],relatedIds:["3.4-KN-05"],jurisdiction:"CH"},{id:"FC-459",ue:"3.4",front:"LPD : que doit-on communiquer au moins à la collecte (art. 19) ?",back:"Identité et coordonnées du responsable, finalité du traitement, destinataires le cas échéant.",sources:["FEDLEX-LPD"],relatedIds:["3.4-KN-05"],jurisdiction:"CH"},{id:"FC-460",ue:"3.3",front:"France : quand appeler le 15, et quand le 116 117 ?",back:"15 : urgence médicale (Samu). 116 117 : garde médicale quand le médecin habituel est indisponible.",sources:["SERVICE-PUBLIC-F33954"],relatedIds:["3.3-KN-02"],jurisdiction:"FR"},{id:"FC-461",ue:"3.3",front:"France : quel rôle pour le médecin traitant ?",back:"Premier niveau de recours aux soins et coordination du suivi médical.",sources:["SERVICE-PUBLIC-F163"],relatedIds:["3.3-KN-02"],jurisdiction:"FR"},{id:"FC-462",ue:"3.3",front:"Suisse : quel numéro appeler pour les ambulances ?",back:"144.",sources:["BAKOM-URGENCES"],relatedIds:["3.3-KN-03"],jurisdiction:"CH"},{id:"FC-463",ue:"3.3",front:"Suisse : que garantit l'art. 117a de la Constitution ?",back:"L'accès de chacun à des soins médicaux de base suffisants et de qualité (Confédération et cantons).",sources:["BAG-MASTERPLAN"],relatedIds:["3.3-KN-03"],jurisdiction:"CH"},{id:"FC-464",ue:"6.1",front:"Que signifie PICO ?",back:"Population, Intervention, Comparaison(s), Outcome (critère de jugement).",sources:["COCHRANE-HB-C01"],relatedIds:["6.1-KN-01"],jurisdiction:"COMMON"},{id:"FC-465",ue:"6.1",front:"Les trois composantes de la pratique fondée sur les preuves (Sackett, 1996) ?",back:"Données de la recherche, expertise clinique, valeurs du patient.",sources:["SACKETT-EBM1996"],relatedIds:["6.1-KN-01"],jurisdiction:"COMMON"},{id:"FC-466",ue:"6.2",front:"Biais ou imprécision : lequel est une erreur systématique ?",back:"Le biais. L'imprécision est une erreur aléatoire, liée à l'échantillonnage.",sources:["COCHRANE-HB-C07"],relatedIds:["6.2-KN-01"],jurisdiction:"COMMON"},{id:"FC-467",ue:"6.2",front:"Dissimulation de l'allocation ou aveugle : lequel agit avant l'affectation ?",back:"La dissimulation de l'allocation (elle empêche l'enrôlement sélectif). L'aveugle agit après l'affectation.",sources:["COCHRANE-HB-C08"],relatedIds:["6.2-KN-01"],jurisdiction:"COMMON"},{id:"FC-468",ue:"6.2",front:"Sensibilité et spécificité : définitions ?",back:"Sensibilité : test positif parmi les malades. Spécificité : test négatif parmi les non-malades.",sources:["TREVETHAN-2017"],relatedIds:["6.2-KN-02"],jurisdiction:"COMMON"},{id:"FC-469",ue:"6.2",front:"Quel indicateur diagnostique varie avec la prévalence ?",back:"Les valeurs prédictives (VPP et VPN), contrairement à la sensibilité et à la spécificité.",sources:["TREVETHAN-2017"],relatedIds:["6.2-KN-02"],jurisdiction:"COMMON"},{id:"FC-470",ue:"6.2",front:"Formules du LR+ et du LR− ?",back:"LR+ = sensibilité / (1 − spécificité) ; LR− = (1 − sensibilité) / spécificité.",sources:["AKOBENG-2007"],relatedIds:["6.2-KN-03"],jurisdiction:"COMMON"},{id:"FC-471",ue:"6.2",front:"Comment passer de la probabilité pré-test à la probabilité post-test ?",back:"Probabilité → cote (p / (1 − p)), multiplier par le LR, puis cote → probabilité (cote / (1 + cote)).",sources:["AKOBENG-2007"],relatedIds:["6.2-KN-03"],jurisdiction:"COMMON"},{id:"FC-472",ue:"6.2",front:"Un rapport de risque de 0,75 signifie quoi en termes relatifs ?",back:"Une réduction relative du risque de 25 % ; la réduction absolue dépend du risque de base.",sources:["COCHRANE-HB-C15"],relatedIds:["6.2-KN-04"],jurisdiction:"COMMON"},{id:"FC-473",ue:"6.2",front:"Que mesure le nombre de sujets à traiter (NNT) dans un essai ?",back:"Le nombre de personnes à traiter avec l'intervention plutôt que le comparateur pour qu'une personne de plus évite l'événement.",sources:["COCHRANE-HB-C15"],relatedIds:["6.2-KN-04"],jurisdiction:"COMMON"},{id:"FC-474",ue:"7.3",front:"Les trois étapes du modèle de décision partagée (Elwyn, 2012) ?",back:"Choice talk, option talk, decision talk.",sources:["ELWYN-2012"],relatedIds:["7.3-KN-01"],jurisdiction:"COMMON"},{id:"FC-475",ue:"7.3",front:"Qu'est-ce que le teach-back ?",back:"Demander au patient de décrire avec ses mots ce qu'il vient d'entendre, pour évaluer sa compréhension.",sources:["WHO-HANDOVER-2007"],relatedIds:["7.3-KN-01"],jurisdiction:"COMMON"},{id:"FC-476",ue:"7.3",front:"Qu'est-ce que le filet de sécurité (Jones, 2019) ?",back:"Technique de consultation : communiquer l'incertitude, informer sur les signes d'alarme, planifier une réévaluation en temps utile.",sources:["JONES-2019"],relatedIds:["7.3-CR-01"],jurisdiction:"COMMON"},{id:"FC-477",ue:"7.3",front:"Que signifie SBAR ?",back:"Situation, Background (contexte), Assessment (évaluation), Recommendation : cadre de transmission suggéré par l'OMS (2007).",sources:["WHO-HANDOVER-2007"],relatedIds:["7.3-MG-01"],jurisdiction:"COMMON"},{id:"FC-478",ue:"7.3",front:"Définition OMS d'un quasi-accident (near miss) ?",back:"Incident qui n'a pas atteint le patient.",sources:["WHO-PSCG-2011"],relatedIds:["7.3-MG-02"],jurisdiction:"COMMON"},{id:"FC-479",ue:"7.3",front:"Open disclosure : de quoi s'agit-il ?",back:"Communication honnête avec le patient ou sa famille après un événement indésirable, sans chercher à répartir la faute (OMS, 2011).",sources:["WHO-PSCG-2011"],relatedIds:["7.3-MG-02"],jurisdiction:"COMMON"},{id:"FC-480",ue:"7.3",front:"Que conclut le guide OMS sur les limites de compétence et l'aide ?",back:"Reconnaître ses limites et savoir demander de l'aide est essentiel (guide OMS ; contexte de formation, extrapolé à la pratique libérale).",sources:["WHO-PSCG-2011"],relatedIds:["7.3-KN-02"],jurisdiction:"COMMON"},{id:"FC-481",ue:"7.3",front:"NICE NG59 : que faire à chaque réévaluation d'une lombalgie ?",back:"Envisager d'autres diagnostics (surtout si symptômes nouveaux ou modifiés), exclure les causes spécifiques ; orienter si gravité suspectée.",sources:["NICE-NG59"],relatedIds:["7.3-CR-02"],jurisdiction:"COMMON"},{id:"FC-482",ue:"6.2",front:"GRADE : niveau de preuve ≠ ?",back:"Force de la recommandation : une preuve de haute qualité n'implique pas nécessairement une recommandation forte, et inversement.",sources:["GRADE-GUYATT-2008"],relatedIds:["6.2-KN-05"],jurisdiction:"COMMON"},{id:"FC-483",ue:"6.2",front:"Cinq critères qui peuvent abaisser la confiance dans la preuve (GRADE 2008) ?",back:"Limites des études, incohérence, caractère indirect, imprécision, biais de notification.",sources:["GRADE-GUYATT-2008"],relatedIds:["6.2-KN-05"],jurisdiction:"COMMON"},{id:"FC-484",ue:"6.2",front:"Fiabilité vs validité (COSMIN) ?",back:"Fiabilité : degré d'exemption d'erreur de mesure ; validité : mesure du construit visé. Un outil fiable peut être non valide.",sources:["COSMIN-TAXONOMY"],relatedIds:["6.2-KN-06"],jurisdiction:"COMMON"},{id:"FC-485",ue:"6.2",front:"MDC et MIC : que mesure chacun de ces deux seuils ?",back:"MDC : plus petit changement détectable statistiquement. MIC : plus petit changement jugé important par les patients en moyenne.",sources:["TERWEE-MIC-2021"],relatedIds:["6.2-KN-06"],jurisdiction:"COMMON"},{id:"FC-486",ue:"1.9",front:"Quelle hormone est la principale hormone de régulation de la calcémie ?",back:"La PTH, produite par les cellules principales des parathyroïdes.",sources:["OPENSTAX-AP-17-5"],relatedIds:["1.9-KN-06"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-487",ue:"1.9",front:"Quel est l'effet de la calcitonine sur les ostéoclastes ?",back:"Elle les inhibe (et stimule les ostéoblastes), ce qui abaisse la calcémie.",sources:["OPENSTAX-AP-17-5"],relatedIds:["1.9-KN-06"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-488",ue:"1.9",front:"Quel risque en cas d'hypocalcémie sévère par déficit en PTH ?",back:"Spasmes et convulsions, voire paralysie des muscles respiratoires.",sources:["OPENSTAX-AP-17-5"],relatedIds:["1.9-KN-06"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-489",ue:"1.9",front:"Quelle cellule des îlots pancréatiques sécrète l'insuline ?",back:"La cellule bêta.",sources:["OPENSTAX-AP-17-9"],relatedIds:["1.9-KN-07"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-490",ue:"1.9",front:"Quel est l'effet du glucagon sur le foie ?",back:"Il stimule la glycogénolyse et la néoglucogenèse, ce qui élève la glycémie.",sources:["OPENSTAX-AP-17-9"],relatedIds:["1.9-KN-07"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-491",ue:"1.9",front:"Quel mécanisme est à l'origine du diabète de type 2 ?",back:"Une résistance des cellules à l'action de l'insuline.",sources:["OPENSTAX-AP-17-9"],relatedIds:["1.9-KN-07"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-492",ue:"1.9",front:"Pourquoi le rein droit est-il un peu plus bas que le gauche ?",back:"À cause du foie, qui le refoule vers le bas.",sources:["NCBI-KIDNEY-ANATOMY"],relatedIds:["1.9-KN-08"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-493",ue:"1.9",front:"Quelle fraction du débit cardiaque traverse les reins au repos ?",back:"Environ 25 %.",sources:["OPENSTAX-AP-25-3"],relatedIds:["1.9-KN-08"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-494",ue:"1.9",front:"Quelle voie nerveuse contracte le détrusor lors de la miction ?",back:"Le parasympathique, par les nerfs pelviens.",sources:["OPENSTAX-AP-25-2"],relatedIds:["1.9-KN-09"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-495",ue:"1.9",front:"Quelle voie nerveuse inhibe le détrusor pendant le remplissage vésical ?",back:"Le sympathique, par les nerfs hypogastriques.",sources:["OPENSTAX-AP-25-2"],relatedIds:["1.9-KN-09"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-496",ue:"1.9",front:"Quelle est la nature du sphincter externe de l'urètre ?",back:"Un muscle squelettique volontaire, innervé par le nerf pudendal.",sources:["OPENSTAX-AP-25-2"],relatedIds:["1.9-KN-09"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-497",ue:"1.9",front:"Quel ligament utérin, repli péritonéal, en est le principal soutien ?",back:"Le ligament large.",sources:["OPENSTAX-AP-27-2"],relatedIds:["1.9-KN-10"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-498",ue:"1.9",front:"Quelle hormone domine la phase sécrétoire du cycle menstruel ?",back:"La progestérone, sécrétée par le corps jaune.",sources:["OPENSTAX-AP-27-2"],relatedIds:["1.9-KN-10"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-499",ue:"1.9",front:"Quelle cellule testiculaire produit la testostérone sous l'effet de la LH ?",back:"La cellule de Leydig.",sources:["OPENSTAX-AP-27-1"],relatedIds:["1.9-KN-11"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-500",ue:"1.9",front:"Quelle cellule testiculaire soutient la spermatogenèse sous l'effet de la FSH ?",back:"La cellule de Sertoli.",sources:["OPENSTAX-AP-27-1"],relatedIds:["1.9-KN-11"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-501",ue:"1.9",front:"Le PSA est-il spécifique du cancer de la prostate ?",back:"Non : hypertrophie bénigne, prostatite et traumatisme l'élèvent aussi.",sources:["NCBI-PSA"],relatedIds:["1.9-KN-11"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-502",ue:"2.8",front:"Quelle est la triade classique de la grossesse extra-utérine ?",back:"Douleur pelvienne, saignement vaginal, test de grossesse positif.",sources:["NCBI-ECTOPIC"],relatedIds:["2.8-RF-06"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-503",ue:"2.8",front:"Où siège la grossesse extra-utérine dans environ 97 % des cas ?",back:"Dans la trompe utérine, le plus souvent l'ampoule.",sources:["NCBI-ECTOPIC"],relatedIds:["2.8-RF-06"],audience:"BOTH",difficultyBand:"FOUNDATION"},{id:"FC-504",ue:"2.8",front:"Quelle douleur à distance évoque une rupture de grossesse extra-utérine ?",back:"Une douleur d'épaule.",sources:["NCBI-ECTOPIC"],relatedIds:["2.8-RF-06"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-505",ue:"2.8",front:"Quel examen est la référence pour confirmer une grossesse extra-utérine ?",back:"L'échographie endovaginale.",sources:["NCBI-ECTOPIC"],relatedIds:["2.8-RF-06"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-506",ue:"2.8",front:"Quel seuil de DFG et quelle durée définissent l'insuffisance rénale chronique ?",back:"DFG estimé inférieur à 60 mL/min/1,73 m² (ou lésion rénale) pendant au moins 3 mois.",sources:["NCBI-CKD"],relatedIds:["2.8-DX-03"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-507",ue:"2.8",front:"Quelle catégorie d'insuffisance rénale aiguë répond au remplissage vasculaire ?",back:"La forme prérénale : la créatinine redescend en 24 à 72 h.",sources:["NCBI-AKI"],relatedIds:["2.8-DX-03"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-508",ue:"2.8",front:"Pourquoi les AINS sont-ils à éviter chez un patient à risque rénal ?",back:"Ils sont néphrotoxiques et peuvent déclencher ou aggraver une insuffisance rénale.",sources:["NCBI-AKI","NCBI-CKD"],relatedIds:["2.8-DX-03"],audience:"BOTH",difficultyBand:"FOUNDATION"},{id:"FC-509",ue:"2.8",front:"Quels signes distinguent la pyélonéphrite de la cystite non compliquée ?",back:"La fièvre et la douleur de flanc avec sensibilité costo-vertébrale.",sources:["NCBI-PYELONEPHRITIS","NCBI-CYSTITIS"],relatedIds:["2.8-DX-04"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-510",ue:"2.8",front:"Qu'est-ce qu'une pyonéphrose ?",back:"Une pyélonéphrite obstructive : urgence chirurgicale de drainage.",sources:["NCBI-PYELONEPHRITIS"],relatedIds:["2.8-DX-04"],audience:"CLINICAL",difficultyBand:"ADVANCED"},{id:"FC-511",ue:"2.8",front:"Quel seuil de tension artérielle alerte lors d'une pyélonéphrite fébrile ?",back:"Systolique inférieure à 90 mmHg : sepsis possible.",sources:["NCBI-PYELONEPHRITIS"],relatedIds:["2.8-DX-04"],audience:"CLINICAL",difficultyBand:"ADVANCED"},{id:"FC-512",ue:"2.7",front:"Quelle est la cause la plus fréquente d'insuffisance surrénalienne primaire ?",back:"L'atteinte auto-immune du cortex surrénalien (maladie d'Addison).",sources:["PUBMED-ADDISON"],relatedIds:["2.7-RF-07"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-513",ue:"2.7",front:"Quelle perturbation du potassium et du sodium accompagne la crise surrénalienne ?",back:"Hyperkaliémie avec hyponatrémie.",sources:["PUBMED-ADDISON"],relatedIds:["2.7-RF-07"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-514",ue:"2.7",front:"Comment une insuffisance surrénalienne primaire est-elle confirmée ?",back:"Cortisol et aldostérone bas, rénine élevée, réponse atténuée à la stimulation par l'ACTH.",sources:["PUBMED-ADDISON"],relatedIds:["2.7-RF-07"],audience:"CLINICAL",difficultyBand:"ADVANCED"},{id:"FC-515",ue:"2.7",front:"Quelle durée de traitement substitutif l'insuffisance surrénalienne primaire exige-t-elle ?",back:"Toute la vie, sans interruption.",sources:["PUBMED-ADDISON"],relatedIds:["2.7-RF-07"],audience:"BOTH",difficultyBand:"FOUNDATION"},{id:"FC-516",ue:"2.7",front:"Quels trois éléments définissent l'insuffisance hépatique aiguë ?",back:"Début rapide sans maladie hépatique préalable, encéphalopathie et INR ≥ 1,5.",sources:["PUBMED-ALF"],relatedIds:["2.7-RF-08"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-517",ue:"2.7",front:"Quelle est la première cause d'insuffisance hépatique aiguë en Occident ?",back:"L'intoxication au paracétamol.",sources:["PUBMED-ALF"],relatedIds:["2.7-RF-08"],audience:"BOTH",difficultyBand:"FOUNDATION"},{id:"FC-518",ue:"2.7",front:"Quel délai définit la forme hyperaiguë d'insuffisance hépatique ?",back:"Moins de 7 jours entre l'ictère et l'encéphalopathie.",sources:["PUBMED-ALF"],relatedIds:["2.7-RF-08"],audience:"CLINICAL",difficultyBand:"ADVANCED"},{id:"FC-519",ue:"2.7",front:"Quel symptôme d'alarme d'une dyspepsie chez un patient de moins de 50 ans ?",back:"Dysphagie, saignement digestif ou anémie, ou vomissements persistants.",sources:["PUBMED-DYSPEPSIA-ALARM"],relatedIds:["2.7-DX-01"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-520",ue:"2.7",front:"Quelle valeur prédictive négative les symptômes d'alarme atteignent-ils pour le cancer digestif haut ?",back:"Environ 99,8 % : leur absence rend un cancer très improbable.",sources:["PUBMED-DYSPEPSIA-ALARM"],relatedIds:["2.7-DX-01"],audience:"CLINICAL",difficultyBand:"ADVANCED"},{id:"FC-521",ue:"2.5",front:"Jusqu'où irradie typiquement une douleur facettaire lombo-sacrée ?",back:"Fesses, aine ou cuisse, sans dépasser le genou.",sources:["PUBMED-FACET-LS","PUBMED-FACET-ARTH"],relatedIds:["2.5-RF-31"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-522",ue:"2.5",front:"Quelle part des lombalgies les facettes expliquent-elles ?",back:"Environ 15 à 45 %.",sources:["PUBMED-FACET-LS"],relatedIds:["2.5-RF-31"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-523",ue:"2.5",front:"Pourquoi l'imagerie seule ne suffit-elle pas à retenir un syndrome facettaire ?",back:"Ses images ne corrèlent pas de façon fiable avec les symptômes.",sources:["PUBMED-FACET-LS"],relatedIds:["2.5-RF-31"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-524",ue:"2.5",front:"Qu'appelle-t-on trigger point dans le syndrome myofascial ?",back:"Une zone hyperirritable située dans une bande tendue du muscle.",sources:["PUBMED-MYOFASCIAL"],relatedIds:["2.5-RF-32"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-525",ue:"2.5",front:"À partir de quelle durée parle-t-on de syndrome myofascial chronique ?",back:"Au moins 6 mois.",sources:["PUBMED-MYOFASCIAL"],relatedIds:["2.5-RF-32"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-526",ue:"2.5",front:"Quelles deux maladies systémiques sont des facteurs de risque du syndrome myofascial ?",back:"La carence en vitamine D et l'hypothyroïdie.",sources:["PUBMED-MYOFASCIAL"],relatedIds:["2.5-RF-32"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-527",ue:"2.5",front:"Quels tendons passent dans la gouttière rétro-malléolaire latérale ?",back:"Les tendons des fibulaires long et court.",sources:["PUBMED-PERONEAL"],relatedIds:["2.5-RF-33"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-528",ue:"2.5",front:"Quel ligament latéral de cheville est le seul extracapsulaire ?",back:"Le ligament calcanéo-fibulaire.",sources:["PUBMED-ANKLE-INSTAB"],relatedIds:["2.5-RF-33"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-529",ue:"2.5",front:"Quelles atteintes distingue-t-on pour les tendons fibulaires ?",back:"Tendinopathie, subluxation et rupture.",sources:["PUBMED-PERONEAL"],relatedIds:["2.5-RF-33"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-530",ue:"2.5",front:"Quelle classification structure les douleurs de l'aine chez le sportif ?",back:"L'accord de Doha : entités définies, douleur liée à la hanche, autres causes.",sources:["PUBMED-DOHA"],relatedIds:["2.5-RF-34"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-531",ue:"2.5",front:"Que désigne l'ostéite pubienne ?",back:"Une inflammation chronique non infectieuse de la symphyse pubienne.",sources:["PUBMED-OSTEITIS-PUBIS"],relatedIds:["2.5-RF-34"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-532",ue:"2.5",front:"Quelle structure de l'os de l'enfant la fracture de Salter-Harris traverse-t-elle ?",back:"Le cartilage de croissance (physe).",sources:["PUBMED-SALTER-HARRIS"],relatedIds:["2.5-RF-05"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-536",ue:"2.15",front:"Quels critères diagnostiques actuels du SDRC remplacent ceux de l'IASP de 1994 ?",back:"Les critères de Budapest (2010), plus spécifiques.",sources:["PUBMED-CRPS"],relatedIds:["2.15-DX-03"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-537",ue:"2.15",front:"Qu'est-ce qui distingue le SDRC de type 2 du type 1 ?",back:"Le type 2 suit une lésion nerveuse connue ; le type 1 survient sans lésion nerveuse.",sources:["PUBMED-CRPS"],relatedIds:["2.15-DX-03"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-538",ue:"2.15",front:"Quel est le signe cardinal de douleur dans le SDRC ?",back:"Une douleur disproportionnée à la lésion, persistant au-delà de la cicatrisation attendue.",sources:["PUBMED-CRPS"],relatedIds:["2.15-DX-03"],audience:"BOTH",difficultyBand:"FOUNDATION"},{id:"FC-539",ue:"2.15",front:"Quelle distribution a la douleur du SDRC ?",back:"Régionale : ni dermatomique ni myotomique.",sources:["PUBMED-CRPS"],relatedIds:["2.15-DX-03"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-533",ue:"5.2",front:"Quels trois sens le terme fascia recouvre-t-il selon les auteurs ?",back:"Un tissu conjonctif collagénique, une membrane distincte, un système conjonctif global.",sources:["PUBMED-FASCIA-FNC","PUBMED-FASCIA-NOMEN"],relatedIds:["5.2-KN-01"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-534",ue:"5.2",front:"Quel comité a proposé la définition du système fascial en 2017 ?",back:"Le Fascia Nomenclature Committee de la Fascia Research Society.",sources:["PUBMED-FASCIA-FNC"],relatedIds:["5.2-KN-01"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-535",ue:"5.2",front:"Que démontre un modèle de continuum fascial sur l'efficacité d'une technique ?",back:"Rien : c'est un cadre conceptuel, l'efficacité exige des données cliniques.",sources:["PUBMED-FASCIA-FNC","PUBMED-FASCIA-NOMEN"],relatedIds:["5.2-KN-01"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-540",ue:"1.2",front:"Où le conduit thoracique déverse-t-il la lymphe ?",back:"Dans la veine sous-clavière gauche.",sources:["OPENSTAX-AP-21-1"],relatedIds:["1.2-KN-06"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-541",ue:"1.2",front:"Quelle région du corps le conduit lymphatique droit draine-t-il ?",back:"La partie supérieure droite du corps.",sources:["OPENSTAX-AP-21-1"],relatedIds:["1.2-KN-06"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-542",ue:"1.2",front:"Quel nom portent les capillaires lymphatiques des villosités de l'intestin grêle ?",back:"Les lactéales (chylifères), qui transportent les lipides alimentaires sous forme de chyle.",sources:["OPENSTAX-AP-21-1"],relatedIds:["1.2-KN-06"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-543",ue:"1.2",front:"Le système nerveux central possède-t-il des capillaires lymphatiques ?",back:"Non : il en est dépourvu, comme les os, les dents et la cornée.",sources:["OPENSTAX-AP-21-1"],relatedIds:["1.2-KN-06"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-544",ue:"1.2",front:"Quels organes lymphoïdes sont dits primaires ?",back:"La moelle osseuse et le thymus.",sources:["OPENSTAX-AP-21-1"],relatedIds:["1.2-KN-07"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-545",ue:"1.2",front:"Dans quel organe les lymphocytes T mûrissent-ils ?",back:"Dans le thymus.",sources:["OPENSTAX-AP-21-1"],relatedIds:["1.2-KN-07"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-546",ue:"1.2",front:"Par quels vaisseaux la lymphe entre-t-elle dans un ganglion, et par lesquels sort-elle ?",back:"Elle entre par des vaisseaux afférents et sort par un vaisseau efférent.",sources:["OPENSTAX-AP-21-1"],relatedIds:["1.2-KN-07"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-547",ue:"1.2",front:"Quel organe élimine les microbes et les globules rouges vieillissants du sang ?",back:"La rate.",sources:["OPENSTAX-AP-21-1"],relatedIds:["1.2-KN-07"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-548",ue:"1.2",front:"Quelles cellules sécrètent les anticorps ?",back:"Les plasmocytes, issus de lymphocytes B activés.",sources:["OPENSTAX-AP-21-4"],relatedIds:["1.2-KN-08"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-549",ue:"1.2",front:"Quelle classe d'anticorps domine la réponse secondaire et traverse le placenta ?",back:"L'IgG.",sources:["OPENSTAX-AP-21-4"],relatedIds:["1.2-KN-08"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-550",ue:"1.2",front:"Quelle classe d'anticorps se fixe sur les mastocytes et déclenche l'allergie ?",back:"L'IgE.",sources:["OPENSTAX-AP-21-4"],relatedIds:["1.2-KN-08"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-551",ue:"1.2",front:"Pourquoi l'immunité passive ne laisse-t-elle aucune mémoire ?",back:"L'organisme reçoit des anticorps tout faits au lieu de produire ses propres lymphocytes mémoire.",sources:["OPENSTAX-AP-21-4"],relatedIds:["1.2-KN-08"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-552",ue:"1.2",front:"Quelle structure fixe le point de consigne de la température corporelle ?",back:"L'hypothalamus (centre thermorégulateur).",sources:["PUBMED-FEVER"],relatedIds:["1.2-KN-09"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-553",ue:"1.2",front:"Qu'est-ce qui distingue la fièvre de l'hyperthermie ?",back:"La fièvre élève le point de consigne hypothalamique ; l'hyperthermie dépasse la régulation hypothalamique.",sources:["PUBMED-FEVER"],relatedIds:["1.2-KN-09"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-554",ue:"1.2",front:"Une fièvre est-elle toujours d'origine infectieuse ?",back:"Non : inflammation, cancer ou processus auto-immun peuvent aussi la provoquer.",sources:["PUBMED-FEVER"],relatedIds:["1.2-KN-09"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-555",ue:"1.2",front:"Chez un patient neutropénique, que faut-il penser d'une fièvre sans signe local ?",back:"C'est une urgence : la neutropénie masque les signes locaux d'infection (voir 2.10-RF-02).",sources:["PUBMED-FEVER"],relatedIds:["1.2-KN-09"],audience:"CLINICAL",difficultyBand:"CLINICAL"},{id:"FC-556",ue:"1.2",front:"Quel organe synthétise la protéine C-réactive ?",back:"Le foie.",sources:["PUBMED-CRP"],relatedIds:["1.2-KN-10"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-557",ue:"1.2",front:"Quelle cytokine induit surtout la synthèse de la CRP ?",back:"L'interleukine 6.",sources:["PUBMED-CRP"],relatedIds:["1.2-KN-10"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-558",ue:"1.2",front:"Pourquoi une CRP élevée ne suffit-elle pas à poser un diagnostic ?",back:"Elle est peu spécifique : infection, traumatisme et inflammation chronique l'élèvent.",sources:["PUBMED-CRP"],relatedIds:["1.2-KN-10"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-559",ue:"1.2",front:"En quoi la CRP diffère-t-elle de la vitesse de sédimentation ?",back:"Elle monte et redescend plus vite avec l'inflammation.",sources:["PUBMED-CRP"],relatedIds:["1.2-KN-10"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-560",ue:"1.2",front:"Quel mécanisme définit une maladie auto-immune ?",back:"La rupture de la tolérance au soi.",sources:["OPENSTAX-AP-21-6"],relatedIds:["1.2-KN-11"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-561",ue:"1.2",front:"Citez trois maladies auto-immunes données comme exemples.",back:"Diabète de type 1, maladie de Basedow, myasthénie.",sources:["OPENSTAX-AP-21-6"],relatedIds:["1.2-KN-11"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-562",ue:"1.2",front:"Qu'est-ce qui distingue l'auto-immunité de l'allergie ?",back:"L'auto-immunité cible le soi ; l'allergie est une réaction excessive à un antigène étranger.",sources:["OPENSTAX-AP-21-6"],relatedIds:["1.2-KN-11"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-563",ue:"1.2",front:"Quelle cellule le VIH cible-t-il ?",back:"Les lymphocytes T auxiliaires CD4+.",sources:["OPENSTAX-AP-21-6"],relatedIds:["1.2-KN-12"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-564",ue:"1.2",front:"Quelles réponses le DICS (SCID) touche-t-il ?",back:"Les réponses des lymphocytes B et des lymphocytes T.",sources:["OPENSTAX-AP-21-6"],relatedIds:["1.2-KN-12"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-565",ue:"1.2",front:"Pourquoi un déficit immunitaire change-t-il le seuil d'urgence d'une fièvre ?",back:"Les signes locaux d'infection peuvent être atténués alors que l'infection peut être grave.",sources:["OPENSTAX-AP-21-6"],relatedIds:["1.2-KN-12"],audience:"CLINICAL",difficultyBand:"CLINICAL"},{id:"FC-566",ue:"1.2",front:"Quel type d'hypersensibilité est immédiat et médié par les IgE ?",back:"Le type I.",sources:["OPENSTAX-AP-21-6"],relatedIds:["1.2-KN-13"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-567",ue:"1.2",front:"Quel type d'hypersensibilité est dû aux complexes immuns ?",back:"Le type III (exemples : lupus, polyarthrite rhumatoïde).",sources:["OPENSTAX-AP-21-6"],relatedIds:["1.2-KN-13"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-568",ue:"1.2",front:"Quel est le délai d'apparition de l'hypersensibilité de type IV ?",back:"24 à 72 h après la réexposition.",sources:["OPENSTAX-AP-21-6"],relatedIds:["1.2-KN-13"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-569",ue:"1.2",front:"Quelles cellules médient l'hypersensibilité de type IV ?",back:"Les lymphocytes T (Th1 recrutant des macrophages).",sources:["OPENSTAX-AP-21-6"],relatedIds:["1.2-KN-13"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-570",ue:"5.11",front:"Quelle instabilité cervicale haute, notamment dans la polyarthrite, contre-indique une HVLA cervicale ?",back:"L'instabilité atlanto-axoïdienne.",sources:["NCBI-HVLA-CONTRA"],relatedIds:["5.11-MG-01"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-571",ue:"5.11",front:"Une infection active de la zone à traiter contre-indique-t-elle une HVLA ?",back:"Oui : contre-indication absolue sur la zone concernée.",sources:["NCBI-HVLA-CONTRA"],relatedIds:["5.11-MG-01"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-572",ue:"5.11",front:"Que signalent les drapeaux rouges, selon la HAS ?",back:"Un risque de pathologie grave justifiant un avis médical.",sources:["HAS-LOMBALGIE-2019"],relatedIds:["5.11-KN-01"],audience:"BOTH",difficultyBand:"FOUNDATION"},{id:"FC-573",ue:"5.11",front:"Que signalent les drapeaux jaunes ?",back:"Un risque accru de chronicité ou d'incapacité prolongée (facteurs psychosociaux).",sources:["HAS-LOMBALGIE-2019"],relatedIds:["5.11-KN-01"],audience:"BOTH",difficultyBand:"FOUNDATION"},{id:"FC-574",ue:"5.11",front:"Que recherche-t-on avec les drapeaux bleus et noirs ?",back:"Les obstacles au retour au travail ou à une incapacité prolongée au travail.",sources:["HAS-LOMBALGIE-2019"],relatedIds:["5.11-KN-01"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-575",ue:"5.11",front:"Que recommande la HAS en l'absence de drapeau rouge lors d'une poussée aiguë de lombalgie ?",back:"Ne pas faire d'imagerie rachidienne et expliquer pourquoi au patient.",sources:["HAS-LOMBALGIE-2019"],relatedIds:["5.11-KN-01"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-576",ue:"5.11",front:"À quoi sert le questionnaire STarT Back ?",back:"À stratifier la prise en charge selon le risque de chronicité.",sources:["HAS-LOMBALGIE-2019"],relatedIds:["5.11-KN-01"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-577",ue:"5.11",front:"Un signe d'alerte isolé constitue-t-il forcément un drapeau rouge ?",back:"Non : le drapeau rouge est une situation clinique justifiant un avis médical (définition enseignée).",sources:["HAS-LOMBALGIE-2019"],relatedIds:["5.11-KN-01"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-578",ue:"5.11",front:"Quelle est la durée d'une crise de migraine ?",back:"De 4 à 72 heures.",sources:["PUBMED-MIGRAINE-ACP","PUBMED-MIGRAINE-PROPH"],relatedIds:["5.11-DX-01"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-579",ue:"5.11",front:"Un déclencheur de migraine est-il une cause de la céphalée ?",back:"Non : le déclencheur facilite la crise sans en être la cause.",sources:["PUBMED-MIGRAINE-ACP","PUBMED-MIGRAINE-PROPH"],relatedIds:["5.11-DX-01"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-580",ue:"5.11",front:"Chez un migraineux connu, quelle céphalée impose de chercher une cause secondaire ?",back:"Une céphalée différente de ses crises habituelles, brutale ou avec signes associés.",sources:["PUBMED-MIGRAINE-ACP","PUBMED-MIGRAINE-PROPH","PUBMED-SNNOOP10"],relatedIds:["5.11-DX-01"],audience:"CLINICAL",difficultyBand:"CLINICAL"},{id:"FC-581",ue:"2.4",front:"Que regroupe la liste SNNOOP10 ?",back:"Les signes d'alerte de céphalée secondaire.",sources:["PUBMED-SNNOOP10"],relatedIds:["2.4-RF-01"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-582",ue:"2.4",front:"Le post-partum est-il un signe d'alerte SNNOOP10 de céphalée secondaire ?",back:"Oui : grossesse et post-partum figurent dans la liste.",sources:["PUBMED-SNNOOP10"],relatedIds:["2.4-RF-01"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-583",ue:"5.11",front:"Combien de symptômes sur 9 faut-il pour un trouble dépressif caractérisé (DSM-5) ?",back:"Au moins 5, dont l'humeur dépressive ou l'anhédonie.",sources:["PUBMED-MDD","PUBMED-MDD-NURS"],relatedIds:["5.11-DX-02"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-584",ue:"5.11",front:"Pendant combien de temps les symptômes doivent-ils durer pour un trouble dépressif caractérisé ?",back:"Au moins 2 semaines.",sources:["PUBMED-MDD","PUBMED-MDD-NURS"],relatedIds:["5.11-DX-02"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-585",ue:"5.11",front:"Quel symptôme dépressif prime sur toute autre démarche ?",back:"Les idées suicidaires (voir 2.11-RF-01).",sources:["PUBMED-MDD","PUBMED-MDD-NURS"],relatedIds:["5.11-DX-02"],audience:"CLINICAL",difficultyBand:"CLINICAL"},{id:"FC-586",ue:"5.11",front:"Quel mécanisme produit une fracture de fatigue ?",back:"Une charge répétée qui dépasse la capacité de réparation d'un os sain.",sources:["PUBMED-STRESSFX-2025","PUBMED-STRESSFX-MECH","PUBMED-STRESSFX-UL"],relatedIds:["5.11-DX-03"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-587",ue:"5.11",front:"Une radiographie initiale normale exclut-elle une fracture de fatigue ?",back:"Non : elle est souvent normale ; l'IRM est la référence.",sources:["PUBMED-STRESSFX-2025","PUBMED-STRESSFX-MECH","PUBMED-STRESSFX-UL"],relatedIds:["5.11-DX-03"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-588",ue:"5.11",front:"Quels deux sites de fracture de fatigue exposent à une non-union ?",back:"Le naviculaire et le 5e métatarsien (zones 2 et 3).",sources:["PUBMED-NAVICULAR-SF","PUBMED-5MT-SF"],relatedIds:["5.11-DX-03"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-589",ue:"2.6",front:"Combien de critères sur 4 faut-il pour diagnostiquer une péricardite aiguë ?",back:"Au moins deux.",sources:["ESC-PERICARDIAL-2015","PUBMED-PERICARDITIS"],relatedIds:["2.6-DX-03"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-590",ue:"2.6",front:"Quelle position soulage la douleur de péricardite ?",back:"La position assise penchée en avant.",sources:["ESC-PERICARDIAL-2015","PUBMED-PERICARDITIS"],relatedIds:["2.6-DX-03"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-591",ue:"2.6",front:"Quelles modifications ECG évoquent une péricardite aiguë ?",back:"Un sus-décalage diffus du ST ou un sous-décalage de PR.",sources:["ESC-PERICARDIAL-2015","PUBMED-PERICARDITIS"],relatedIds:["2.6-DX-03"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-592",ue:"2.6",front:"L'absence de frottement péricardique écarte-t-elle une péricardite ?",back:"Non : le frottement est inconstant et fugace.",sources:["ESC-PERICARDIAL-2015","PUBMED-PERICARDITIS"],relatedIds:["2.6-DX-03"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-593",ue:"2.6",front:"Quels signes évoquent une tamponnade ?",back:"Jugulaires turgescentes, pouls paradoxal, bruits du cœur assourdis : urgence.",sources:["ESC-PERICARDIAL-2015","PUBMED-PERICARDITIS"],relatedIds:["2.6-DX-03"],audience:"CLINICAL",difficultyBand:"CLINICAL"},{id:"FC-594",ue:"2.6",front:"Quel seuil de consultation définit l'hypertension selon l'ESC/ESH 2018 ?",back:"≥ 140 et/ou ≥ 90 mmHg.",sources:["ESC-ESH-HTN-2018"],relatedIds:["2.6-KN-04"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-595",ue:"2.6",front:"Combien de temps le patient doit-il être au repos avant la mesure de PA ?",back:"Cinq minutes, assis et au calme.",sources:["ESC-ESH-HTN-2018"],relatedIds:["2.6-KN-04"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-596",ue:"2.6",front:"Quel seuil moyen de MAPA sur 24 h définit l'hypertension ?",back:"≥ 130/80 mmHg.",sources:["ESC-ESH-HTN-2018"],relatedIds:["2.6-KN-04"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-597",ue:"2.6",front:"Pourquoi une PA isolée mesurée après un effort ne suffit-elle pas à poser le diagnostic ?",back:"Elle est prise hors protocole : il faut des mesures répétées au repos puis une confirmation hors cabinet.",sources:["ESC-ESH-HTN-2018"],relatedIds:["2.6-KN-04"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-598",ue:"2.6",front:"Comment définit-on une syncope ?",back:"Perte de connaissance transitoire par hypoperfusion cérébrale, avec récupération spontanée complète.",sources:["ESC-SYNCOPE-2018","PUBMED-SYNCOPE"],relatedIds:["2.6-RF-07"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-599",ue:"2.6",front:"Citez les trois grandes catégories de syncope.",back:"Réflexe, hypotension orthostatique et cardiaque.",sources:["ESC-SYNCOPE-2018","PUBMED-SYNCOPE"],relatedIds:["2.6-RF-07"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-600",ue:"2.6",front:"Une syncope débutant à l'effort évoque-t-elle une origine réflexe ou cardiaque ?",back:"Cardiaque : c'est un signe à risque.",sources:["ESC-SYNCOPE-2018","PUBMED-SYNCOPE"],relatedIds:["2.6-RF-07"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-601",ue:"2.6",front:"Quelle est la cause la plus fréquente d'hypotension orthostatique ?",back:"La cause médicamenteuse.",sources:["ESC-SYNCOPE-2018","PUBMED-SYNCOPE"],relatedIds:["2.6-RF-07"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-602",ue:"2.6",front:"Quelle est la cause principale du rétrécissement mitral dans le monde ?",back:"La cardiopathie rhumatismale.",sources:["ESC-VHD-2021","PUBMED-MITRAL-STENOSIS"],relatedIds:["2.6-DX-04"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-603",ue:"2.6",front:"Quelles complications menacent un patient porteur d'un rétrécissement mitral ?",back:"La fibrillation atriale et les embolies systémiques.",sources:["ESC-VHD-2021","PUBMED-MITRAL-STENOSIS"],relatedIds:["2.6-DX-04"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-604",ue:"2.6",front:"Quel souffle accompagne l'insuffisance aortique ?",back:"Un souffle diastolique, avec une pression pulsée élargie.",sources:["ESC-VHD-2021","PUBMED-MITRAL-STENOSIS"],relatedIds:["2.6-DX-04"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-605",ue:"2.6",front:"Quelles causes expliquent une insuffisance aortique aiguë sévère ?",back:"L'endocardite infectieuse ou la dissection aortique.",sources:["ESC-VHD-2021","PUBMED-MITRAL-STENOSIS"],relatedIds:["2.6-DX-04"],audience:"CLINICAL",difficultyBand:"ADVANCED"},{id:"FC-606",ue:"2.4",front:"Quel mouvement de la tête, combiné à la compression axiale, constitue la manœuvre de Spurling ?",back:"L'extension, la rotation et l'inclinaison homolatérale du cou.",sources:["NCBI-CERVICAL-RADIC"],relatedIds:["2.4-EX-01"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-607",ue:"2.4",front:"Quelles racines un Lasègue positif évoque-t-il ?",back:"Une atteinte de L4 à S1.",sources:["NCBI-LUMBOSACRAL-RADIC"],relatedIds:["2.4-EX-01"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-608",ue:"2.4",front:"Quelle est la sensibilité du Spurling dans l'étude de 255 patients ?",back:"30 % (spécificité 93 %).",sources:["PUBMED-SPURLING-TONG"],relatedIds:["2.4-EX-01"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-609",ue:"2.4",front:"Un Spurling négatif exclut-il une radiculopathie cervicale ?",back:"Non : le test est peu sensible.",sources:["PUBMED-SPURLING-TONG"],relatedIds:["2.4-EX-01"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-610",ue:"2.5",front:"Entre deux règles de décision cervicales validées, laquelle est la plus sensible ?",back:"La règle canadienne : environ 99 % de sensibilité contre 91 %.",sources:["PUBMED-CCR-VS-NEXUS"],relatedIds:["2.5-RF-35"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-611",ue:"2.5",front:"Quels facteurs de haut risque imposent la radiographie dans la Canadian C-spine rule ?",back:"Âge ≥ 65 ans, mécanisme dangereux, paresthésies des extrémités.",sources:["PUBMED-CCR-2001"],relatedIds:["2.5-RF-35"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-612",ue:"2.5",front:"Quels patients ont servi à dériver la Canadian C-spine rule ?",back:"Des adultes alertes et stables vus aux urgences après un traumatisme fermé.",sources:["PUBMED-CCR-2001"],relatedIds:["2.5-RF-35"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-613",ue:"2.5",front:"Combien de critères NEXUS de faible risque existe-t-il ?",back:"Cinq, tous nécessaires pour conserver la sensibilité.",sources:["PUBMED-NEXUS-2000","PUBMED-NEXUS-CRITERIA"],relatedIds:["2.5-RF-35"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-614",ue:"2.5",front:"Comment calcule-t-on le rapport de vraisemblance positif ?",back:"Sensibilité / (1 − spécificité).",sources:["BMJ-LR-2004"],relatedIds:["2.5-RF-36"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-615",ue:"2.5",front:"Comment calcule-t-on le rapport de vraisemblance négatif ?",back:"(1 − sensibilité) / spécificité.",sources:["BMJ-LR-2004"],relatedIds:["2.5-RF-36"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-616",ue:"2.5",front:"À partir de quelles valeurs un rapport de vraisemblance donne-t-il une preuve forte ?",back:"Au-delà de 10 ou en deçà de 0,1.",sources:["BMJ-LR-2004"],relatedIds:["2.5-RF-36"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-617",ue:"2.5",front:"Pourquoi les rapports de vraisemblance sont-ils préférés aux valeurs prédictives ?",back:"Ils ne dépendent pas de la prévalence et s'adaptent à la probabilité pré-test.",sources:["BMJ-LR-2004"],relatedIds:["2.5-RF-36"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-618",ue:"2.5",front:"Quelle est la conclusion de la revue systématique sur le test de Sharp-Purser ?",back:"Il peut être inadapté : validité incohérente, faible fiabilité, risque potentiel.",sources:["PUBMED-SPT-SR"],relatedIds:["2.5-RF-37"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-619",ue:"2.5",front:"Un Sharp-Purser négatif écarte-t-il une instabilité atlanto-axoïdienne ?",back:"Non : sa validité est incohérente.",sources:["PUBMED-SPT-SR"],relatedIds:["2.5-RF-37"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-620",ue:"1.10",front:"Quel réflexe stabilise le regard pendant un mouvement de la tête ?",back:"Le réflexe vestibulo-oculaire.",sources:["NCBI-VESTIBULAR-PHYSIO"],relatedIds:["1.10-KN-06"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-621",ue:"2.9",front:"Sur quels deux éléments GRACE-3 fonde-t-il l'approche d'un étourdissement aigu ?",back:"La temporalité et les déclencheurs des symptômes.",sources:["GRACE3-DIZZ"],relatedIds:["2.9-KN-02"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-622",ue:"2.9",front:"Quelle différence sépare le vertige de l'étourdissement ?",back:"Le vertige est une sensation de mouvement ; l'étourdissement est une orientation perturbée sans fausse sensation de mouvement.",sources:["PUBMED-BARANY-SYMPTOMS-2009"],relatedIds:["2.9-KN-02"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-623",ue:"2.9",front:"Selon GRACE-3, quels sont les trois syndromes vestibulaires cliniques devant un étourdissement ?",back:"Aigu continu, épisodique spontané et épisodique déclenché (positionnel).",sources:["GRACE3-DIZZ"],relatedIds:["2.9-KN-02"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-624",ue:"2.9",front:"Une perte de connaissance est-elle d'origine vestibulaire ?",back:"Non : le cours l'enseigne comme jamais vestibulaire ; chercher une cause cardiaque ou générale.",sources:["ESC-SYNCOPE-2018"],relatedIds:["2.9-KN-02"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-625",ue:"2.9",front:"Quel signe pose le diagnostic de VPPB du canal postérieur au Dix-Hallpike ?",back:"Un vertige avec nystagmus torsionnel battant vers le haut.",sources:["PUBMED-BPPV-AAO-2017"],relatedIds:["2.9-DX-02"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-626",ue:"2.9",front:"Quel test rechercher si le Dix-Hallpike montre un nystagmus horizontal ou aucun nystagmus ?",back:"Le supine roll test, pour le canal latéral.",sources:["PUBMED-BPPV-AAO-2017"],relatedIds:["2.9-DX-02"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-627",ue:"2.9",front:"Quel est le traitement recommandé du VPPB du canal postérieur ?",back:"Une manœuvre de repositionnement canalaire (Epley).",sources:["PUBMED-BPPV-AAO-2017"],relatedIds:["2.9-DX-02"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-628",ue:"2.9",front:"Faut-il imposer des restrictions posturales après un repositionnement ?",back:"Non : la guideline recommande contre toute restriction posturale.",sources:["PUBMED-BPPV-AAO-2017"],relatedIds:["2.9-DX-02"],audience:"CLINICAL",difficultyBand:"ADVANCED"},{id:"FC-629",ue:"2.9",front:"Un suppresseur vestibulaire est-il recommandé en routine dans le VPPB ?",back:"Non : la guideline recommande contre un usage de routine.",sources:["PUBMED-BPPV-AAO-2017"],relatedIds:["2.9-DX-02"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-630",ue:"2.9",front:"Quelle durée minimale de vertige soutenu définit l'AUVP complète ?",back:"Au moins 24 heures.",sources:["PUBMED-AUVP-BARANY-2022"],relatedIds:["2.9-DX-03"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-631",ue:"2.9",front:"Quel résultat du head impulse test est attendu dans une névrite vestibulaire ?",back:"Une saccade de rattrapage du côté lésé.",sources:["PUBMED-AUVP-BARANY-2022"],relatedIds:["2.9-DX-03"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-632",ue:"2.9",front:"Quel signe associé exclut le diagnostic d'AUVP ?",back:"Un signe auditif ou central aigu.",sources:["PUBMED-AUVP-BARANY-2022"],relatedIds:["2.9-DX-03"],audience:"CLINICAL",difficultyBand:"ADVANCED"},{id:"FC-633",ue:"2.9",front:"Quels diagnostics différentiels d'une aréflexie vestibulaire aiguë le cours cite-t-il ?",back:"AVC du tronc cérébral, sclérose en plaques, schwannome du VIIIe nerf.",sources:["GRACE3-DIZZ"],relatedIds:["2.9-DX-03"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-634",ue:"2.9",front:"Dans l'examen du vertige aigu, que signifie l'acronyme HINTS ?",back:"Head Impulse, Nystagmus, Test of Skew.",sources:["PUBMED-HINTS-KATTAH-2009","PUBMED-HINTS-ED-SR-2020"],relatedIds:["2.9-EX-02"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-635",ue:"2.9",front:"Quel résultat du head impulse test oriente vers une cause centrale dans un syndrome vestibulaire aigu ?",back:"Un head impulse normal, sans saccade de rattrapage.",sources:["PUBMED-HINTS-KATTAH-2009","PUBMED-HINTS-ED-SR-2020"],relatedIds:["2.9-EX-02"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-636",ue:"2.9",front:"Quel nystagmus oriente vers une cause centrale dans un syndrome vestibulaire aigu ?",back:"Un nystagmus changeant de direction selon le regard.",sources:["PUBMED-HINTS-KATTAH-2009","PUBMED-HINTS-ED-SR-2020"],relatedIds:["2.9-EX-02"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-637",ue:"2.9",front:"À quels patients HINTS s'applique-t-il ?",back:"Syndrome vestibulaire aigu avec nystagmus, examiné par un clinicien formé.",sources:["PUBMED-HINTS-KATTAH-2009","PUBMED-HINTS-ED-SR-2020","GRACE3-DIZZ"],relatedIds:["2.9-EX-02"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-638",ue:"2.9",front:"Un HINTS réalisé par un praticien non formé peut-il exclure un AVC ?",back:"Non : sa précision n'est pas démontrée hors formation.",sources:["PUBMED-HINTS-ED-SR-2020"],relatedIds:["2.9-EX-02"],audience:"CLINICAL",difficultyBand:"ADVANCED"},{id:"FC-639",ue:"2.9",front:"Quelle durée de crise définit la maladie de Ménière ?",back:"De 20 minutes à 12 heures.",sources:["PUBMED-MENIERE-BARANY-2015"],relatedIds:["2.9-DX-04"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-640",ue:"2.9",front:"Quelle perte auditive caractérise la maladie de Ménière définie ?",back:"Neurosensorielle, des fréquences graves à moyennes, fluctuante.",sources:["PUBMED-MENIERE-BARANY-2015"],relatedIds:["2.9-DX-04"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-641",ue:"2.9",front:"Quel examen documente la perte auditive d'un Ménière ?",back:"L'audiométrie.",sources:["PUBMED-MENIERE-BARANY-2015"],relatedIds:["2.9-DX-04"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-642",ue:"2.9",front:"Quelle durée de symptômes définit la maladie de Ménière probable ?",back:"De 20 minutes à 24 heures.",sources:["PUBMED-MENIERE-BARANY-2015"],relatedIds:["2.9-DX-04"],audience:"STUDENT",difficultyBand:"ADVANCED"},{id:"FC-643",ue:"2.9",front:"Quelle durée d'épisode définit la migraine vestibulaire ?",back:"De 5 minutes à 72 heures.",sources:["PUBMED-VM-BARANY-2012","PUBMED-VM-BARANY-2022"],relatedIds:["2.9-DX-05"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-644",ue:"2.9",front:"Combien d'épisodes faut-il pour une migraine vestibulaire définie ?",back:"Au moins cinq.",sources:["PUBMED-VM-BARANY-2012","PUBMED-VM-BARANY-2022"],relatedIds:["2.9-DX-05"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-645",ue:"2.9",front:"Quel antécédent est requis pour une migraine vestibulaire ?",back:"Une migraine actuelle ou passée.",sources:["PUBMED-VM-BARANY-2012","PUBMED-VM-BARANY-2022"],relatedIds:["2.9-DX-05"],audience:"BOTH",difficultyBand:"FOUNDATION"},{id:"FC-646",ue:"2.9",front:"La migraine vestibulaire est-elle un diagnostic d'exclusion ?",back:"Oui : il faut écarter une autre explication.",sources:["PUBMED-VM-BARANY-2012","PUBMED-VM-BARANY-2022"],relatedIds:["2.9-DX-05"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-647",ue:"2.9",front:"Quel est le premier geste devant une baisse brusque de l'audition ?",back:"Distinguer perte neurosensorielle et perte de transmission.",sources:["PUBMED-SSNHL-AAO-2019"],relatedIds:["2.9-RF-05"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-648",ue:"2.9",front:"Dans quel délai faire l'audiométrie d'une baisse brusque de l'audition ?",back:"Dès que possible, au plus tard dans les 14 jours.",sources:["PUBMED-SSNHL-AAO-2019"],relatedIds:["2.9-RF-05"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-649",ue:"2.9",front:"Quels examens recherchent une atteinte rétro-cochléaire ?",back:"L'IRM ou les potentiels évoqués auditifs.",sources:["PUBMED-SSNHL-AAO-2019"],relatedIds:["2.9-RF-05"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-650",ue:"2.9",front:"Un scanner cérébral de routine est-il recommandé dans la baisse brusque de l'audition ?",back:"Non.",sources:["PUBMED-SSNHL-AAO-2019"],relatedIds:["2.9-RF-05"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-651",ue:"2.9",front:"Où se latéralise le Weber dans une surdité neurosensorielle unilatérale ?",back:"Vers l'oreille saine.",sources:["STATPEARLS-WEBER"],relatedIds:["2.9-EX-03"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-652",ue:"2.9",front:"Où se latéralise le Weber dans une perte de transmission unilatérale ?",back:"Vers l'oreille atteinte.",sources:["STATPEARLS-WEBER"],relatedIds:["2.9-EX-03"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-653",ue:"2.9",front:"Que signifie un Rinne négatif ?",back:"Conduction osseuse meilleure qu'aérienne : composante de transmission.",sources:["STATPEARLS-RINNE"],relatedIds:["2.9-EX-03"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-654",ue:"2.9",front:"Les tests au diapason remplacent-ils l'audiométrie ?",back:"Non : leur précision varie selon la technique et les seuils.",sources:["PUBMED-TUNING-FORK-SR"],relatedIds:["2.9-EX-03"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-655",ue:"2.9",front:"Quel acouphène justifie un examen audiologique prompt ?",back:"Unilatéral, persistant (6 mois ou plus) ou associé à des difficultés auditives.",sources:["PUBMED-TINNITUS-AAO-2014"],relatedIds:["2.9-DX-06"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-656",ue:"2.9",front:"Quelle thérapie est recommandée pour un acouphène persistant gênant ?",back:"La thérapie cognitivo-comportementale.",sources:["PUBMED-TINNITUS-AAO-2014"],relatedIds:["2.9-DX-06"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-657",ue:"2.9",front:"Dans quels cas la guideline déconseille-t-elle l'imagerie d'un acouphène ?",back:"Acouphène non pulsatile, bilatéral ou non localisé, sans signe neurologique ni perte auditive asymétrique.",sources:["PUBMED-TINNITUS-AAO-2014"],relatedIds:["2.9-DX-06"],audience:"CLINICAL",difficultyBand:"ADVANCED"},{id:"FC-658",ue:"2.5",front:"Quelle attitude de la tête caractérise la fixation rotatoire atloïdo-axoïdienne ?",back:"Un torticolis douloureux fixé, dit « cock-robin ».",sources:["PUBMED-AARF-REVIEW","PUBMED-AARF-CHALLENGES"],relatedIds:["2.5-RF-38"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-659",ue:"2.5",front:"Quel examen d'imagerie est la référence pour une AARF ?",back:"Le scanner.",sources:["PUBMED-AARF-REVIEW","PUBMED-AARF-CHALLENGES"],relatedIds:["2.5-RF-38"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-660",ue:"2.5",front:"Quel contexte infectieux précède souvent une AARF de l'enfant ?",back:"Une infection des voies respiratoires supérieures.",sources:["PUBMED-AARF-REVIEW","PUBMED-AARF-CHALLENGES"],relatedIds:["2.5-RF-38"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-661",ue:"1.9",front:"Dans quelle structure minérale le phosphate est-il stocké dans l'os ?",back:"Dans l'hydroxyapatite.",sources:["PUBMED-PHOSPHATE-HOMEOSTASIS"],relatedIds:["1.9-KN-06"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-662",ue:"2.5",front:"Que faut-il réunir pour diagnostiquer un syndrome de conflit fémoro-acétabulaire ?",back:"Symptômes, signes cliniques et anomalies d'imagerie (accord de Warwick).",sources:["PUBMED-WARWICK-FAI"],relatedIds:["2.5-RF-34"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-663",ue:"2.4",front:"Quel examen vasculaire GRACE-3 recommande-t-il si un AIT est suspecté devant des vertiges épisodiques ?",back:"Un angio-scanner ou une angio-IRM.",sources:["GRACE3-DIZZ"],relatedIds:["2.4-RF-02"],audience:"CLINICAL",difficultyBand:"ADVANCED"},{id:"FC-664",ue:"1.2",front:"Quelles propriétés définissent un antigène complet ?",back:"L'immunogénicité et la réactivité.",sources:["OPENSTAX-AP-21-2"],relatedIds:["1.2-KN-04"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-665",ue:"1.2",front:"Qu'est-ce que l'immunosénescence ?",back:"La détérioration progressive de l'immunité avec l'âge.",sources:["PUBMED-IMMUNOSENESCENCE"],relatedIds:["1.2-KN-12"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-666",ue:"2.15",front:"Que dit l'IASP (2020) sur la relation entre douleur et nociception ?",back:"Ce sont deux phénomènes différents : la douleur ne se déduit pas de la nociception.",sources:["PUBMED-IASP-DEF-2020"],relatedIds:["2.15-KN-02"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-667",ue:"2.15",front:"Quelle est la définition IASP révisée de la douleur ?",back:"Expérience sensorielle et émotionnelle désagréable, associée à ou ressemblant à celle d'une lésion tissulaire réelle ou potentielle.",sources:["PUBMED-IASP-DEF-2020"],relatedIds:["2.15-KN-02"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-668",ue:"2.15",front:"Que détectent les nocicepteurs ?",back:"Des stimuli intenses ou liés à une lésion : thermiques, mécaniques ou chimiques.",sources:["PUBMED-NOCICEPTORS-2010"],relatedIds:["2.15-KN-02"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-669",ue:"2.15",front:"Une imagerie normale exclut-elle une douleur réelle ?",back:"Non : douleur, nociception et lésion ne sont pas directement corrélées.",sources:["PUBMED-IASP-DEF-2020","PUBMED-NOCICEPTORS-2010","PUBMED-CENTRAL-MODULATION"],relatedIds:["2.15-KN-02"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-670",ue:"2.15",front:"Que désigne la sensibilisation périphérique ?",back:"Un seuil abaissé et une réactivité accrue des nocicepteurs.",sources:["IASP-TERM"],relatedIds:["2.15-KN-03"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-671",ue:"2.15",front:"Que désigne la sensibilisation centrale ?",back:"Une réactivité accrue des neurones nociceptifs du système nerveux central à leurs afférences normales ou infraliminaires.",sources:["IASP-TERM","PUBMED-CS-WOOLF-2009"],relatedIds:["2.15-KN-03"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-672",ue:"2.15",front:"La sensibilisation centrale est-elle un diagnostic ?",back:"Non : c'est un mécanisme neurophysiologique, à ne pas confondre avec la douleur nociplastique.",sources:["IASP-TERM","PUBMED-CS-WOOLF-2009"],relatedIds:["2.15-KN-03"],audience:"CLINICAL",difficultyBand:"ADVANCED"},{id:"FC-673",ue:"2.15",front:"Qui a proposé le gate control et en quelle année ?",back:"Melzack et Wall, en 1965.",sources:["PUBMED-GATE-1965"],relatedIds:["2.15-KN-04"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-674",ue:"2.15",front:"Le gate control démontre-t-il l'efficacité d'un geste manuel donné ?",back:"Non : c'est un modèle explicatif simplifié.",sources:["PUBMED-GATE-1965","PUBMED-CENTRAL-MODULATION"],relatedIds:["2.15-KN-04"],audience:"CLINICAL",difficultyBand:"ADVANCED"},{id:"FC-675",ue:"2.15",front:"Quels facteurs contextuels modulent l'expérience de la douleur ?",back:"L'état émotionnel, l'anxiété, l'attention et les expériences passées.",sources:["PUBMED-CENTRAL-MODULATION"],relatedIds:["2.15-KN-04"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-676",ue:"2.15",front:"Quelle approche la douleur chronique appelle-t-elle selon le Lancet 2021 ?",back:"Une approche personnalisée, multimodale et interdisciplinaire.",sources:["PUBMED-CHRONIC-PAIN-LANCET"],relatedIds:["2.15-MG-02"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-677",ue:"2.15",front:"Que faire d'un patient douloureux chronique évitant toute activité par peur ?",back:"L'éduquer et encourager une reprise graduée d'activité.",sources:["PUBMED-CHRONIC-PAIN-LANCET"],relatedIds:["2.15-MG-02"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-678",ue:"2.15",front:"Quelle proportion de patients sous traitement anticancéreux a une douleur selon l'OMS ?",back:"55 %.",sources:["WHO-CANCER-PAIN-2018"],relatedIds:["2.15-KN-05"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-679",ue:"2.15",front:"Que faire devant une douleur nouvelle chez un patient suivi pour un cancer ?",back:"La signaler au médecin ou à l'équipe oncologique.",sources:["WHO-CANCER-PAIN-2018","NICE-NG12"],relatedIds:["2.15-KN-05"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-680",ue:"2.5",front:"Quels mécanismes sont proposés pour expliquer la douleur référée ?",back:"Des hypothèses : sensibilisation centrale de neurones convergents de la corne dorsale, et réflexes périphériques de fibres afférentes bifurquées.",sources:["PUBMED-REFERRED-PAIN-2023"],relatedIds:["2.5-RF-20"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-681",ue:"1.6",front:"Où le nerf radial est-il exposé lors d'une fracture de la diaphyse humérale ?",back:"À la gouttière radiale (spirale) de l'humérus.",sources:["PUBMED-RADIAL-HSF-REVIEW"],relatedIds:["1.6-KN-04"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-682",ue:"1.6",front:"Quelle fréquence de paralysie radiale primaire dans les fractures de la diaphyse humérale ?",back:"Environ 10 %.",sources:["PUBMED-HSF-EDU-2026"],relatedIds:["1.6-KN-04"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-683",ue:"1.6",front:"Quel signe distingue une compression à l'arcade de Frohse d'une épicondylalgie ?",back:"Une douleur plus distale avec faiblesse des extenseurs du poignet et des doigts.",sources:["PUBMED-FROHSE-2025"],relatedIds:["1.6-KN-04"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-684",ue:"1.6",front:"Que faire devant un déficit brutal d'extension du poignet après fracture humérale ?",back:"Évoquer une paralysie radiale et orienter en urgence.",sources:["PUBMED-RADIAL-HSF-REVIEW","PUBMED-HSF-EDU-2026"],relatedIds:["1.6-KN-04"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-685",ue:"1.6",front:"Quelle place occupe la neuropathie ulnaire au coude parmi les neuropathies d'entrapment ?",back:"La deuxième, après le canal carpien.",sources:["COCHRANE-UNE-2025"],relatedIds:["1.6-DX-04"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-686",ue:"1.6",front:"Quels muscles paralysés affaiblissent la pince dans l'atteinte ulnaire ?",back:"Le premier interosseux dorsal et l'adducteur du pouce.",sources:["PUBMED-ULNAR-PINCH-2026"],relatedIds:["1.6-DX-04"],audience:"STUDENT",difficultyBand:"ADVANCED"},{id:"FC-687",ue:"1.6",front:"Quel muscle est le plus souvent faible dans une neuropathie ulnaire aiguë au coude ?",back:"L'abducteur du petit doigt.",sources:["PUBMED-UNE-ACUTE-2026"],relatedIds:["1.6-DX-04"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-688",ue:"1.6",front:"Que repose le traitement conservateur de la neuropathie ulnaire au coude ?",back:"Sur l'éducation du patient, la modification d'activité et l'attelle nocturne.",sources:["PUBMED-UNE-CONSERVATIVE"],relatedIds:["1.6-DX-04"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-689",ue:"1.9",front:"Quel effet la grossesse a-t-elle sur la capacité résiduelle fonctionnelle ?",back:"Elle diminue.",sources:["PUBMED-PREG-RESP-2025"],relatedIds:["1.9-KN-12"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-690",ue:"1.9",front:"Quelle fréquence d'hydronéphrose en grossesse et quelle part symptomatique ?",back:"Environ 90 %, dont environ 3 % symptomatiques.",sources:["PUBMED-PREG-HYDRONEPHROSIS"],relatedIds:["1.9-KN-12"],audience:"STUDENT",difficultyBand:"ADVANCED"},{id:"FC-691",ue:"1.9",front:"Pourquoi distinguer adaptation et pathologie en grossesse ?",back:"Certaines adaptations imitent des symptômes de maladie.",sources:["PUBMED-PREG-PHYSIO-2016"],relatedIds:["1.9-KN-12"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-692",ue:"2.8",front:"Quel test fonctionnel est recommandé pour la douleur de la ceinture pelvienne ?",back:"Le soulèvement actif de la jambe tendue (ASLR).",sources:["PUBMED-PGP-EUROPEAN-2008"],relatedIds:["2.8-DX-05"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-693",ue:"2.8",front:"Les tests de mobilité sacro-iliaque par palpation sont-ils recommandés dans la douleur de la ceinture pelvienne ?",back:"Non : la guideline européenne ne les recommande pas.",sources:["PUBMED-PGP-EUROPEAN-2008"],relatedIds:["2.8-DX-05"],audience:"CLINICAL",difficultyBand:"ADVANCED"},{id:"FC-694",ue:"2.8",front:"Quels facteurs de risque probables de douleur de la ceinture pelvienne gravidique ?",back:"Un antécédent de lombalgie et un traumatisme antérieur du bassin.",sources:["PUBMED-PGP-EUROPEAN-2008"],relatedIds:["2.8-DX-05"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-695",ue:"2.8",front:"Quelle intervention a une efficacité de certitude modérée sur la douleur de la ceinture pelvienne ?",back:"L'exercice.",sources:["PUBMED-PGP-EXERCISE-2026"],relatedIds:["2.8-DX-05"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-696",ue:"2.8",front:"Que dit la revue exploratoire sur la thérapie manuelle dans cette douleur ?",back:"Réduction de douleur en général, mais effets faibles ou inconsistants et preuve limitée.",sources:["PUBMED-PGP-MANUAL-2026"],relatedIds:["2.8-DX-05"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-697",ue:"2.8",front:"Quelle est la définition de la pré-éclampsie ?",back:"Hypertension avec protéinurie après 20 semaines de grossesse.",sources:["PUBMED-PREECLAMPSIA-2026","PUBMED-PREECLAMPSIA-BRAIN","PUBMED-PREECLAMPSIA-BIOSENSORS"],relatedIds:["2.8-RF-07"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-698",ue:"2.8",front:"L'absence de symptôme exclut-elle une pré-éclampsie ?",back:"Non : certaines formes sont presque asymptomatiques.",sources:["PUBMED-PREECLAMPSIA-2026"],relatedIds:["2.8-RF-07"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-699",ue:"2.8",front:"Que faire devant céphalée en casque, troubles visuels et douleur épigastrique après 20 semaines ?",back:"Prendre la pression artérielle et orienter en urgence.",sources:["PUBMED-PREECLAMPSIA-2026","PUBMED-PREECLAMPSIA-BRAIN","PUBMED-PREECLAMPSIA-BIOSENSORS"],relatedIds:["2.8-RF-07"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-700",ue:"5.2",front:"Quels tests palpatoires du rachis ont le plus souvent une fiabilité acceptable ?",back:"Les tests de provocation de la douleur (64 % des études).",sources:["PUBMED-PALPATION-SEFFINGER-2004"],relatedIds:["5.2-KN-02"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-701",ue:"5.2",front:"Quelle fiabilité acceptable pour la palpation de tissus mous dans la revue de 2004 ?",back:"Aucune étude (0 %) ne l'a montrée.",sources:["PUBMED-PALPATION-SEFFINGER-2004"],relatedIds:["5.2-KN-02"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-702",ue:"5.2",front:"Quelle différence entre fiabilité et validité d'un test ?",back:"La fiabilité mesure la reproductibilité ; la validité mesure l'exactitude du diagnostic.",sources:["PUBMED-PALPATION-SEFFINGER-2004"],relatedIds:["5.2-KN-02"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-703",ue:"5.2",front:"Où se situe le compartiment du fascia iliaca ?",back:"Sous le fascia iliaca, au-dessus des muscles iliaque et psoas.",sources:["PUBMED-FASCIA-ILIACA-2026"],relatedIds:["5.2-KN-03"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-704",ue:"5.2",front:"Où se situe le fascia endothoracique ?",back:"Entre la plèvre pariétale et les muscles intercostaux profonds.",sources:["PUBMED-ENDOTHORACIC-RAT-2012"],relatedIds:["5.2-KN-03"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-705",ue:"5.2",front:"L'existence anatomique d'un fascia prouve-t-elle l'efficacité d'une technique fasciale ?",back:"Non : le rôle fonctionnel reste un modèle à étayer.",sources:["PUBMED-FASCIA-ILIACA-2026"],relatedIds:["5.2-KN-03"],audience:"CLINICAL",difficultyBand:"ADVANCED"},{id:"FC-706",ue:"4.1",front:"Quels sont les quatre postulats de l'ostéopathie enseignés (attribués à Still) ?",back:"Globalité, structure-fonction, loi de l'artère, autoguérison.",sources:["COURS-COS-UE-4.1"],relatedIds:["4.1-KN-04"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-707",ue:"4.1",front:"Autoguérison et homéostasie : quelle différence dans l'enseignement ?",back:"Autoguérison = changement d'état (maladie vers santé) ; homéostasie = maintien d'un état.",sources:["COURS-COS-UE-4.1"],relatedIds:["4.1-KN-04"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-708",ue:"4.1",front:"Les postulats de Still sont-ils des mécanismes physiologiques démontrés ?",back:"Non : ils sont enseignés comme philosophie et cadre de raisonnement.",sources:["COURS-COS-UE-4.1","BORDONI-OSTEOPRINCIPLES-2021","WHO-OSTEO-BENCHMARKS-2010"],relatedIds:["4.1-KN-04"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-709",ue:"4.1",front:"Qui a fondé la British School of Osteopathy et en quelle année ?",back:"J.M. Littlejohn, en 1917 à Londres.",sources:["COURS-COS-UE-4.1"],relatedIds:["4.1-KN-05"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-710",ue:"4.1",front:"Quel ouvrage de 1939 marque l'origine du concept crânien dans le cours ?",back:"The Cranial Bowl, de W.G. Sutherland.",sources:["COURS-COS-UE-4.1"],relatedIds:["4.1-KN-05"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-711",ue:"4.1",front:"Quelle opposition sépare Still et Littlejohn dans le récit enseigné ?",back:"Anatomie et structure (Still) contre physiologie (Littlejohn).",sources:["COURS-COS-UE-4.1"],relatedIds:["4.1-KN-05"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-712",ue:"4.1",front:"Quels trois modèles ostéopathiques contemporains le cours distingue-t-il ?",back:"Biomécanique, fluidique, biodynamique.",sources:["COURS-COS-UE-4.1"],relatedIds:["4.1-KN-06"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-713",ue:"4.1",front:"Quel modèle repose sur la règle de l'artère et la libre circulation des fluides ?",back:"Le modèle fluidique.",sources:["COURS-COS-UE-4.1"],relatedIds:["4.1-KN-06"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-714",ue:"4.1",front:"Quels auteurs incarnent la 3e génération du modèle biodynamique ?",back:"Rollin Becker, James Jealous et Anne Wales.",sources:["COURS-COS-UE-4.1"],relatedIds:["4.1-KN-06"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-715",ue:"4.1",front:"Que décrit la ligne centrale de gravité dans le modèle de Littlejohn ?",back:"Un trajet de l'odontoïde de C2 au corps de L3, au promontoire, à la hanche, au genou et à l'articulation talo-naviculaire.",sources:["COURS-COS-UE-4.1"],relatedIds:["4.1-KN-07"],audience:"STUDENT",difficultyBand:"ADVANCED"},{id:"FC-716",ue:"4.1",front:"Que signifie l'abréviation TOG en ostéopathie ?",back:"Traitement ostéopathique général (ajustement corporel de Littlejohn, repris par Wernham).",sources:["COURS-COS-UE-4.1"],relatedIds:["4.1-KN-07"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-717",ue:"4.1",front:"Le TOG est-il présenté comme un traitement d'efficacité démontrée ?",back:"Non : c'est une méthode enseignée dont l'effet clinique reste à établir.",sources:["COURS-COS-UE-4.1"],relatedIds:["4.1-KN-07"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-718",ue:"4.2",front:"De quels deux temps se compose le diagnostic ostéopathique enseigné ?",back:"Diagnostic d'opportunité (visée médicale) et diagnostic fonctionnel (visée ostéopathique).",sources:["COURS-COS-UE-4.2","COURS-COS-UE-4.3"],relatedIds:["4.2-KN-03"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-719",ue:"4.2",front:"Que signifie SOPIE dans la consultation ?",back:"Situation, Objectif, Procédure, Intervention, Exécution.",sources:["COURS-COS-UE-4.2","COURS-COS-UE-4.3"],relatedIds:["4.2-KN-03"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-720",ue:"4.2",front:"Que signifie IPPANOR pour l'examen physique ?",back:"Inspection, palpation, percussion, auscultation, neurologie, ostéo-articulaire, rachis.",sources:["COURS-COS-UE-4.2","COURS-COS-UE-4.3"],relatedIds:["4.2-KN-03"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-721",ue:"4.2",front:"Comment le cours définit-il l'élasticité d'un tissu ?",back:"Sa capacité à se déformer puis à revenir à sa position initiale.",sources:["COURS-COS-UE-4.2"],relatedIds:["4.2-KN-04"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-722",ue:"4.2",front:"Test global ou spécifique : lequel oriente vers une zone sans la localiser ?",back:"Le test global.",sources:["COURS-COS-UE-4.2"],relatedIds:["4.2-KN-04"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-723",ue:"4.2",front:"La perte d'élasticité palpée est-elle une dysfonction cliniquement validée ?",back:"Non : c'est un modèle enseigné, la fiabilité de la palpation des tissus mous est limitée.",sources:["COURS-COS-UE-4.2","PUBMED-PALPATION-SEFFINGER-2004"],relatedIds:["4.2-KN-04"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-724",ue:"5.4",front:"Que décrit la SSB dans le modèle crânien ?",back:"L'articulation entre le corps du sphénoïde (partie postérieure) et la partie basilaire de l'occiput (le cours écrit « partie antérieure du basion » ; le basion est un point du bord antérieur du foramen magnum).",sources:["COURS-COS-UE-5.4","WIKI-BASILAR-PART-OCCIPITAL"],relatedIds:["5.4-KN-01"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-725",ue:"5.4",front:"Quels mouvements sont dits aphysiologiques dans le modèle de la SSB ?",back:"Les strains verticaux, les strains horizontaux et la compression.",sources:["COURS-COS-UE-5.4"],relatedIds:["5.4-KN-01"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-726",ue:"5.4",front:"Dans le modèle, flexion de la SSB : que fait l'occiput ?",back:"Il fait une rotation postérieure (le sphénoïde fait une rotation antérieure).",sources:["COURS-COS-UE-5.4"],relatedIds:["5.4-KN-01"],audience:"STUDENT",difficultyBand:"ADVANCED"},{id:"FC-727",ue:"5.4",front:"Dans l'enseignement, qu'est-ce que l'os primaire ?",back:"L'os qui initie le mouvement le plus vite ou qui va le plus loin.",sources:["COURS-COS-UE-5.4"],relatedIds:["5.4-KN-02"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-728",ue:"5.4",front:"Technique directe ou indirecte : laquelle va dans le sens de la dysfonction ?",back:"L'indirecte, jusqu'à la barrière tissulaire.",sources:["COURS-COS-UE-5.4"],relatedIds:["5.4-KN-02"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-729",ue:"5.4",front:"Où est placé le praticien pour le test de la SSB par la voûte ?",back:"Assis à la tête du patient en décubitus, index sur les grandes ailes du sphénoïde.",sources:["COURS-COS-UE-5.4"],relatedIds:["5.4-KN-02"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-730",ue:"5.4",front:"Que conclut la revue de 2016 sur la fiabilité du diagnostic crânien ?",back:"Les procédures diagnostiques sont peu fiables (8 études sur 9 à risque élevé de biais).",sources:["PUBMED-CRANIAL-GUILLAUD-2016"],relatedIds:["5.4-KN-03"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-731",ue:"5.4",front:"Existe-t-il une preuve d'efficacité spécifique des techniques crâniennes ?",back:"Non : seules 3 études sur 14 sont à faible risque de biais, avec des effets modestes possiblement non spécifiques.",sources:["PUBMED-CRANIAL-GUILLAUD-2016"],relatedIds:["5.4-KN-03"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-732",ue:"5.4",front:"Les revues sur le crânien disent-elles que le modèle n'a pas d'intérêt pédagogique ?",back:"Non : elles jugent fiabilité et efficacité spécifique, pas la présence d'un modèle enseigné.",sources:["PUBMED-CRANIAL-GUILLAUD-2016","PUBMED-CRANIOSACRAL-JAKEL-2012"],relatedIds:["5.4-KN-03"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-733",ue:"5.7",front:"Quel niveau vertébral correspond à chacun des trois orifices du diaphragme ?",back:"Veine cave inférieure T8, œsophage T10, aorte T12.",sources:["RADIOPAEDIA-DIAPHRAGM-APERTURES"],relatedIds:["5.7-KN-01"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-734",ue:"5.7",front:"Quelle est l'origine du nerf phrénique ?",back:"Les branches antérieures de C3 à C5.",sources:["STATPEARLS-PHRENIC-NERVES"],relatedIds:["5.7-KN-01"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-735",ue:"5.7",front:"Quel orifice diaphragmatique laisse passer le nerf phrénique droit ?",back:"L'orifice de la veine cave inférieure, à T8.",sources:["RADIOPAEDIA-DIAPHRAGM-APERTURES","STATPEARLS-PHRENIC-NERVES"],relatedIds:["5.7-KN-01"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-736",ue:"5.7",front:"Dans le test d'écoute des piliers, comment sont placées les mains ?",back:"Main gauche sur le pilier droit, main droite sur le pilier gauche.",sources:["COURS-COS-UE-5.7"],relatedIds:["5.7-KN-02"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-737",ue:"5.7",front:"Quel est le principe respiratoire de la technique de Chantepie ?",back:"Gagner la pression à chaque expiration, relâcher progressivement.",sources:["COURS-COS-UE-5.7"],relatedIds:["5.7-KN-02"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-738",ue:"5.7",front:"Les indications citées pour le travail du diaphragme sont-elles démontrées ?",back:"Non : ce sont des indications enseignées, sans effet démontré dans ce registre.",sources:["COURS-COS-UE-5.7"],relatedIds:["5.7-KN-02"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-739",ue:"5.7",front:"Quel est un autre nom de la membrane suprapleurale ?",back:"Le fascia de Sibson.",sources:["RADIOPAEDIA-SUPRAPLEURAL"],relatedIds:["5.7-KN-03"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-740",ue:"5.7",front:"Dans le test enseigné, quel mouvement de tête teste le ligament transverso-pleural ?",back:"L'inclinaison controlatérale.",sources:["COURS-COS-UE-5.7"],relatedIds:["5.7-KN-03"],audience:"STUDENT",difficultyBand:"ADVANCED"},{id:"FC-741",ue:"5.7",front:"Une céphalée brutale inhabituelle est-elle une indication au travail du dôme pleural ?",back:"Non : c'est une contre-indication enseignée et un signe d'alerte médicale.",sources:["COURS-COS-UE-5.7"],relatedIds:["5.7-KN-03"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-742",ue:"6.1",front:"Quel critère définit la recherche ostéopathique dans le cours ?",back:"Sa contribution à améliorer la pratique ou à comprendre le métier.",sources:["COURS-COS-UE-6.1","ATSRI-HISTORY"],relatedIds:["6.1-KN-02"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-743",ue:"6.1",front:"Qui a proposé le segment facilité, selon le cours ?",back:"J.S. Denslow et I.M. Korr.",sources:["COURS-COS-UE-6.1","ATSRI-HISTORY"],relatedIds:["6.1-KN-02"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-744",ue:"6.1",front:"Le segment facilité est-il un diagnostic validé ?",back:"Non : hypothèse physiologique de la recherche ostéopathique.",sources:["COURS-COS-UE-6.1","ATSRI-HISTORY"],relatedIds:["6.1-KN-02"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-745",ue:"6.2",front:"Que signifie « un genre, plusieurs styles » ?",back:"Un même genre professionnel s'exprime dans plusieurs styles de pratique.",sources:["COURS-COS-UE-6.2"],relatedIds:["6.2-KN-07"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-746",ue:"6.2",front:"Qu'étudie la recherche qualitative ?",back:"Le sens, les expériences et les déterminants des soins, à partir de données verbales.",sources:["COURS-COS-UE-6.2","PMC-POPE-MAYS-1995"],relatedIds:["6.2-KN-07"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-747",ue:"6.2",front:"Une étude qualitative peut-elle mesurer l'efficacité d'un traitement ?",back:"Non : elle complète les études quantitatives sans les remplacer.",sources:["COURS-COS-UE-6.2","PMC-POPE-MAYS-1995"],relatedIds:["6.2-KN-07"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-748",ue:"1.6",front:"Quelle est l'origine du nerf musculo-cutané ?",back:"Faisceau latéral du plexus brachial (C5 à C7).",sources:["PUBMED-MUSCULOCUTANEOUS-STATPEARLS"],relatedIds:["1.6-KN-05"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-749",ue:"1.6",front:"Quels muscles le nerf musculo-cutané innerve-t-il au bras ?",back:"Le biceps brachial et le brachial.",sources:["PUBMED-MUSCULOCUTANEOUS-STATPEARLS"],relatedIds:["1.6-KN-05"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-750",ue:"1.6",front:"Comment s'appelle sa continuation sensitive à l'avant-bras ?",back:"Le nerf cutané latéral de l'avant-bras.",sources:["PUBMED-MUSCULOCUTANEOUS-STATPEARLS"],relatedIds:["1.6-KN-05"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-751",ue:"2.5",front:"Que conditionne la stabilité d'une fracture de Jefferson ?",back:"L'intégrité du ligament transverse (règle de Spence : débord cumulé d'environ 7 mm).",sources:["PMC-MARCON-CSPINE-2013","PMC-MEAD-C1-2016"],relatedIds:["2.5-KN-01"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-752",ue:"2.5",front:"Fracture de la dent de l'axis : quel type est le plus fréquent et instable ?",back:"Le type II d'Anderson et D'Alonzo, à la base de la dent.",sources:["PMC-MARCON-CSPINE-2013","PMC-MEAD-C1-2016"],relatedIds:["2.5-KN-01"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-753",ue:"2.5",front:"Que faire après un traumatisme cervical avec suspicion de fracture ?",back:"Immobiliser et orienter vers une imagerie médicale, sans test actif ni manipulation.",sources:["PMC-MARCON-CSPINE-2013","PMC-MEAD-C1-2016"],relatedIds:["2.5-KN-01"],audience:"CLINICAL",difficultyBand:"ADVANCED"},{id:"FC-754",ue:"1.9",front:"Combien de segments fonctionnels compte le foie (Couinaud) ?",back:"Huit.",sources:["RADIOPAEDIA-LIVER"],relatedIds:["1.9-KN-13"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-755",ue:"1.9",front:"Quel apport sanguin vient de la veine porte ?",back:"Environ 75 % du sang hépatique (riche en nutriments, pauvre en oxygène).",sources:["RADIOPAEDIA-LIVER"],relatedIds:["1.9-KN-13"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-756",ue:"1.9",front:"Le ligament rond du foie est le reliquat de quelle structure ?",back:"La veine ombilicale.",sources:["RADIOPAEDIA-LIVER"],relatedIds:["1.9-KN-13"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-757",ue:"1.9",front:"Quel est le rôle des contractions haustrales ?",back:"Brasser le contenu et favoriser l'absorption d'eau.",sources:["STATPEARLS-LARGE-INTESTINE"],relatedIds:["1.9-KN-14"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-758",ue:"1.9",front:"Quel est le rôle des mouvements de masse du côlon ?",back:"Propulser rapidement le contenu fécal vers le rectum.",sources:["STATPEARLS-LARGE-INTESTINE"],relatedIds:["1.9-KN-14"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-759",ue:"1.9",front:"Comment l'eau est-elle absorbée dans le côlon ?",back:"Par osmose, suivant l'absorption active du sodium.",sources:["STATPEARLS-LARGE-INTESTINE"],relatedIds:["1.9-KN-14"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-760",ue:"1.9",front:"Où sont absorbés la B12 et les sels biliaires ?",back:"Dans l'iléon terminal.",sources:["AMBOSS-SMALL-INTESTINE"],relatedIds:["1.9-KN-15"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-761",ue:"1.9",front:"Où est absorbé l'essentiel des glucides et des protéines ?",back:"Dans le jéjunum.",sources:["AMBOSS-SMALL-INTESTINE"],relatedIds:["1.9-KN-15"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-762",ue:"1.9",front:"Où est absorbé surtout le fer ?",back:"Dans le duodénum et le jéjunum proximal.",sources:["AMBOSS-SMALL-INTESTINE"],relatedIds:["1.9-KN-15"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-763",ue:"3.3",front:"Quelle population le dépistage organisé du sein vise-t-il en France ?",back:"Les femmes de 50 à 74 ans, mammographie tous les deux ans.",sources:["SPF-DEPISTAGE-SEIN"],relatedIds:["3.3-KN-04"],audience:"STUDENT",difficultyBand:"FOUNDATION",jurisdiction:"FR"},{id:"FC-764",ue:"3.3",front:"Quel est l'intérêt de la deuxième lecture dans ce programme ?",back:"Elle est systématique pour un examen jugé normal.",sources:["SPF-DEPISTAGE-SEIN"],relatedIds:["3.3-KN-04"],audience:"STUDENT",difficultyBand:"INTERMEDIATE",jurisdiction:"FR"},{id:"FC-765",ue:"3.3",front:"Les bornes d'âge françaises sont-elles universelles ?",back:"Non : ce sont celles du programme français.",sources:["SPF-DEPISTAGE-SEIN"],relatedIds:["3.3-KN-04"],audience:"BOTH",difficultyBand:"INTERMEDIATE",jurisdiction:"FR"},{id:"FC-766",ue:"5.7",front:"Quelles sont les sept étapes du protocole fascial enseigné ?",back:"Anamnèse, observation, tests d'écoute, tests de mobilité, projet thérapeutique, traitement, réévaluation.",sources:["COURS-COS-UE-5.7"],relatedIds:["5.7-KN-04"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-767",ue:"5.7",front:"À quoi correspond PALPATE ?",back:"Mnémotechnique de palpation : position, anatomie, niveau, objectif, vérification, ajustement, évaluation.",sources:["COURS-COS-UE-5.7"],relatedIds:["5.7-KN-04"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-768",ue:"5.7",front:"Quel signe indique une pression de palpation excessive ?",back:"Le blanchissement de la pointe des ongles du praticien.",sources:["COURS-COS-UE-5.7"],relatedIds:["5.7-KN-04"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-769",ue:"5.7",front:"Quelle différence entre induction et traitement direct ?",back:"L'induction suit les tensions jusqu'au point de fixation ; le direct agit sur la zone fixée.",sources:["COURS-COS-UE-5.7"],relatedIds:["5.7-KN-05"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-770",ue:"5.7",front:"En quoi consiste le recoil ?",back:"Un appui dans la densité puis un retrait rapide pour créer une onde sur les fibres.",sources:["COURS-COS-UE-5.7"],relatedIds:["5.7-KN-05"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-771",ue:"5.7",front:"La durée maximale de 90 secondes de l'induction est-elle validée ?",back:"Non : c'est une convention d'enseignement.",sources:["COURS-COS-UE-5.7"],relatedIds:["5.7-KN-05"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-772",ue:"5.7",front:"Fascias ou fascia : quelle différence enseignée ?",back:"Fascias topographiques (Paoletti) contre fascia unique et continu (embryologie).",sources:["COURS-COS-UE-5.7"],relatedIds:["5.7-KN-06"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-773",ue:"5.7",front:"Quelles sont les deux approches distinguées dans le cours ?",back:"L'approche fasciale (origine américaine) et l'approche tissulaire (origine française).",sources:["COURS-COS-UE-5.7"],relatedIds:["5.7-KN-06"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-774",ue:"5.7",front:"Le continuum fascial est-il un consensus ?",back:"Non : c'est une proposition conceptuelle, la définition du fascia reste débattue.",sources:["PUBMED-FASCIA-FNC","PUBMED-FASCIA-NOMEN"],relatedIds:["5.7-KN-06"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-775",ue:"5.7",front:"Que concluent les revues de 2015 et de 2018 sur le relâchement myofascial ?",back:"2015 : encourageant mais qualité inégale ; 2018 : preuves insuffisantes pour la douleur chronique.",sources:["PUBMED-MFR-AJIMSHA-2015","DOI-MFR-LAIMI-2018"],relatedIds:["5.7-KN-07"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-776",ue:"5.7",front:"Ces revues valident-elles le protocole enseigné au COS ?",back:"Non : elles portent sur le relâchement myofascial en général.",sources:["PUBMED-MFR-AJIMSHA-2015","DOI-MFR-LAIMI-2018"],relatedIds:["5.7-KN-07"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-777",ue:"5.7",front:"Quel statut épistémique pour le relâchement myofascial dans ce registre ?",back:"CONFLICTING : deux revues systématiques divergent.",sources:["PUBMED-MFR-AJIMSHA-2015","DOI-MFR-LAIMI-2018"],relatedIds:["5.7-KN-07"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-778",ue:"5.6",front:"Motricité, mobilité, motilité : définir la motricité.",back:"Mouvement induit par la contraction des fibres musculaires de l'organe.",sources:["COURS-COS-UE-5.6"],relatedIds:["5.6-KN-01"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-779",ue:"5.6",front:"Définir la mobilité viscérale.",back:"Déplacement passif des viscères lié à la respiration, à la marche et aux mouvements du tronc.",sources:["COURS-COS-UE-5.6"],relatedIds:["5.6-KN-01"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-780",ue:"5.6",front:"Que précise le cours sur l'origine de la motilité ?",back:"Qu'elle est controversée.",sources:["COURS-COS-UE-5.6"],relatedIds:["5.6-KN-01"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-781",ue:"5.2",front:"Quelle formule est attribuée à Fuller pour la tenségrité ?",back:"Des îlots de compression dans un océan de tension.",sources:["COURS-COS-UE-5.2"],relatedIds:["5.2-KN-04"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-782",ue:"5.2",front:"Qui a appliqué la tenségrité à la cellule, et qui au corps entier ?",back:"Ingber à la cellule, Levin au corps entier (biotenségrité).",sources:["COURS-COS-UE-5.2"],relatedIds:["5.2-KN-04"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-783",ue:"5.2",front:"La biotenségrité du corps entier est-elle démontrée ?",back:"Non : aucune étude in vitro ou in vivo ne la démontre (Bordoni 2019) ; c'est un modèle débattu.",sources:["DOI-INGBER-TENSEGRITY-2003","PMC-BORDONI-FASCINTEGRITY-2019"],relatedIds:["5.2-KN-04"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-784",ue:"1.6",front:"Quel muscle innerve le nerf thoracique long ?",back:"Le dentelé antérieur (racines C5 à C7).",sources:["KENHUB-BRACHIAL-PLEXUS","PMC-POSTERIOR-CORD-2026","JBPPNI-BRACHIAL-PLEXUS-2007"],relatedIds:["1.6-KN-06"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-785",ue:"1.6",front:"Quels muscles innerve le nerf suprascapulaire ?",back:"Le supra-épineux et l'infra-épineux (tronc supérieur, C5-C6).",sources:["KENHUB-BRACHIAL-PLEXUS","PMC-POSTERIOR-CORD-2026","JBPPNI-BRACHIAL-PLEXUS-2007"],relatedIds:["1.6-KN-06"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-786",ue:"1.6",front:"Dans quel ordre se divise le plexus brachial ?",back:"Racines → troncs → divisions → cordons → branches terminales.",sources:["KENHUB-BRACHIAL-PLEXUS","PMC-POSTERIOR-CORD-2026","JBPPNI-BRACHIAL-PLEXUS-2007"],relatedIds:["1.6-KN-06"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-787",ue:"1.6",front:"Quelles branches terminales du plexus brachial sont issues du cordon postérieur ?",back:"Le nerf axillaire et le nerf radial (le radial en est la continuation).",sources:["KENHUB-BRACHIAL-PLEXUS","PMC-POSTERIOR-CORD-2026","JBPPNI-BRACHIAL-PLEXUS-2007"],relatedIds:["1.6-KN-06"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-788",ue:"2.11",front:"Que cherche à rompre l'EPR dans le TOC ?",back:"Le cycle obsession, compulsion ou évitement, soulagement bref : on expose sans laisser faire le rituel.",sources:["PMC-ERP-OCD-2019"],relatedIds:["2.11-KN-01"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-789",ue:"2.11",front:"Quelle est la psychothérapie de première ligne du TOC ?",back:"L'exposition avec prévention de la réponse (EPR).",sources:["PMC-ERP-OCD-2019"],relatedIds:["2.11-KN-01"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-790",ue:"2.11",front:"Délai d'apparition d'un trouble de l'adaptation (DSM-5) ?",back:"Dans les 3 mois suivant un facteur de stress identifiable.",sources:["PMC-AJD-PERSPECTIVES-2018"],relatedIds:["2.11-KN-02"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-791",ue:"2.11",front:"Quels deux symptômes centrent le trouble de l'adaptation en CIM-11 ?",back:"La préoccupation (rumination du stresseur) et l'échec de l'adaptation.",sources:["PMC-AJD-PERSPECTIVES-2018"],relatedIds:["2.11-KN-02"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-792",ue:"2.11",front:"Score GAD-7 cité comme seuil d'évaluation approfondie ?",back:"8 ou plus (selon la revue citée) ; le GAD-7 ne pose pas de diagnostic.",sources:["PMC-GAD7-PRIMARYCARE-2020"],relatedIds:["2.11-EX-01"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-793",ue:"2.5",front:"Pourquoi un examen d'imagerie normal n'exclut-il pas une rupture partielle de coiffe ?",back:"La sensibilité est plus basse (0,67 à 0,83) pour les atteintes partielles, malgré une spécificité élevée.",sources:["PMC-RC-IMAGING-META-2015"],relatedIds:["2.5-KN-02"],audience:"CLINICAL",difficultyBand:"ADVANCED"},{id:"FC-794",ue:"2.5",front:"Quel examen est jugé le meilleur choix pour la coiffe (précision, coût, sécurité) ?",back:"L'échographie, dont la précision est comparable selon l'opérateur formé.",sources:["PMC-RC-IMAGING-META-2015"],relatedIds:["2.5-KN-02"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-795",ue:"2.5",front:"Quelles incidences radiographiques servent au diagnostic d'une tendinopathie calcifiante ?",back:"Face, profil de coiffe (outlet) et axillaire.",sources:["PMC-RC-CALCIFIC-2018"],relatedIds:["2.5-KN-03"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-796",ue:"2.5",front:"Une calcification de coiffe peut-elle disparaître sans traitement spécifique ?",back:"Oui, une résorption spontanée avec guérison du tendon est décrite.",sources:["PMC-RC-CALCIFIC-2018"],relatedIds:["2.5-KN-03"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-797",ue:"2.5",front:"Quel niveau de preuve pour les exercices dans la tendinopathie de coiffe des travailleurs ?",back:"Faible à modéré (revue de 10 essais randomisés).",sources:["PMC-RC-EXERCISE-WORKERS-2016"],relatedIds:["2.5-KN-04"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-798",ue:"1.7",front:"En quelles deux branches l'artère fémorale commune se divise-t-elle ?",back:"L'artère superficielle et l'artère profonde.",sources:["PMC-FEMORAL-ACCESS-2024"],relatedIds:["1.7-KN-05"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-799",ue:"1.7",front:"Quel rapport entre veine fémorale commune et artère fémorale superficielle sous la bifurcation ?",back:"La veine passe derrière l'artère.",sources:["PMC-FEMORAL-ACCESS-2024"],relatedIds:["1.7-KN-05"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-800",ue:"1.7",front:"Quelles structures accompagnent l'artère tibiale postérieure dans le tunnel tarsien ?",back:"Les veines tibiales postérieures et le nerf tibial.",sources:["PMC-POSTERIOR-TIBIAL-2023"],relatedIds:["1.7-KN-06"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-801",ue:"1.7",front:"Quelle artère donne la tibiale postérieure ?",back:"L'artère poplitée.",sources:["PMC-POSTERIOR-TIBIAL-2023"],relatedIds:["1.7-KN-06"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-802",ue:"2.5",front:"Quels niveaux cervicaux sont le plus souvent touchés par une luxation facettaire ?",back:"C5-C6 et C6-C7.",sources:["PMC-SUBAXIAL-FACET-2021"],relatedIds:["2.5-KN-05"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-803",ue:"2.5",front:"Quel mécanisme produit une luxation facettaire cervicale ?",back:"Flexion et distraction combinées, souvent un accident de la route ; la rotation donne plutôt une forme unilatérale.",sources:["PMC-SUBAXIAL-FACET-2021"],relatedIds:["2.5-KN-05"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-804",ue:"2.5",front:"Traumatisme cervical à haute énergie avec cervicalgie : que faire ?",back:"Immobiliser et orienter en urgence ; aucune manipulation cervicale.",sources:["PMC-SUBAXIAL-FACET-2021"],relatedIds:["2.5-KN-05"],audience:"CLINICAL",difficultyBand:"CLINICAL"},{id:"FC-805",ue:"2.7",front:"Quelle est la transmission de l'hypercholestérolémie familiale ?",back:"Autosomique dominante : un hétérozygote a 50 % de chances de la transmettre.",sources:["PMC-HEFH-DIAGNOSIS-2019"],relatedIds:["2.7-KN-01"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-806",ue:"2.7",front:"Les xanthomes sont-ils nécessaires au diagnostic d'hypercholestérolémie familiale hétérozygote ?",back:"Non : xanthomes et arc cornéen sont inconstants ; ils sont typiques de la forme homozygote.",sources:["PMC-HEFH-DIAGNOSIS-2019"],relatedIds:["2.7-KN-01"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-807",ue:"1.8",front:"Quel est le déterminant de l'apport en O2 aux tissus ?",back:"Contenu artériel en O2 × débit cardiaque.",sources:["PMC-HB-O2-DISSOCIATION-2015"],relatedIds:["1.8-KN-07"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-808",ue:"1.8",front:"Que provoque une hausse de PCO2, d'acidité ou de température sur la courbe de dissociation ?",back:"Un décalage vers la droite : moindre affinité de l'hémoglobine, libération d'O2 facilitée.",sources:["PMC-HB-O2-DISSOCIATION-2015"],relatedIds:["1.8-KN-07"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-809",ue:"1.8",front:"Pourquoi une SpO2 normale ne garantit-elle pas un apport tissulaire suffisant ?",back:"Elle ne tient pas compte de l'hémoglobine ni du débit cardiaque.",sources:["PMC-HB-O2-DISSOCIATION-2015"],relatedIds:["1.8-KN-07"],audience:"CLINICAL",difficultyBand:"CLINICAL"},{id:"FC-810",ue:"1.8",front:"Quelle est la P50 normale du sang adulte ?",back:"Environ 26 mmHg.",sources:["PMC-HB-O2-DISSOCIATION-2015"],relatedIds:["1.8-KN-07"],audience:"STUDENT",difficultyBand:"ADVANCED"},{id:"FC-811",ue:"1.7",front:"Quelle cellule osseuse résorbe la matrice osseuse ?",back:"L'ostéoclaste.",sources:["NCBI-BONE-PHYSIO"],relatedIds:["1.7-KN-04"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-812",ue:"1.7",front:"Quelle cellule osseuse maintient la matrice et détecte les contraintes ?",back:"L'ostéocyte.",sources:["NCBI-BONE-PHYSIO"],relatedIds:["1.7-KN-04"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-813",ue:"1.8",front:"Pourquoi le rapport V/Q est-il bas à la base du poumon ?",back:"La perfusion y augmente davantage que la ventilation.",sources:["NCBI-PULM-VENT-PERFUSION"],relatedIds:["1.8-KN-04"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-814",ue:"1.8",front:"Quel mécanisme définit le choc hypovolémique ?",back:"Une perte critique de volume intravasculaire (hémorragie, brûlures, diarrhée).",sources:["MSD-SHOCK"],relatedIds:["1.8-KN-06"],audience:"BOTH",difficultyBand:"FOUNDATION"},{id:"FC-815",ue:"1.8",front:"Quel mécanisme définit le choc distributif ?",back:"Une vasodilatation avec un volume circulant normal (septique, anaphylactique, neurogène).",sources:["MSD-SHOCK"],relatedIds:["1.8-KN-06"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-816",ue:"1.8",front:"Quel mécanisme définit le choc obstructif ?",back:"Un obstacle mécanique au remplissage ou à l'éjection cardiaque (pneumothorax compressif, tamponnade, embolie pulmonaire).",sources:["MSD-SHOCK"],relatedIds:["1.8-KN-06"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-817",ue:"1.6",front:"Où naissent les fibres parasympathiques ?",back:"Dans le tronc cérébral et la moelle sacrée S2-S3 (voie crânio-sacrée).",sources:["MSD-ANS-OVERVIEW"],relatedIds:["1.6-KN-03"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-818",ue:"1.6",front:"Quel nerf transporte environ 75 % des fibres parasympathiques ?",back:"Le nerf vague.",sources:["MSD-ANS-OVERVIEW"],relatedIds:["1.6-KN-03"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-819",ue:"2.4",front:"Comment réalise-t-on le test de Tinel au poignet ?",back:"Par percussion le long du canal carpien ; positif si elle reproduit les symptômes du médian.",sources:["PMC-CTS-REVIEW-2020"],relatedIds:["2.4-KN-03"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-820",ue:"2.4",front:"Quelle est la position du test de Phalen ?",back:"Flexion du poignet à 90° ; positif si elle reproduit les symptômes du médian.",sources:["PMC-CTS-REVIEW-2020"],relatedIds:["2.4-KN-03"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-821",ue:"2.4",front:"Quel signe marque le stade avancé du canal carpien ?",back:"L'hypotrophie ou l'atrophie de l'éminence thénar.",sources:["PMC-CTS-REVIEW-2020"],relatedIds:["2.4-KN-03"],audience:"BOTH",difficultyBand:"FOUNDATION"},{id:"FC-822",ue:"2.4",front:"Que rapportent les sources sur la précision de Tinel et de Phalen dans le canal carpien ?",back:"La revue de 2020 n'en chiffre aucune ; une méta-analyse de 2023 donne Phalen sensibilité 0,57 / spécificité 0,67 et Tinel 0,45 / 0,78 : discrimination faible.",sources:["PMC-CTS-REVIEW-2020","DABBAGH-CTS-TESTS-2023"],relatedIds:["2.4-KN-03"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-823",ue:"1.7",front:"Pourquoi l'ATM est-elle dite ginglymo-arthrodiale ?",back:"Elle associe un mouvement de charnière et un mouvement de glissement.",sources:["PMC-TMJ-INTERNAL-DERANGEMENTS-2015"],relatedIds:["1.7-KN-07"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-824",ue:"1.7",front:"De quel tissu sont revêtus le condyle et la fosse de l'ATM ?",back:"De tissu conjonctif fibreux, non de cartilage hyalin.",sources:["PMC-TMJ-INTERNAL-DERANGEMENTS-2015"],relatedIds:["1.7-KN-07"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-825",ue:"1.7",front:"Quel seuil d'ouverture assistée définit une ouverture limitée selon les DC/TMD ?",back:"Moins de 40 mm entre les bords incisifs.",sources:["PMC-TMJ-INTERNAL-DERANGEMENTS-2015"],relatedIds:["1.7-KN-07"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-826",ue:"1.7",front:"Quelle différence entre déplacement discal avec et sans réduction ?",back:"Avec réduction, le disque se replace à l'ouverture (claquement) ; sans réduction, il reste déplacé et l'ouverture peut être limitée.",sources:["PMC-TMJ-INTERNAL-DERANGEMENTS-2015"],relatedIds:["1.7-KN-07"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-827",ue:"2.11",front:"Quel est le sous-type de démence le plus fréquent ?",back:"La maladie d'Alzheimer.",sources:["PMC-DEMENTIA-BMJ-2015"],relatedIds:["2.11-KN-03"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-828",ue:"2.11",front:"Quels signes évoquent une démence à corps de Lewy ?",back:"Hallucinations visuelles complexes, parkinsonisme et fluctuations cognitives.",sources:["PMC-DEMENTIA-BMJ-2015"],relatedIds:["2.11-KN-03"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-829",ue:"2.11",front:"Quel tableau évoque une démence fronto-temporale ?",back:"Un changement de personnalité et de comportement vers 50-60 ans, mémoire initialement conservée.",sources:["PMC-DEMENTIA-BMJ-2015"],relatedIds:["2.11-KN-03"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-830",ue:"2.11",front:"Un dépistage de population de la démence est-il recommandé ?",back:"Non : la démence ne remplit pas les critères d'une maladie à dépister en population.",sources:["PMC-DEMENTIA-BMJ-2015"],relatedIds:["2.11-KN-03"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-831",ue:"1.6",front:"En quels trois lobes divise-t-on le cervelet ?",back:"Le lobe antérieur, le lobe postérieur et le lobe flocculo-nodulaire.",sources:["PMC-CEREBELLUM-FOCUS-2021"],relatedIds:["1.6-KN-07"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-832",ue:"1.6",front:"À quoi correspond le spino-cervelet ?",back:"Au vermis et au paravermis, qui reçoivent des afférences sensorimotrices de la moelle.",sources:["PMC-CEREBELLUM-FOCUS-2021"],relatedIds:["1.6-KN-07"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-833",ue:"1.6",front:"Le rôle du cervelet est-il purement moteur ?",back:"Non : il inclut aussi des fonctions cognitives, sociales et comportementales.",sources:["PMC-CEREBELLUM-FOCUS-2021"],relatedIds:["1.6-KN-07"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-834",ue:"1.6",front:"Où se situe le thalamus et quel est son rôle général ?",back:"Entre tronc cérébral et cortex ; relais et carrefour, impliqué dans la conscience et le sommeil.",sources:["PMC-THALAMUS-2025"],relatedIds:["1.6-KN-08"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-835",ue:"1.6",front:"Quelle voie visuelle passe par un noyau thalamique spécifique ?",back:"Rétine vers le corps genouillé latéral.",sources:["PMC-THALAMUS-2025"],relatedIds:["1.6-KN-08"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-836",ue:"2.9",front:"Nécrolyse épidermique toxique (Lyell) : quelle surface corporelle décollée ?",back:"≥ 30 % ; de 10 à 29 % : chevauchement SJS/Lyell.",sources:["NCBI-SJS-TEN"],relatedIds:["2.9-RF-04"]},{id:"FC-837",ue:"3.3",front:"Suisse : quel est le numéro d'urgence européen ?",back:"112.",sources:["BAKOM-URGENCES"],relatedIds:["3.3-KN-03"],jurisdiction:"CH"},{id:"FC-838",ue:"1.1",front:"Quel organite dégrade et digère les composants cellulaires devenus inutiles ?",back:"Le lysosome.",sources:["OPENSTAX-AP-3-2"],relatedIds:["1.1-KN-03"],audience:"STUDENT",reverseOf:"FC-177",difficultyBand:"FOUNDATION"},{id:"FC-839",ue:"1.1",front:"Quel organite est le site de synthèse des protéines à partir de l'ARN messager ?",back:"Le ribosome.",sources:["OPENSTAX-AP-3-2"],relatedIds:["1.1-KN-03"],audience:"STUDENT",reverseOf:"FC-178",difficultyBand:"FOUNDATION"},{id:"FC-840",ue:"2.3",front:"Appendicite aiguë : quel taux d'appendicectomie blanche est jugé acceptable, et pourquoi ?",back:"15 % : le retard diagnostique augmente la mortalité.",sources:["MSD-APPENDICITIS"],relatedIds:["2.3-DX-02"]},{id:"FC-841",ue:"3.4",front:"Suisse : quelles sanctions l'autorité de surveillance peut-elle prononcer (art. 19) ?",back:"Avertissement, blâme, amende ≤ 20 000 fr., interdiction de pratiquer ≤ 6 ans ou définitive.",sources:["FEDLEX-LPSAN"],relatedIds:["3.4-KN-04"],jurisdiction:"CH"},{id:"FC-845",ue:"2.12",front:"Arthrite septique de hanche de l'enfant : quels sont les critères de Kocher ?",back:"Fièvre, non-mise en charge, VS > 40, leucocytes > 12 000/mm³.",sources:["KOCHER-1999-SEPTIC-HIP"],relatedIds:["2.12-DX-01"]},{id:"FC-844",ue:"2.6",front:"Pneumothorax compressif : quels sites de décompression à l'aiguille sont décrits ?",back:"2e espace intercostal médio-claviculaire (ETC) ou 4e-5e espace axillaire (ATLS) ; recommandations divergentes.",sources:["MSD-PNEUMOTHORAX","PMC-NEEDLE-DECOMPRESSION-2025"],relatedIds:["2.6-RF-04"]},{id:"FC-842",ue:"1.9",front:"Équilibre acido-basique : quel est le délai d'action de la compensation respiratoire ?",back:"Minutes à heures (environ 50-75 % efficace).",sources:["MSD-ACID-BASE-REG"],relatedIds:["1.9-KN-05"]},{id:"FC-843",ue:"1.9",front:"Équilibre acido-basique : quel est le délai d'action de la compensation rénale ?",back:"Heures à jours (ajustement de la réabsorption et de l'excrétion du HCO3-).",sources:["MSD-ACID-BASE-REG"],relatedIds:["1.9-KN-05"]},{id:"FC-846",ue:"2.5",front:"Une douleur dorsale reproductible à la palpation est-elle forcément mécanique ?",back:"Non : elle n'exclut ni une cause viscérale ni une cause cardio-vasculaire concomitante.",sources:["PMC-TSP-PREVALENCE-2009","PMC-SERIOUS-PATHOLOGY-PET-2022"],relatedIds:["2.5-DX-01"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-847",ue:"2.5",front:"Que faut-il examiner en plus du rachis devant une douleur dorsale ?",back:"Les paramètres vitaux et l'auscultation cardio-pulmonaire, que certains professionnels rapportent peu.",sources:["PMC-SERIOUS-PATHOLOGY-PET-2022"],relatedIds:["2.5-DX-01"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-848",ue:"2.5",front:"Dans les cas publiés de douleur dorsale ou thoracique avec pathologie grave, quelle catégorie est la plus fréquente ?",back:"Les causes cardio-vasculaires, devant les fractures et les tumeurs.",sources:["PMC-SERIOUS-PATHOLOGY-PET-2022"],relatedIds:["2.5-DX-01"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-849",ue:"2.16",front:"Quel est le déclencheur de la maladie cœliaque ?",back:"Le gluten des céréales, chez un sujet prédisposé HLA-DQ2/DQ8 ; l'auto-antigène est la transglutaminase tissulaire.",sources:["PMC-CELIAC-REVIEW-2019"],relatedIds:["2.16-DX-01"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-850",ue:"2.16",front:"Pourquoi ne pas supprimer le gluten avant le bilan d'une suspicion de maladie cœliaque ?",back:"Les examens doivent être faits sous régime contenant du gluten ; l'éviction préalable peut les fausser.",sources:["PMC-CELIAC-REVIEW-2019"],relatedIds:["2.16-DX-01"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-851",ue:"2.16",front:"Quelle atteinte osseuse est fréquente au diagnostic d'une maladie cœliaque ?",back:"Une ostéopénie ou une ostéoporose (environ 70 % des patients au diagnostic selon la revue).",sources:["PMC-CELIAC-REVIEW-2019"],relatedIds:["2.16-DX-01"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-852",ue:"2.6",front:"Douleur thoracique : quelle caractéristique liée à l'effort oriente vers une cause cardiovasculaire ?",back:"Déclenchement ou aggravation par l'effort, soulagement par le repos.",sources:["NICE-CG95"],relatedIds:["2.6-RF-01"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-853",ue:"2.6",front:"Dissection aortique : quels signes évocateurs ?",back:"Douleur brutale, maximale d'emblée, déchirante, migratrice dans le dos ; asymétrie tensionnelle entre les deux bras.",sources:["NICE-CG95","NCBI-PE","ESC-PERICARDIAL-2015"],relatedIds:["2.6-DX-01"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-854",ue:"2.6",front:"Douleur thoracique pleurale (inspiration, toux, dyspnée) : quel groupe de causes ?",back:"Pulmonaire : embolie pulmonaire, pneumothorax, pleurésie.",sources:["NICE-CG95","NCBI-PE","ESC-PERICARDIAL-2015"],relatedIds:["2.6-DX-01"],audience:"BOTH",difficultyBand:"BASIC"},{id:"FC-855",ue:"2.6",front:"Douleur thoracique pariétale suivie en conservateur : que prévoir ?",back:"Une réévaluation programmée si non-résolution ou aggravation.",sources:["NICE-CG95","NCBI-DYSPNEA","NCBI-HF"],relatedIds:["2.6-MG-01"],audience:"BOTH",difficultyBand:"BASIC"},{id:"FC-856",ue:"2.6",front:"Pourquoi ne pas débuter un traitement manuel « pour voir » devant une douleur thoracique ?",back:"Une cause cardiovasculaire ou thromboembolique doit d'abord être écartée.",sources:["NICE-CG95","NCBI-DYSPNEA","NCBI-HF"],relatedIds:["2.6-MG-01"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-857",ue:"2.5",front:"Lombalgie : quel défaut d'anamnèse fait manquer une queue de cheval ?",back:"Ne pas interroger explicitement les fonctions urinaires/fécales et la sensibilité périnéale.",sources:["CORPUS-V1","NICE-NG59"],relatedIds:["2.5-RF-03"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-858",ue:"2.5",front:"Suspicion de queue de cheval : quelle place pour la prise en charge manuelle ?",back:"Elle ne doit pas retarder l'évaluation médicale urgente.",sources:["CORPUS-V1","NICE-NG59"],relatedIds:["2.5-RF-03"],audience:"BOTH",difficultyBand:"BASIC"},{id:"FC-859",ue:"2.5",front:"Lombalgie inflammatoire : quel profil d'activité et de repos ?",back:"Amélioration par l'activité, repos peu soulageant ; le profil mécanique est plutôt soulagé par le repos.",sources:["CORPUS-V1","UE25-PACK-V2"],relatedIds:["2.5-RF-04"],audience:"BOTH",difficultyBand:"BASIC"},{id:"FC-860",ue:"2.5",front:"Le profil inflammatoire d'une lombalgie suffit-il à diagnostiquer une spondyloarthrite axiale ?",back:"Non : il oriente vers une évaluation médicale (rhumatologie), il ne diagnostique pas.",sources:["CORPUS-V1","UE25-PACK-V2"],relatedIds:["2.5-RF-04"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-861",ue:"2.13",front:"Artérite à cellules géantes : pourquoi est-ce une urgence médicale ?",back:"Risque de cécité irréversible ; avis spécialisé idéalement le jour même.",sources:["BSR-GCA-2020"],relatedIds:["2.13-RF-06"],audience:"BOTH",difficultyBand:"BASIC"},{id:"FC-862",ue:"2.13",front:"Artérite à cellules géantes : quels éléments biologiques sont évocateurs ?",back:"Élévation de la VS et de la CRP, et des plaquettes.",sources:["BSR-GCA-2020"],relatedIds:["2.13-RF-06"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-863",ue:"1.6",front:"Paresthésies du pouce et de l'index : quelle confusion éviter ?",back:"Neuropathie médiane distale et radiculopathie cervicale C6-C7 : territoire et contexte différents.",sources:["NCBI-MEDIANNERVE"],relatedIds:["1.6-KN-01"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-864",ue:"2.6",front:"Asthme ou BPCO : quelles constantes constituent un red flag d'exacerbation sévère ?",back:"Fréquence respiratoire > 25/min, fréquence cardiaque > 110/min, ou aggravation rapide malgré le traitement de secours.",sources:["NICE-CKS-ASTHMA","NICE-CKS-COPD"],relatedIds:["2.6-RF-06"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-865",ue:"2.6",front:"Exacerbation sévère d'asthme ou de BPCO : que faire en attendant les secours ?",back:"Installer le patient assis, au calme, l'encourager à utiliser son bronchodilatateur de secours ; ne jamais retarder l'appel.",sources:["NICE-CKS-ASTHMA","NICE-CKS-COPD"],relatedIds:["2.6-RF-06"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-866",ue:"2.6",front:"BPCO dyspnéique au quotidien : par rapport à quoi juger une aggravation ?",back:"Par rapport à son état de base, pas par rapport à la normale.",sources:["NICE-CKS-ASTHMA","NICE-CKS-COPD"],relatedIds:["2.6-RF-06"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-867",ue:"2.7",front:"Ischémie mésentérique aiguë : un lactate normal l'exclut-il ?",back:"Non : marqueur tardif et non spécifique, sa normalité n'exclut pas une ischémie débutante.",sources:["MSD-MESENTERIC-ISCHEMIA"],relatedIds:["2.7-RF-06"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-868",ue:"2.7",front:"Ischémie mésentérique aiguë : quels signes apparaissent à l'infarctus constitué ?",back:"Sensibilité marquée, défense, rigidité, silence auscultatoire, sang dans les selles, choc ; l'infarctus peut survenir en 6 heures.",sources:["MSD-MESENTERIC-ISCHEMIA"],relatedIds:["2.7-RF-06"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-869",ue:"2.3",front:"Appendicite : en quoi consiste le signe de Rovsing ?",back:"Douleur en fosse iliaque droite à la palpation de la fosse iliaque gauche.",sources:["MSD-APPENDICITIS"],relatedIds:["2.3-DX-02"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-870",ue:"2.3",front:"Adénite mésentérique ou appendicite : que montre l'échographie dans l'adénite ?",back:"Des ganglions mésentériques ≥ 8 mm de petit axe, sans structure tubulaire borgne épaissie (appendice inflammatoire).",sources:["MSD-APPENDICITIS","NCBI-MESENTERIC-ADENITIS"],relatedIds:["2.3-DX-02"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-871",ue:"2.6",front:"Décompensation cardiaque ou exacerbation de BPCO : crépitants ou sibilants ?",back:"Cardiaque : crépitants bibasaux nouveaux. BPCO : sibilants avec expectoration modifiée.",sources:["NCBI-HF"],relatedIds:["2.6-RF-03"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-872",ue:"2.13",front:"Fracture de fragilité : quels outils évaluent le risque fracturaire ultérieur ?",back:"FRAX ou QFracture, quel que soit l'âge du patient.",sources:["NICE-CG146-OSTEOPOROSIS-RISK"],relatedIds:["2.13-RF-02"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-873",ue:"2.4",front:"Paralysie faciale périphérique avec éruption, otalgie sévère ou fièvre : que faut-il évoquer ?",back:"Une cause autre que la paralysie de Bell idiopathique : zona du ganglion géniculé, maladie de Lyme, tumeur.",sources:["NICE-CKS-BELLSPALSY","NICE-NG128"],relatedIds:["2.4-RF-05"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-874",ue:"2.4",front:"Paralysie de Bell isolée typique (front atteint, aucun autre signe) : quelle orientation ?",back:"Vers un médecin, pour confirmation diagnostique et traitement précoce.",sources:["NICE-CKS-BELLSPALSY","NICE-NG128"],relatedIds:["2.4-RF-05"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-875",ue:"2.7",front:"Occlusion intestinale : quel signe classique rechercher à l'anamnèse ?",back:"L'arrêt des matières et des gaz ; une diarrhée est possible dans l'occlusion incomplète.",sources:["NCBI-SBO","WSES-ASBO-2017"],relatedIds:["2.7-RF-05"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-876",ue:"2.5",front:"Règles d'Ottawa pour le genou : à partir de quel âge une radiographie est-elle recommandée après traumatisme ?",back:"À 55 ans ou plus (un critère parmi cinq).",sources:["PMC-ED-MSK-2026","PUBMED-OTTAWA-KNEE-1997"],relatedIds:["2.5-RF-11"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-877",ue:"2.5",front:"Que cherchent à écarter les règles d'Ottawa pour le genou ?",back:"Une fracture ; elles ne renseignent pas sur une lésion méniscale ou ligamentaire.",sources:["PMC-ED-MSK-2026","PUBMED-OTTAWA-KNEE-1997"],relatedIds:["2.5-RF-11"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-878",ue:"2.5",front:"Quelle part du plateau tibial les ménisques recouvrent-ils et quel est leur rôle ?",back:"Environ 70 % de la surface articulaire ; ils transmettent les charges et amortissent les chocs.",sources:["NCBI-MENISCAL-TEARS"],relatedIds:["2.5-DX-02"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-879",ue:"2.5",front:"Comment définit-on la douleur fémoro-patellaire (consensus 2016) ?",back:"Douleur autour ou derrière la patella, aggravée par une activité qui charge l'articulation sur un genou fléchi.",sources:["PMC-PFP-CONSENSUS-2016"],relatedIds:["2.5-DX-03"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-880",ue:"2.5",front:"Quel est le meilleur test clinique disponible pour la douleur fémoro-patellaire ?",back:"La douleur antérieure du genou reproduite à l'accroupissement ; aucun test n'est définitif.",sources:["PMC-PFP-CONSENSUS-2016"],relatedIds:["2.5-DX-03"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-881",ue:"2.5",front:"Selon l'OARSI 2019, quels traitements constituent le socle de la prise en charge de la gonarthrose ?",back:"Éducation à la maladie et exercice structuré au sol, avec ou sans gestion du poids.",sources:["PUBMED-OARSI-2019"],relatedIds:["2.5-RF-14"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-882",ue:"2.5",front:"Règles d'Ottawa pour la cheville : quels critères osseux justifient une radiographie ?",back:"Douleur de la zone malléolaire avec douleur au bord postérieur ou à la pointe d'une malléole, ou impossibilité de faire quatre pas.",sources:["PUBMED-OTTAWA-ANKLE-SR-2003","PMC-ED-MSK-2026"],relatedIds:["2.5-RF-12"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-883",ue:"2.5",front:"Règles d'Ottawa pour le pied : quels points osseux sont palpés ?",back:"La base du 5e métatarsien et le naviculaire, en cas de douleur de la zone médio-tarsienne.",sources:["PUBMED-OTTAWA-ANKLE-SR-2003","PMC-ED-MSK-2026"],relatedIds:["2.5-RF-12"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-884",ue:"2.5",front:"Comment réalise-t-on le test de Thompson et que signe-t-il ?",back:"Patient en procubitus, on presse le mollet ; l'absence de flexion plantaire évoque une rupture complète du tendon d'Achille.",sources:["PMC-ED-MSK-2026"],relatedIds:["2.5-RF-13"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-885",ue:"2.5",front:"Où siège le plus souvent la rupture du tendon d'Achille ?",back:"À 2 à 6 cm au-dessus de l'insertion calcanéenne, zone relativement peu vascularisée.",sources:["PMC-ED-MSK-2026"],relatedIds:["2.5-RF-13"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-886",ue:"2.5",front:"Quels tests orientent vers une lésion de la syndesmose ?",back:"Le squeeze test et le test de rotation externe : spécificité élevée, sensibilité faible.",sources:["PMC-SYNDESMOSIS-HUNT-2013","PMC-ED-MSK-2026"],relatedIds:["2.5-DX-04"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-887",ue:"2.5",front:"Où surviennent le plus souvent les fractures vertébrales de fragilité ?",back:"Au rachis thoracique et lombaire, avec un traumatisme minime ou nul.",sources:["PMC-VCF-FINDLAY-2026"],relatedIds:["2.5-RF-17"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-888",ue:"2.5",front:"Quels signes évoquent une tumeur ou une ostéomyélite devant une fracture vertébrale ?",back:"Un déficit neurologique progressif ou des signes d'infection.",sources:["PMC-VCF-FINDLAY-2026"],relatedIds:["2.5-RF-17"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-889",ue:"2.5",front:"À quoi sert l'IRM devant une fracture vertébrale suspectée ?",back:"À distinguer une fracture récente d'une déformation ancienne ou d'une atteinte tumorale.",sources:["PMC-VCF-FINDLAY-2026"],relatedIds:["2.5-RF-17"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-890",ue:"2.5",front:"Quelle cause vasculaire peut simuler une dorsalgie mécanique ?",back:"La dissection aortique : douleur brutale du milieu du dos, disproportionnée par rapport à l'examen.",sources:["PMC-AD-MIDBACK-2025"],relatedIds:["2.5-RF-21"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-891",ue:"2.5",front:"Quelle proportion des cervicalgies serait due à une pathologie grave sous-jacente ?",back:"Environ 1 %, selon une revue de guides de pratique.",sources:["PMC-NECK-REDFLAGS-2024"],relatedIds:["2.5-RF-06"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-892",ue:"2.5",front:"Quelle règle de dépistage est retenue pour les fractures post-traumatiques du rachis cervical ?",back:"La règle canadienne du rachis cervical, seule règle dont l'exactitude est documentée parmi les drapeaux rouges de la revue.",sources:["PMC-NECK-REDFLAGS-2024"],relatedIds:["2.5-RF-06"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-893",ue:"2.5",front:"Quel signe sensitif périnéal évoque un syndrome de la queue de cheval ?",back:"L'anesthésie en selle.",sources:["PMC-CES-DEFINITION-SR-2023"],relatedIds:["2.5-RF-03"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-894",ue:"2.5",front:"Quelle différence entre syndrome de la queue de cheval incomplet et avec rétention ?",back:"Le syndrome avec rétention comporte une rétention urinaire et une incontinence par regorgement ; l'incomplet n'en comporte pas.",sources:["PMC-CES-DEFINITION-SR-2023"],relatedIds:["2.5-RF-03"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-895",ue:"2.5",front:"Quels symptômes digestifs peuvent accompagner une douleur d'épaule d'origine non musculo-squelettique ?",back:"Douleur abdominale, de l'hypochondre droit ou gauche, épigastrique (données issues surtout de cas cliniques).",sources:["PUBMED-SHOULDER-GI-REDFLAGS-2022"],relatedIds:["2.5-RF-09"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-896",ue:"2.5",front:"Quand envisager l'imagerie devant une douleur d'épaule ?",back:"Pas d'imagerie systématique ; elle est réservée aux situations à risque ou sans amélioration vers 12 semaines.",sources:["PMC-SHOULDER-IMAGING-2025"],relatedIds:["2.5-RF-09"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-897",ue:"2.5",front:"Que signifie un test FADIR négatif ?",back:"La hanche est peu probable comme source de la douleur (sensibilité élevée) ; un test positif ne confirme pas le diagnostic.",sources:["PMC-HIP-GROIN-ESSKA-2026"],relatedIds:["2.5-RF-22"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-898",ue:"2.5",front:"Selon l'accord de Warwick 2016, sur quelle triade repose le diagnostic de conflit fémoro-acétabulaire ?",back:"Symptômes, signes cliniques et imagerie.",sources:["PMC-FAIS-REVIEW-2024"],relatedIds:["2.5-RF-22"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-899",ue:"2.5",front:"Le test de Spurling est-il surtout sensible ou surtout spécifique pour la radiculopathie cervicale ?",back:"Surtout spécifique : sa sensibilité est très variable selon la technique.",sources:["PMC-CERVRAD-DX-UPDATE-2026"],relatedIds:["2.5-RF-39"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-900",ue:"2.5",front:"Que vaut l'élévation de la jambe tendue pour la hernie discale lombaire ?",back:"Sensible (0,92) mais peu spécifique (0,28) en population chirurgicale.",sources:["PUBMED-LUMBAR-RADIC-COCHRANE-2010"],relatedIds:["2.5-RF-07"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-901",ue:"2.5",front:"Quels mouvements sont surtout limités dans la capsulite rétractile ?",back:"La rotation externe et l'abduction, de façon progressive, active et passive.",sources:["PMC-FROZEN-SHOULDER-CPG-2025"],relatedIds:["2.5-RF-10"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-902",ue:"2.5",front:"Quelle place pour l'échographie et l'IRM dans la capsulite rétractile ?",back:"Examens complémentaires pour écarter une autre cause ; non recommandés seuls pour poser le diagnostic.",sources:["PMC-FROZEN-SHOULDER-CPG-2025"],relatedIds:["2.5-RF-10"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-903",ue:"2.5",front:"La raideur matinale prolongée fait-elle partie des cinq critères ASAS 2009 de lombalgie inflammatoire ?",back:"Non : c'est un repère du cours, absent de la règle des 4 critères sur 5 (Sieper 2009).",sources:["PUBMED-ASAS-IBP"],relatedIds:["2.5-RF-04","2.15-DX-02"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-904",ue:"2.5",front:"Dans la myélopathie cervicale dégénérative, dans quel délai traiter pour la meilleure chance de récupération ?",back:"Dans les six mois suivant le début des symptômes (revue BMJ 2018).",sources:["PMC-DCM-BMJ-2018"],relatedIds:["2.5-RF-08","2.4-RF-03"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-905",ue:"2.5",front:"Quelle corrélation entre l'importance de la compression à l'IRM et la gravité d'une myélopathie cervicale ?",back:"Mauvaise : l'IRM montre la compression mais ne prédit pas la gravité des symptômes (revue BMJ 2018).",sources:["PMC-DCM-BMJ-2018"],relatedIds:["2.5-RF-08"],audience:"CLINICAL",difficultyBand:"ADVANCED"},{id:"FC-906",ue:"5.12",front:"Que rajoute BE-FAST à FAST ?",back:"Balance (déséquilibre) et Eyes (troubles visuels) : 14,1 % des AVC ischémiques n'avaient aucun symptôme FAST dans une étude monocentrique (Aroor 2017).",sources:["PUBMED-BEFAST-2017"],relatedIds:["5.12-RF-01","2.4-RF-02"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-907",ue:"2.6",front:"Une douleur thoracique reproduite à la palpation exclut-elle à elle seule un syndrome coronarien aigu ?",back:"Non : à Zurich (121 patients), VPN 98,1 % mais IC 89,9–99,7 % et SCA chez 11,6 % ; un signe à intégrer à l'évaluation globale.",sources:["PMC-CHEST-WALL-TENDERNESS-ACS-2015"],relatedIds:["2.6-RF-01","2.5-RF-21"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-908",ue:"2.5",front:"Selon SANJO, quand ponctionner une articulation suspecte d'être septique, et un paramètre clinique peut-il exclure le diagnostic ?",back:"Le plus vite possible ; aucun paramètre clinique ne peut exclure ou confirmer l'arthrite septique, avec ou sans fièvre (SANJO 2023).",sources:["SANJO-2023"],relatedIds:["2.5-RF-16"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-909",ue:"2.5",front:"Une CRP normale exclut-elle une arthrite septique ?",back:"Non : aucun examen sanguin n'a la sensibilité ou la spécificité pour confirmer ou exclure le diagnostic (SANJO 2023).",sources:["SANJO-2023"],relatedIds:["2.5-RF-16"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-910",ue:"2.6",front:"Les symptômes et signes d'insuffisance cardiaque suffisent-ils à poser le diagnostic ?",back:"Non : ils manquent de précision ; une preuve objective de dysfonction cardiaque est nécessaire (ESC 2021).",sources:["ESC-HF-2021"],relatedIds:["2.6-RF-03","2.6-KN-02"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-911",ue:"2.6",front:"À quoi sert une règle de probabilité clinique (Genève révisé, Wells) dans l'embolie pulmonaire ?",back:"À estimer la probabilité d'embolie en trois niveaux pour guider D-dimères et imagerie ; outil du clinicien (ESC 2019).",sources:["ESC-PE-2019"],relatedIds:["2.6-KN-03"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-912",ue:"2.7",front:"Un abdomen souple exclut-il une urgence abdominale ?",back:"Non : l'ischémie mésentérique donne une douleur sévère avec abdomen souple (voir 2.7-RF-06).",sources:["BJGPOPEN-ABDOMINAL-SIGNS-2024","AFP-ABDOMINAL-PAIN-2023"],relatedIds:["2.7-RF-01","2.7-RF-06"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-913",ue:"2.7",front:"Quel indice de choc alerte pour l'appendicite dans la revue BJGP Open 2024 ?",back:"Fréquence cardiaque divisée par pression systolique supérieure à 0,85 (une seule étude aux urgences).",sources:["BJGPOPEN-ABDOMINAL-SIGNS-2024"],relatedIds:["2.7-RF-01"],audience:"CLINICAL",difficultyBand:"ADVANCED"},{id:"FC-914",ue:"2.5",front:"Une rupture de coiffe vue à l'imagerie après 50 ans explique-t-elle forcément la douleur ?",back:"Non : de nombreuses personnes de plus de 50 ans ont des ruptures sans symptôme ; on confronte l'image à la clinique.",sources:["EBM-RC-EXAM-COMMENTARY-2013"],relatedIds:["2.5-KN-02"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-915",ue:"2.5",front:"Quand le guide JOSPT 2025 envisage-t-il l'imagerie de la coiffe ?",back:"Pas d'emblée : après 12 semaines de soins conservateurs sans succès, avec l'échographie préférée (grade F).",sources:["JOSPT-RC-TENDINOPATHY-CPG-2025"],relatedIds:["2.5-KN-02"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-916",ue:"2.4",front:"Quelle fréquence et quelle durée définissent la céphalée de tension chronique (ICHD-3) ?",back:"15 jours/mois ou plus depuis plus de 3 mois (180 jours/an ou plus).",sources:["ICHD3-TTH"],relatedIds:["2.4-DX-02"],audience:"BOTH",difficultyBand:"FOUNDATION"},{id:"FC-917",ue:"2.4",front:"Quelle durée d'une crise non traitée et quelle fréquence dans la céphalée en grappes (ICHD-3) ?",back:"15 à 180 minutes ; de une crise tous les deux jours à huit par jour.",sources:["ICHD3-CLUSTER"],relatedIds:["2.4-DX-03"],audience:"BOTH",difficultyBand:"FOUNDATION"},{id:"FC-918",ue:"2.4",front:"Quel signe pupillaire distingue un glaucome aigu à angle fermé d'une céphalée en grappes (NICE CG150) ?",back:"Pupille semi-dilatée dans le glaucome aigu, contractée (myosis) dans la céphalée en grappes.",sources:["NICE-CG150"],relatedIds:["2.4-DX-03","2.4-RF-01"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-919",ue:"2.4",front:"À partir de combien de jours par mois (3 mois ou plus) NICE CG150 fait-il évoquer une céphalée par abus médicamenteux ?",back:"10 jours ou plus pour triptans, opioïdes, ergotés et antalgiques combinés ; 15 jours ou plus pour paracétamol, aspirine et AINS.",sources:["NICE-CG150","ICHD3-MOH"],relatedIds:["2.4-DX-04"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-920",ue:"2.4",front:"Quel est le principe de prise en charge d'une céphalée par abus médicamenteux (NICE CG150) ?",back:"Retirer les médicaments de crise abusés pendant au moins 1 mois, brutalement, en prévenant d'une aggravation transitoire ; décision médicale.",sources:["NICE-CG150"],relatedIds:["2.4-DX-04"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-921",ue:"2.5",front:"Cancer passé ou actuel et signes de compression médullaire : que prévoit NICE NG234 ?",back:"Contact immédiat avec le coordinateur MSCC, urgence oncologique ; IRM dans les 24 heures (service anglais).",sources:["NICE-NG234"],relatedIds:["2.5-RF-40"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-922",ue:"2.5",front:"Cancer passé ou actuel et douleur évoquant des métastases rachidiennes, sans signe de compression : délais de NICE NG234 ?",back:"Avis spécialisé dans les 24 heures ; IRM dans la semaine si métastases suspectées sans compression.",sources:["NICE-NG234"],relatedIds:["2.5-RF-40"],audience:"BOTH",difficultyBand:"INTERMEDIATE"},{id:"FC-923",ue:"5.9",front:"Que désigne un biseau interne d'une suture dans l'enseignement ?",back:"Un bord de contact qui regarde vers l'intérieur du crâne ; externe : vers l'extérieur ; neutre : ni l'un ni l'autre.",sources:["COURS-COS-UE-5.9"],relatedIds:["5.9-KN-01"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-924",ue:"5.9",front:"V-spread : où placer la main opposée ?",back:"Sur une pièce osseuse diamétralement opposée, jamais sur une suture ; elle envoie l'impulsion vers la suture encadrée en V.",sources:["COURS-COS-UE-5.9"],relatedIds:["5.9-KN-01"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-925",ue:"5.9",front:"Sens du mouvement de l'occiput en flexion crânienne (modèle enseigné) ?",back:"Rotation postérieure autour d'un axe transversal ; angles inféro-latéraux vers le bas, condyles vers l'avant.",sources:["COURS-COS-UE-5.9"],relatedIds:["5.9-KN-02"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-927",ue:"5.9",front:"DAG maxillaire : vecteur de la traction enseignée ?",back:"Dans le prolongement des branches montantes du maxillaire : en bas et en avant, main céphalique fixe en prise bi-sphénoïdale.",sources:["COURS-COS-UE-5.9"],relatedIds:["5.9-KN-04"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-929",ue:"5.4",front:"La fusion de la synchondrose sphéno-occipitale est-elle tardive (21-25 ans) ?",back:"Non d'après l'imagerie (Alhazmi 2017) : fusion complète en moyenne vers 15-16 ans ; le chiffre 21-25 ans est celui du cours.",sources:["PMC-SOS-CLOSURE-ALHAZMI-2017"],relatedIds:["5.4-KN-01"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-930",ue:"5.5",front:"Quels sont les quatre temps de normalisation de la technique articulaire enseignée ?",back:"Mobiliser jusqu'à égalité de tension, utiliser la coopération respiratoire/musculaire, attendre l'équilibre sur la durée de l'apnée, retester.",sources:["COURS-COS-UE-5.5"],relatedIds:["5.5-KN-01"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-931",ue:"5.5",front:"Pourquoi l'iliaque est-il une exception dans cette technique ?",back:"Mauvaise congruence ilio-sacrée : sa normalisation est décrite par action directe.",sources:["COURS-COS-UE-5.5"],relatedIds:["5.5-KN-01"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-932",ue:"5.5",front:"Comment le cours nomme-t-il une dysfonction par rapport au déficit ?",back:"À l'inverse du déficit : déficit de rotation interne = dysfonction en rotation externe.",sources:["COURS-COS-UE-5.5"],relatedIds:["5.5-KN-02"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-933",ue:"5.5",front:"Lecture TFD / TFA enseignée ?",back:"TFD > TFA : dysfonction iliaque ; TFA > TFD : dysfonction sacrée ou sacro-iliaque ; égaux : physiologique.",sources:["COURS-COS-UE-5.5"],relatedIds:["5.5-KN-02"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-934",ue:"5.5",front:"Valeur des grappes de tests de provocation sacro-iliaque ?",back:"Mieux pour exclure que confirmer (RV+ environ 2,1 ; RV- 0,33 ; preuve de certitude très faible).",sources:["PUBMED-SIJ-CLUSTERS-SAUERESSIG-2021"],relatedIds:["5.5-KN-02"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-935",ue:"5.5",front:"Apnée pour une torsion antérieure ou une flexion du sacrum (technique enseignée) ?",back:"Expiratoire ; inspiratoire pour une torsion postérieure ou une extension.",sources:["COURS-COS-UE-5.5"],relatedIds:["5.5-KN-03"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-936",ue:"5.5",front:"Apnée pour une rotation postérieure de la fibula ?",back:"Inspiratoire ; expiratoire pour une rotation antérieure.",sources:["COURS-COS-UE-5.5"],relatedIds:["5.5-KN-04"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-937",ue:"7.1",front:"Principe de la technique de Jones enseignée ?",back:"Repérer un point sensible puis placer le segment dans la position de confort qui réduit sa douleur (technique de position, indirecte).",sources:["COURS-COS-UE-7.1"],relatedIds:["7.1-KN-01"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-938",ue:"7.1",front:"Correction de C1 antérieur en rotation (Jones) : par quoi commence-t-on ?",back:"Toujours par la rotation (controlatérale, centrée C0-C1-C2), puis l'inclinaison controlatérale ciblée sur C1.",sources:["COURS-COS-UE-7.1"],relatedIds:["7.1-KN-01"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-939",ue:"7.1",front:"Pourquoi le décubitus latéral est-il recommandé à l'approche du terme ?",back:"Pour éviter le syndrome de la veine cave : en décubitus dorsal, l'utérus gravide comprime la veine cave et réduit le retour veineux.",sources:["COURS-COS-UE-7.1"],relatedIds:["7.1-KN-02"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-940",ue:"7.1",front:"Saignements chez une femme enceinte : attitude enseignée ?",back:"Contre-indication à la prise en charge manuelle ; réorientation systématique vers le gynécologue ou la sage-femme.",sources:["COURS-COS-UE-7.1"],relatedIds:["7.1-KN-02"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-941",ue:"7.1",front:"Que montre la méta-analyse de Franke (2017) ?",back:"Amélioration de la douleur lombaire et de la fonction pendant et après la grossesse, avec des preuves limitées.",sources:["PUBMED-OMT-PREGNANCY-FRANKE-2017"],relatedIds:["7.1-KN-02"],audience:"BOTH",difficultyBand:"ADVANCED"},{id:"FC-942",ue:"5.10",front:"Quel résultat de l'expérience de Milgram (1963) est cité dans le cours ?",back:"65 % des sujets ont administré le choc maximal de 450 volts ; le taux baisse si la victime est proche ou l'expérimentateur absent.",sources:["COURS-COS-UE-5.10","DOI-MILGRAM-1963"],relatedIds:["5.10-KN-01"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-943",ue:"3.1",front:"Que signifie « base de sécurité » dans la théorie de l'attachement ?",back:"La figure d'attachement disponible permet à l'enfant (dès environ 6 mois) d'explorer et de revenir vers elle en cas de besoin.",sources:["COURS-COS-UE-3.1"],relatedIds:["3.1-KN-03"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-944",ue:"3.2",front:"Qu'est-ce que l'habitus chez Bourdieu ?",back:"Un système de dispositions intériorisées pendant la socialisation qui oriente préférences et manières de percevoir et d'agir.",sources:["COURS-COS-UE-3.2"],relatedIds:["3.2-KN-03"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-945",ue:"3.1",front:"Quelles sont les trois phases du syndrome général d'adaptation (Selye) ?",back:"Alarme, résistance, épuisement ; une phase de récupération suit la gestion du stresseur.",sources:["COURS-COS-UE-3.1","DOI-SELYE-1936"],relatedIds:["3.1-KN-05"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-946",ue:"3.1",front:"Comment le cours distingue-t-il peur, stress et anxiété ?",back:"Peur : émotion devant un danger réel et concret ; stress : réaction biologique à un événement ; anxiété : anticipation d'une menace future.",sources:["COURS-COS-UE-3.1"],relatedIds:["3.1-KN-05"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-947",ue:"3.1",front:"Quel critère principal sépare anxiété normale et pathologique dans l'enseignement ?",back:"Le retentissement sur les capacités d'adaptation de la personne (intensité, durée, fréquence, souffrance).",sources:["COURS-COS-UE-3.1"],relatedIds:["3.1-KN-06"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-948",ue:"3.1",front:"Quels sont les quatre temps de l'accueil d'un patient anxieux enseignés ?",back:"Relation, technique de stabilisation, éducation, orientation vers un psychologue ou un psychiatre.",sources:["COURS-COS-UE-3.1"],relatedIds:["3.1-KN-06"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-949",ue:"3.1",front:"Qui doit accompagner l'arrêt d'un antidépresseur ?",back:"Un professionnel médical, de façon progressive : un arrêt brutal expose à un syndrome de sevrage et à une rechute.",sources:["COURS-COS-UE-3.1","NICE-NG222"],relatedIds:["3.1-KN-07"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-950",ue:"3.1",front:"Quelle durée sépare le baby blues de la dépression post-partum ?",back:"Baby blues : 2 à 3 jours, jusqu'à 2 semaines ; dépression post-partum : plus de 2 semaines avec retentissement quotidien.",sources:["COURS-COS-UE-3.1","NICE-CG192"],relatedIds:["3.1-KN-08"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-951",ue:"3.1",front:"Pourquoi ne pas juger un trouble alimentaire sur l'IMC seul ?",back:"NICE NG69 recommande de ne pas décider d'un traitement sur une mesure unique comme l'IMC ou la durée de la maladie.",sources:["COURS-COS-UE-3.1","NICE-NG69"],relatedIds:["3.1-KN-09"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-952",ue:"3.1",front:"Quels sont les trois groupes de symptômes du trouble de stress post-traumatique enseignés ?",back:"Syndrome de répétition, évitement des stimuli et hyperactivation neurovégétative.",sources:["COURS-COS-UE-3.1","NICE-NG116"],relatedIds:["3.1-KN-10"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-953",ue:"3.2",front:"Qu'est-ce que le relativisme culturel (Boas) et en quoi diffère-t-il du relativisme absolu ?",back:"S'interdire de juger les autres cultures avec les critères de la sienne ; le relativisme absolu interdirait tout examen objectif.",sources:["COURS-COS-UE-3.2"],relatedIds:["3.2-KN-04"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-954",ue:"3.2",front:"Que distinguent « disease » et « illness » (Kleinman) ?",back:"Disease : problème biomédical ; illness : maladie vécue, interprétée et expliquée par le patient et son entourage.",sources:["COURS-COS-UE-3.2","DOI-KLEINMAN-1978"],relatedIds:["3.2-KN-05"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-955",ue:"5.1",front:"Comment se reconnaît l'articulation acromio-claviculaire à la palpation ?",back:"En suivant la clavicule vers le dehors : une marche d'escalier, la marche supérieure étant la clavicule et l'inférieure l'acromion.",sources:["COURS-COS-UE-5.1-MS"],relatedIds:["5.1-KN-04"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-956",ue:"2.5",front:"Que n'écartent pas des règles d'Ottawa négatives ?",back:"Une lésion de la syndesmose, d'un tendon ou d'un ligament : elles écartent une fracture de la cheville ou du médio-pied.",sources:["PUBMED-OTTAWA-ANKLE-SR-2003","PMC-ED-MSK-2026"],relatedIds:["2.5-RF-12"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-957",ue:"2.5",front:"Quel mécanisme provoque une lésion de la syndesmose ?",back:"Rotation externe excessive de la cheville, avec atteinte des ligaments tibio-fibulaires.",sources:["PMC-SYNDESMOSIS-HUNT-2013"],relatedIds:["2.5-DX-04"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-958",ue:"2.5",front:"Où siège la douleur d'une lésion de la syndesmose ?",back:"Au-dessus de l'interligne de la cheville.",sources:["PMC-ED-MSK-2026"],relatedIds:["2.5-DX-04"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-959",ue:"2.5",front:"Quel tendon fibulaire s'insère à la base du 5e métatarsien ?",back:"Le tendon du court fibulaire.",sources:["PUBMED-PERONEAL"],relatedIds:["2.5-RF-33"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-960",ue:"2.5",front:"Quelle décision revient au médecin pour une lésion de la syndesmose ?",back:"Traitement conservateur avec rééducation pour les lésions de bas grade ; stabilisation chirurgicale pour les lésions complètes et instables.",sources:["PMC-SYNDESMOSIS-HUNT-2013"],relatedIds:["2.5-DX-04"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-961",ue:"5.1",front:"Quel repère suit la crête iliaque vers l'avant en palpation du bassin ?",back:"L'épine iliaque antéro-supérieure (EIAS).",sources:["COURS-COS-UE-5.1"],relatedIds:["5.1-KN-01"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-962",ue:"5.1",front:"Où se situe le ligament inguinal en palpation ?",back:"Entre l'EIAS et l'épine du pubis.",sources:["COURS-COS-UE-5.1"],relatedIds:["5.1-KN-01"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-963",ue:"5.1",front:"Comment repérer le grand fessier ?",back:"Par l'extension de cuisse contre résistance ou le serrage des fesses.",sources:["COURS-COS-UE-5.1"],relatedIds:["5.1-KN-02"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-964",ue:"5.1",front:"Selon le cours, comment repérer le gracile ?",back:"Par la flexion du genou en appuyant le talon.",sources:["COURS-COS-UE-5.1"],relatedIds:["5.1-KN-02"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-965",ue:"5.1",front:"Quel ligament de cheville est souvent touché dans l'entorse en inversion ?",back:"Le ligament talo-fibulaire antérieur.",sources:["COURS-COS-UE-5.1"],relatedIds:["5.1-KN-03"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-966",ue:"5.1",front:"Comment repérer l'angle sternal ?",back:"En descendant de l'incisure jugulaire : il répond aux 2es cartilages costaux.",sources:["COURS-COS-UE-5.1-MS"],relatedIds:["5.1-KN-04"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-967",ue:"5.1",front:"Selon le cours, quel tendon est le plus saillant de la tabatière anatomique ?",back:"Le tendon du long extenseur du pouce.",sources:["COURS-COS-UE-5.1-MS"],relatedIds:["5.1-KN-06"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-968",ue:"5.1",front:"Comment palper le grand droit de l'abdomen ?",back:"En flexion du tronc genoux fléchis, en repérant corps, ligne blanche et intersections tendineuses.",sources:["COURS-COS-UE-5.1-MS"],relatedIds:["5.1-KN-07"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-969",ue:"5.8",front:"Dans la séquence enseignée du bilan de l'épaule, quel bilan précède le bilan ostéopathique ?",back:"Le bilan orthopédique complet, pour conseiller une prise en charge médicale en cas de suspicion pathologique.",sources:["COURS-COS-UE-5.8"],relatedIds:["5.8-KN-01"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-970",ue:"5.8",front:"Pourquoi décoapte-t-on avant de postérioriser une tête humérale en antériorité ?",back:"Pour ne pas léser la glène : le cours signale un risque de fracture.",sources:["COURS-COS-UE-5.8"],relatedIds:["5.8-KN-02"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-971",ue:"5.8",front:"Quel os du carpe est décrit comme souvent en dysfonction au poignet ?",back:"Le lunatum ; le ligament triangulaire est souvent atteint dans les chutes.",sources:["COURS-COS-UE-5.8"],relatedIds:["5.8-KN-03"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-972",ue:"5.9",front:"Quelle prise teste d'abord les deux temporaux dans l'enseignement ?",back:"La prise « papillon » à cinq doigts.",sources:["COURS-COS-UE-5.9"],relatedIds:["5.9-KN-03"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-973",ue:"5.9",front:"Quel axe de mouvement est décrit pour la mandibule dans le modèle enseigné ?",back:"Un axe vertical légèrement oblique entre canine et prémolaire.",sources:["COURS-COS-UE-5.9"],relatedIds:["5.9-KN-05"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-974",ue:"5.10",front:"Que désigne le contre-transfert selon le cours ?",back:"L'ensemble des ressentis du soignant ; en prendre conscience permet de garder la juste proximité.",sources:["COURS-COS-UE-5.10"],relatedIds:["5.10-KN-02"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-975",ue:"3.2",front:"Quel écart d'espérance de vie des hommes le cours cite-t-il entre les 5 % les plus aisés et les 5 % les plus modestes ?",back:"13 ans (84,4 ans contre 71,7 ans).",sources:["COURS-COS-UE-3.2"],relatedIds:["3.2-KN-02"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-976",ue:"3.1",front:"Quel type de conditionnement est décrit par Skinner ?",back:"Le conditionnement opérant (renforcement, punition).",sources:["COURS-COS-UE-3.1"],relatedIds:["3.1-KN-01"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-977",ue:"3.1",front:"Comment le cours définit-il l'hypocondrie ?",back:"La conviction d'une maladie grave fondée sur une interprétation erronée de symptômes.",sources:["COURS-COS-UE-3.1"],relatedIds:["3.1-KN-02"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-978",ue:"3.1",front:"Quelle différence entre assimilation et accommodation chez Piaget ?",back:"Assimiler : intégrer le nouveau au schéma ; accommoder : modifier le schéma.",sources:["COURS-COS-UE-3.1"],relatedIds:["3.1-KN-04"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-979",ue:"5.11",front:"Aucun facteur de risque et examen neurologique normal : la pathologie vasculaire cervicale est-elle exclue ?",back:"Non : les dissections spontanées surviennent sans facteur de risque ; l’anamnèse (douleur « inhabituelle ») prime.",sources:["IFOMPT-CERVICAL2020"],relatedIds:["5.11-EX-01"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-980",ue:"3.1",front:"Devant une accouchée épuisée avec dorsalgie et dévalorisation, quelle conduite est enseignée ?",back:"Poser la question, évoquer le soutien et orienter vers le médecin, la sage-femme ou un psychiatre.",sources:["COURS-COS-UE-3.1","NICE-CG192"],relatedIds:["3.1-KN-08"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-981",ue:"3.1",front:"Dans quels délais débutent le stress aigu et le stress post-traumatique ?",back:"Stress aigu : dans les 4 semaines suivant l’événement ; stress post-traumatique : début habituel dans les 3 premiers mois.",sources:["COURS-COS-UE-3.1"],relatedIds:["3.1-KN-10"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-982",ue:"3.1",front:"Que recommande NICE NG116 du débriefing psychologique centré sur l'événement ?",back:"Il n’est pas recommandé pour prévenir ou traiter le trouble ; les psychothérapies centrées sur le traumatisme le sont.",sources:["COURS-COS-UE-3.1","NICE-NG116"],relatedIds:["3.1-KN-10"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-983",ue:"3.1",front:"Comment utiliser les phases du deuil en consultation ?",back:"Comme une description très individuelle, jamais comme une norme ni un calendrier à imposer.",sources:["COURS-COS-UE-3.1","DOI-SHEAR-2015"],relatedIds:["3.1-KN-08"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-984",ue:"3.1",front:"Que faire devant des signes d'alerte d'un trouble alimentaire (restriction, aménorrhée, maigreur) ?",back:"S'abstenir de tout commentaire sur le poids, utiliser un langage non culpabilisant et orienter vers un avis médical.",sources:["COURS-COS-UE-3.1","NICE-NG69"],relatedIds:["3.1-KN-09"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-985",ue:"3.1",front:"Palpitations ou oppression chez un patient anxieux : que faut-il faire avant de conclure à l'anxiété ?",back:"Éliminer une cause somatique : l'anxiété ne se conclut pas avant.",sources:["COURS-COS-UE-3.1","NICE-CG113"],relatedIds:["3.1-KN-06"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-986",ue:"3.2",front:"Plutôt que de déduire une croyance de l'origine supposée d'un patient, que demander ?",back:"Comment il comprend et nomme son problème (modèle explicatif, Kleinman).",sources:["COURS-COS-UE-3.2","DOI-KLEINMAN-1978"],relatedIds:["3.2-KN-04"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-987",ue:"3.2",front:"Pourquoi les différences de douleur entre sexes ne prédisent-elles pas la douleur d'un individu ?",back:"Elles décrivent des populations et dépendent de multiples déterminants ; elles ne se généralisent pas à l’individu.",sources:["COURS-COS-UE-3.2","PMID-HURLEY-ADAMS-2008"],relatedIds:["3.2-KN-03"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-988",ue:"3.2",front:"Quelle limite du récit guerrier de la maladie est enseignée ?",back:"Il ne prévoit pas la récidive et ne convient pas à tous les patients.",sources:["COURS-COS-UE-3.2"],relatedIds:["3.2-KN-05"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-989",ue:"3.2",front:"Quel cadre en trois critères explique les inégalités face à une épidémie (Blumenshine, 2008) ?",back:"Exposition, susceptibilité (vulnérabilité) et accès aux soins différentiels.",sources:["COURS-COS-UE-3.2"],relatedIds:["3.2-KN-02"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-990",ue:"2.7",front:"Qu'est-ce que le signe de Murphy ?",back:"Un arrêt inspiratoire douloureux à la palpation de l'hypochondre droit, évocateur d'une inflammation vésiculaire.",sources:["NCBI-CHOLECYSTITIS"],relatedIds:["2.7-RF-02"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-991",ue:"2.7",front:"Quelles causes de pancréatite aiguë faut-il rechercher en priorité à l'anamnèse ?",back:"Lithiase biliaire, alcool et hypertriglycéridémie, avant médicaments ou geste endoscopique récent.",sources:["NCBI-PANCREATITIS"],relatedIds:["2.7-RF-03"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-992",ue:"1.6",front:"Comment reconnaît-on le syndrome du nerf interosseux antérieur ?",back:"Déficit purement moteur, signe « OK » impossible, sans aucune perte de sensibilité.",sources:["NCBI-MEDIANNERVE"],relatedIds:["1.6-DX-01"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-993",ue:"2.4",front:"Quelle anomalie l'ICHD-3 décrit-elle comme la plus significative de la céphalée de tension ?",back:"La sensibilité péricrânienne à la palpation, présente entre les crises et majorée pendant la crise.",sources:["ICHD3-TTH"],relatedIds:["2.4-DX-02"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-994",ue:"2.4",front:"Que doit contenir l'agenda des céphalées proposé par NICE CG150 ?",back:"Au moins 8 semaines : fréquence, durée, sévérité, médicaments pris et facteurs déclenchants.",sources:["NICE-CG150"],relatedIds:["2.4-DX-02"],audience:"CLINICAL",difficultyBand:"INTERMEDIATE"},{id:"FC-995",ue:"5.8",front:"Quelle précaution avant de postérioriser une tête humérale en antériorité (cours 5.8) ?",back:"Décoaptation pour ne pas léser la glène : risque de fracture signalé par le cours.",sources:["COURS-COS-UE-5.8"],relatedIds:["5.8-KN-02"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-996",ue:"5.10",front:"Quelle différence entre empathie et compassion dans le cours de relation thérapeutique ?",back:"Empathie : s'identifier à ce que ressent autrui ; compassion : partager sa souffrance.",sources:["COURS-COS-UE-5.10"],relatedIds:["5.10-KN-02"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-997",ue:"5.10",front:"Comment considérer la transposition de Milgram (1963) aux soins ?",back:"Comme une interprétation pédagogique d'un résultat expérimental précis, non une preuve clinique.",sources:["COURS-COS-UE-5.10","DOI-MILGRAM-1963"],relatedIds:["5.10-KN-01"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-998",ue:"1.7",front:"Quelle articulation du coude permet la rotation du radius ?",back:"La radio-ulnaire proximale : un pivot où le ligament annulaire maintient la tête radiale contre l'incisure radiale de l'ulna.",sources:["OPENSTAX-AP-9-6"],relatedIds:["1.7-KN-09"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-999",ue:"1.7",front:"Qu'est-ce que le labrum glénoïdal ?",back:"Un bourrelet fibrocartilagineux qui borde la cavité glénoïdale et l'approfondit légèrement.",sources:["OPENSTAX-AP-9-6"],relatedIds:["1.7-KN-08"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-1000",ue:"1.7",front:"Quel type d'articulation est l'articulation huméro-ulnaire ?",back:"Une charnière uniaxiale entre la trochlée de l'humérus et l'incisure trochléaire de l'ulna.",sources:["OPENSTAX-AP-9-6"],relatedIds:["1.7-KN-09"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-1001",ue:"1.10",front:"Quels pigments influencent la couleur de la peau ?",back:"La mélanine, le carotène et l'hémoglobine.",sources:["OPENSTAX-AP-5-1"],relatedIds:["1.10-KN-01"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-1002",ue:"5.1",front:"Quelle contraction demande-t-on pour palper l'infra-épineux dans sa fosse ?",back:"Une rotation externe de l'épaule : l'infra-épineux est rotateur latéral du bras.",sources:["COURS-COS-UE-5.1-MS","OPENSTAX-AP-11-5"],relatedIds:["5.1-KN-05"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-1003",ue:"5.1",front:"Selon le cours, comment fait-on ressortir les fibres supérieures du grand pectoral ?",back:"Bras à 90° de flexion et en rotation interne : adduction avec élévation du bras contre résistance.",sources:["COURS-COS-UE-5.1-MS"],relatedIds:["5.1-KN-05"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-1004",ue:"5.1",front:"Selon le cours, quelle consigne aide à palper le grand dorsal ?",back:"En procubitus, mains au bord de la table au-dessus de la tête : se tracter sur la table.",sources:["COURS-COS-UE-5.1-MS"],relatedIds:["5.1-KN-05"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-1005",ue:"1.10",front:"Pourquoi la fovéa est-elle la zone la plus précise de la rétine ?",back:"Elle ne contient que des photorécepteurs, sans cellules de soutien ni vaisseaux sur le trajet de la lumière.",sources:["OPENSTAX-AP-14-1"],relatedIds:["1.10-KN-05"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-1006",ue:"1.10",front:"Quel nerf innerve le muscle releveur de la paupière supérieure ?",back:"Le nerf oculomoteur (III).",sources:["OPENSTAX-AP-14-1"],relatedIds:["1.10-KN-05"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-1007",ue:"1.7",front:"Genou fléchi, quel ligament empêche le fémur de glisser vers l’avant sur le tibia ?",back:"Le ligament croisé postérieur, le plus solide des deux croisés.",sources:["OPENSTAX-AP-9-6"],relatedIds:["1.7-KN-11"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-1008",ue:"1.7",front:"Qu'est-ce qu'une gaine tendineuse ?",back:"Un sac conjonctif lubrifié qui entoure un tendon là où il croise une articulation.",sources:["OPENSTAX-SYNOVIAL-JOINTS"],relatedIds:["1.7-KN-01"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-1009",ue:"1.7",front:"Disque articulaire et ménisque : quelle différence ?",back:"Tous deux fibrocartilagineux : le disque est petit et ovale, le ménisque plus grand et en forme de C.",sources:["OPENSTAX-SYNOVIAL-JOINTS"],relatedIds:["1.7-KN-01"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-1010",ue:"1.7",front:"Donnez un exemple d'articulation condylienne (ellipsoïde) et son nombre d'axes.",back:"Radio-carpienne ou métacarpo-phalangiennes : biaxiales.",sources:["OPENSTAX-SYNOVIAL-JOINTS"],relatedIds:["1.7-KN-01"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-1011",ue:"1.7",front:"D'où part le ligament collatéral radial du coude et avec quoi se confond-il ?",back:"Il naît de l'épicondyle latéral de l'humérus et se confond avec le ligament annulaire.",sources:["OPENSTAX-AP-9-6"],relatedIds:["1.7-KN-09"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-1012",ue:"1.7",front:"Quels mouvements les ligaments collatéraux du coude empêchent-ils ?",back:"Les mouvements latéraux (d'un côté à l'autre) et l'hyperextension.",sources:["OPENSTAX-AP-9-6"],relatedIds:["1.7-KN-09"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-1013",ue:"1.7",front:"Quel risque une fracture du col fémoral fait-elle courir à la tête fémorale ?",back:"Une atteinte de sa vascularisation peut entraîner une nécrose de l'os et du cartilage.",sources:["OPENSTAX-AP-9-6"],relatedIds:["1.7-KN-10"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-1014",ue:"1.7",front:"Quelles bourses limitent les frottements des tendons de la coiffe des rotateurs ?",back:"Les bourses subacromiale et subscapulaire.",sources:["OPENSTAX-AP-9-6"],relatedIds:["1.7-KN-08"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-1015",ue:"1.7",front:"Quels ligaments renforcent la capsule gléno-humérale ?",back:"Le ligament coraco-huméral et trois ligaments gléno-huméraux antérieurs, tous faibles.",sources:["OPENSTAX-AP-9-6"],relatedIds:["1.7-KN-08"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-1016",ue:"1.7",front:"Sur quels os les ménisques du genou sont-ils fixés ?",back:"Sur les condyles tibiaux ; ils ne sont pas fixés au fémur.",sources:["OPENSTAX-AP-9-6"],relatedIds:["1.7-KN-11"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-1017",ue:"1.7",front:"Dans quelle position du genou une rotation de la jambe est-elle possible ?",back:"Genou fléchi ; pas en extension.",sources:["OPENSTAX-AP-9-6"],relatedIds:["1.7-KN-11"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-1018",ue:"1.7",front:"Pourquoi certaines lésions méniscales cicatrisent-elles mal ?",back:"Certaines zones de chaque ménisque n'ont pas d'apport artériel.",sources:["OPENSTAX-AP-9-6"],relatedIds:["1.7-KN-11"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-1019",ue:"1.7",front:"Choc latéral sur le genou en extension : quelle séquence de lésions forme la « triade terrible » ?",back:"Ligament collatéral tibial, puis ménisque médial, puis ligament croisé antérieur.",sources:["OPENSTAX-AP-9-6"],relatedIds:["1.7-KN-11"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-1020",ue:"1.7",front:"Qu'est-ce qu'un muscle fixateur ?",back:"Un synergiste qui stabilise l'os d'origine de l'agoniste.",sources:["OPENSTAX-MUSCLE-LEVERS"],relatedIds:["1.7-KN-02"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-1021",ue:"1.7",front:"Flexion du coude : quel agoniste, quel antagoniste ?",back:"Agoniste : biceps brachial ; antagoniste : triceps brachial.",sources:["OPENSTAX-MUSCLE-LEVERS"],relatedIds:["1.7-KN-02"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-1022",ue:"1.5",front:"Qu'est-ce qu'une membrane séreuse et où la trouve-t-on ?",back:"Une membrane épithéliale (mésothélium sur du conjonctif) qui tapisse les cavités closes : plèvres, péricarde, péritoine.",sources:["OPENSTAX-AP-4-1"],relatedIds:["1.5-KN-05"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-1023",ue:"1.5",front:"Que libèrent les fibroblastes de la membrane synoviale ?",back:"De l'hyaluronane, qui retient l'eau pour former le liquide synovial.",sources:["OPENSTAX-AP-4-1"],relatedIds:["1.5-KN-05"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-1024",ue:"1.8",front:"Quel effet une sténose valvulaire a-t-elle sur la postcharge ?",back:"Elle l'augmente : la valve est plus difficile à ouvrir.",sources:["OPENSTAX-AP-19-4"],relatedIds:["1.8-KN-03"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-1025",ue:"1.8",front:"Quel effet une hausse du calcium sanguin a-t-elle sur le cœur ?",back:"Elle augmente la fréquence cardiaque et la contractilité.",sources:["OPENSTAX-AP-19-4"],relatedIds:["1.8-KN-03"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-1026",ue:"1.8",front:"Que traduit l'incisure dicrote d'un tracé de pression artérielle ?",back:"Le bref reflux de sang vers le cœur quand la pression ventriculaire passe sous la pression artérielle, juste avant la fermeture des valves sigmoïdes.",sources:["OPENSTAX-AP-19-3"],relatedIds:["1.8-KN-01"],audience:"STUDENT",difficultyBand:"FOUNDATION"},{id:"FC-1027",ue:"2.6",front:"Palpitations brutales suivies immédiatement d'une perte de connaissance : que faut-il évoquer ?",back:"Une syncope d'origine cardiaque (ESC 2018) : évaluation médicale urgente.",sources:["ESC-SYNCOPE-2018"],relatedIds:["2.6-RF-05"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-1028",ue:"2.6",front:"Perte de connaissance : quels éléments imposent une évaluation cardiovasculaire urgente selon NICE CG109 ?",back:"Survenue à l'effort, antécédent familial de mort subite cardiaque avant 40 ans ou cardiopathie héréditaire, essoufflement nouveau ou inexpliqué, souffle cardiaque, insuffisance cardiaque, anomalie ECG.",sources:["NICE-CG109"],relatedIds:["2.6-RF-05"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-1029",ue:"2.6",front:"Pouls irrégulier chez un patient suspect de fibrillation auriculaire : quel examen pose le diagnostic ?",back:"Un ECG 12 dérivations (NICE NG196) ; la palpation seule ne suffit pas.",sources:["NICE-NG196"],relatedIds:["2.6-RF-05"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-1030",ue:"2.6",front:"Malaise vagal simple : quels sont les 3 « P » de NICE CG109 ?",back:"Posture (station debout prolongée), facteurs Provoquants (douleur, geste médical), Prodromes (sueurs, sensation de chaleur).",sources:["NICE-CG109"],relatedIds:["2.6-RF-05"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-1031",ue:"2.14",front:"Quels signes après un contact imposent le retrait immédiat du terrain (consensus d'Amsterdam) ?",back:"Perte de connaissance réelle ou suspectée, crise convulsive, posture tonique, ataxie ou trouble de l'équilibre, confusion, changement de comportement, amnésie.",sources:["BJSPORTS-CONCUSSION23"],relatedIds:["2.14-RF-01"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-1032",ue:"2.14",front:"Retour au sport après commotion : comment progresse la stratégie ?",back:"Par paliers guidés par les symptômes, chacun durant en général au moins 24 heures ; feu vert écrit d'un professionnel de santé avant le retour sans restriction.",sources:["BJSPORTS-CONCUSSION23"],relatedIds:["2.14-RF-01"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-1033",ue:"2.14",front:"Après un choc à la tête, quels signes justifient une orientation vers un service d'urgences (NICE NG232) ?",back:"Notamment : perte de connaissance, amnésie, céphalée persistante, vomissements, crise convulsive, déficit neurologique focal, traitement anticoagulant, intoxication.",sources:["NICE-NG232"],relatedIds:["2.14-RF-01"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-1034",ue:"2.14",front:"REDs : qui pose le diagnostic ?",back:"Un médecin compétent en REDs, avec les informations d'une équipe multidisciplinaire, après exclusion des autres causes de chaque signe.",sources:["BJSPORTS-REDS23"],relatedIds:["2.14-RF-03"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-1035",ue:"2.14",front:"Quelle est la cause sous-jacente du REDs ?",back:"Une faible disponibilité énergétique problématique : apports insuffisants par rapport à la dépense liée à l'exercice.",sources:["BJSPORTS-REDS23"],relatedIds:["2.14-RF-03"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-1036",ue:"2.4",front:"Personne épileptique : quand une crise convulsive devient-elle une urgence médicale (NICE NG217) ?",back:"Dès qu'elle dure plus de 2 minutes au-delà de sa durée habituelle ; à 5 minutes ou plus, c'est un état de mal convulsif.",sources:["NICE-NG217"],relatedIds:["2.4-RF-04"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-1037",ue:"2.7",front:"Un signe de Murphy positif suffit-il à diagnostiquer une cholécystite aiguë ?",back:"Non : aucun signe isolé ne suffit (WSES 2020) ; le diagnostic combine anamnèse, examen, biologie et imagerie.",sources:["WSES-ACC-2020"],relatedIds:["2.7-RF-02"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"},{id:"FC-1038",ue:"2.5",front:"Suspicion de synovite persistante : quand l'avis spécialisé est-il urgent (NICE NG100) ?",back:"Petites articulations des mains ou des pieds touchées, plus d'une articulation touchée, ou 3 mois ou plus depuis le début, même avec une biologie normale.",sources:["NICE-NG100"],relatedIds:["2.5-RF-15"],audience:"STUDENT",difficultyBand:"INTERMEDIATE"}],i=e;export{i as flashcards};
